import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`ACP 執行環境控制項，可用於啟用分派、選擇後端、限制允許的目標代理程式，以及選擇串流回合的投射行為。`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`ACP 允許的代理程式`},help:{"v1-f2mw0d-3a":`允許用於 ACP 執行環境工作階段的 ACP 目標代理程式 ID 允許清單。留空表示不施加額外的允許清單限制。`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP 後端`},help:{"v1-1s1l6bz-2v":`預設的 ACP 執行環境後端 ID（例如：acpx）。必須與已註冊的 ACP 執行環境外掛程式後端相符。`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACP 預設代理程式`},help:{"v1-7donnu-2c":`建立 ACP 執行個體時，若未明確指定目標，則使用此備用 ACP 目標代理程式 ID。`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`啟用 ACP 分派`},help:{"v1-1ug9t9m-3w":`ACP 工作階段回合的獨立分派開關（預設值：true）。設為 false 可保留 ACP 命令的可用性，同時阻止 ACP 回合執行。`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`啟用 ACP`},help:{"v1-1uonl1v-2a":`全域 ACP 功能開關。除非已設定 ACP 執行環境與原則，否則請保持停用。`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP 備援後端`},help:{"v1-1wvdifq-5m":`當主要後端因 UNAVAILABLE 而失敗時（例如：觸及速率限制／配額耗盡），依序嘗試的備援 ACP 後端 ID 清單。每個項目都必須對應至已註冊的 ACP 執行階段外掛後端。`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`ACP 執行階段安裝命令`},help:{"v1-1jjuv9m-39":"選用的操作人員安裝／設定命令，當 ACP 後端未完成串接時，由 `/acp install` 和 `/acp doctor` 顯示。"}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP 串流`},help:{"v1-1bka5p-2v":`ACP 串流投影控制項，用於設定區塊大小、中繼資料可見性，以及去除重複內容後的傳遞行為。`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`ACP 串流傳遞模式`},help:{"v1-19gdmx1-3s":`ACP 傳遞方式：live 以串流逐步傳遞投影輸出；final_only 則緩衝所有 ACP 投影輸出，直到回合終止事件發生。`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`ACP 串流重複抑制`},help:{"v1-manh32-3d":`設為 true（預設值）時，抑制同一回合中重複的 ACP 狀態／工具投影行，同時保持原始 ACP 事件不變。`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`ACP 串流標籤可見性`},help:{"v1-1ybhx22-34":`依各個 sessionUpdate 設定 ACP 投影的可見性覆寫值（例如 usage_update、available_commands_update）。`}},agents:{label:{"v1-1sa8ub3-6":`代理程式`},help:{"v1-2rc4v8-55":`代理程式執行階段設定的根節點。根層級的同層節點負責基礎架構與跨代理程式的預設值；agents.defaults 負責代理程式迴圈行為；代理程式項目可在支援的情況下覆寫其中任一設定。`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`代理預設設定`},help:{"v1-1af7k5b-5a":`代理程式繼承的共用預設設定，除非在 agents.entries 的個別項目中覆寫。使用預設設定可確保一致的基本行為，並減少各代理程式的重複設定。`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`驗證繼承目標`},help:{"v1-2d16wl-2x":`為維持升級相容性而指定的繼承認證資料存放區擁有者，在認證資料依代理程式分別移轉前使用。`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`驗證繼承擁有者`},help:{"v1-1a1s7nm-4s":`預設標記停用後，仍以其舊版認證資料存放區作為繼承來源的代理程式。若原擁有者不是 main，系統會在升級時自動寫入。`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`啟動載入字元數上限`},help:{"v1-drlo3i-37":`每個工作區啟動檔案注入系統提示的字元數上限，超出部分將截斷（預設：20000）。`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`啟動載入總字元數上限`},help:{"v1-1evwsjb-2c":`所有注入的工作區啟動檔案的總字元數上限（預設：60000）。`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`壓縮`},help:{"v1-1qxdwz8-5p":`當上下文接近 token 上限時的壓縮行為，包括壓縮策略及壓縮前的記憶寫入行為。當長時間執行的工作階段需要在有限的上下文視窗內維持穩定的連貫性時，可使用此設定。`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`內嵌自動壓縮`},help:{"v1-1et7vwu-5l":`啟用內嵌的主動自動壓縮（預設：true）。設為 false 可停止由閾值觸發的內嵌壓縮，同時保留 OpenClaw 溢位復原、預檢壓縮及手動 /compact 功能。`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`壓縮識別碼原則`},help:{"v1-hby01l-4l":`壓縮摘要的識別碼保留原則："strict" 會在開頭加入內建的不透明識別碼保留指引（預設），而 "off" 會停用此前綴。`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`壓縮時保留的近期詞元數`},help:{"v1-tgysub-5h":`壓縮期間，從最近的對話視窗保留的最低詞元預算。使用較高值可維持當前上下文的連貫性，較低值則可保留更多較早的歷史記錄。`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`壓縮作用中對話記錄大小閾值`},help:{"v1-u715n1-90":`觸發一般預檢本機壓縮的位元組閾值。當模型可見的對話記錄視窗（自上次壓縮或重設以來）達到此大小時便會觸發，可指定為位元組數或 "20mb" 之類的字串。設為 0 或不設定即可停用。這也會限制 Codex app-server 原生 rollout 對話記錄的大小；超過大小限制的原生對話串會重新開始。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`壓縮前記憶寫入`},help:{"v1-18q0ve9-55":`壓縮前的記憶寫入設定，讓代理在大幅壓縮前執行記憶寫入。長時間工作階段建議保持啟用，以便在大量裁剪前持久保存重要上下文。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`啟用壓縮前記憶寫入`},help:{"v1-9xllgp-5o":`啟用壓縮前記憶寫入，在執行階段接近 token 上限並大幅縮減歷程記錄之前執行。除非您刻意要在受限環境中停用記憶寫入的副作用，否則請保持啟用。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`壓縮前記憶寫入的對話記錄大小門檻`},help:{"v1-1rzov1e-93":`當模型可見的對話記錄視窗達到此門檻時，強制執行壓縮前記憶寫入（以位元組數或 "2mb" 之類的字串指定）。壓縮後，此範圍包含保留的尾端記錄與後續對話回合，而不包含已捨棄的歷程記錄。即使 token 計數器未及時更新，也可利用此設定避免長時間工作階段停滯；設為 0 即可停用。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`壓縮前記憶寫入的模型覆寫`},help:{"v1-1r3ctyu-7w":`選用的供應商／模型覆寫設定，僅用於壓縮前記憶寫入回合。若擷取持久記憶時應避免使用目前工作階段的付費模型，可將此項設為 ollama/qwen3:8b 等本機模型。此覆寫會嚴格使用指定的模型，不會繼承目前模型的備援鏈。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`壓縮前記憶寫入的軟性門檻`},help:{"v1-1dqo2l1-5c":`距離壓縮觸發點的門檻差距（以 token 數計），達到時便會執行壓縮前記憶寫入。提早觸發可讓資料保存更可靠；縮小差距則可降低寫入頻率。`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`壓縮回合中預檢`},help:{"v1-am6gbh-6x":`選用的嵌入式 OpenClaw 工具迴圈預檢，可在附加工具結果後、下一次模型呼叫前，偵測上下文容量壓力。啟用後，OpenClaw 會重用現有的預檢復原機制，在重試前截斷工具結果或壓縮上下文。`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`啟用壓縮回合中預檢`},help:{"v1-engbwe-5u":`為嵌入式 OpenClaw 工具迴圈啟用結構化的回合中上下文容量壓力檢查。預設值：false。除非大量使用工具的長時間工作階段在正常的回合結束壓縮執行前就發生上下文溢位，否則請保持停用。`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`壓縮模式`},help:{"v1-1unahwc-76":`壓縮策略模式："safeguard"（未設定時實際採用的預設值）會套用防護機制以保留近期上下文，而 "default" 則使用不含這些防護機制的基本摘要方式。只有在 safeguard 摘要方式對您的供應商造成問題時，才設定為 "default"。`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`壓縮模型覆寫`},help:{"v1-cfeys9-6q":`選用的供應商／模型或已設定的單獨別名，僅用於壓縮摘要。單獨別名會在派送前解析；若已設定的模型 ID 字面值與別名衝突，則以該模型 ID 為優先。保持未設定即可繼續使用主要代理程式模型。`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`壓縮時通知使用者`},help:{"v1-lvymm8-bv":`啟用後，會在壓縮開始與完成時，向使用者傳送簡短的上下文維護通知（例如「🧹 正在壓縮上下文...」與「🧹 壓縮完成」）；若壓縮前的記憶寫入已耗盡重試次數，導致回覆以降級狀態繼續，也會傳送通知（例如「⚠️ 記憶維護暫時失敗；正在繼續回覆。」）。預設停用，讓上下文維護保持靜默且不造成干擾。`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`壓縮後的上下文區段`},help:{"v1-1n0ln2u-5f":`選擇要在壓縮後重新注入的 AGENTS.md H2/H3 區段名稱。保持未設定或設為 [] 可停用重新注入。明確設為 ["Session Startup", "Red Lines"] 可啟用舊版預設的兩個區段。`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`壓縮後索引同步`},help:{"v1-ekpjeq-6l":`控制壓縮後的工作階段記憶重新索引模式："off"、"async" 或 "await"（預設為 "async"）。使用 "await" 可最大程度確保資料即時更新，使用 "async" 可降低壓縮延遲；僅在其他機制已處理工作階段記憶同步時，才使用 "off"。`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`壓縮提供者`},help:{"v1-kiwk91-86":`用於產生摘要的已註冊壓縮提供者外掛程式 ID。設定此值且提供者已註冊時，會呼叫其 summarize() 方法，而非內建的 summarizeInStages 處理流程。提供者失敗時，會回退至內建機制。保持未設定即可使用預設的內建摘要功能。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`壓縮品質防護`},help:{"v1-u9ognp-4k":`防護式壓縮摘要的品質稽核重試設定。防護模式預設啟用此功能；設定 enabled: false 可略過摘要稽核與重新產生。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`啟用壓縮品質防護`},help:{"v1-1xk2vt3-36":`啟用防護式壓縮的摘要品質稽核與重新產生重試。預設值：防護模式下為 true。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`壓縮品質防護重試次數上限`},help:{"v1-n7l46y-3y":`防護式摘要品質稽核失敗後，重新產生的重試次數上限。使用較小的值可限制額外延遲與詞元成本。`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`壓縮時保留的最近對話輪數`},help:{"v1-y34ihi-5k":`逐字保留、不納入防護式摘要的最近使用者／助理對話輪數（預設值：3）。提高此值可完整保留最近對話的確切內容脈絡，降低則可最大化壓縮節省量。`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`壓縮思考層級`},help:{"v1-1vafgaw-g1":`僅用於內嵌 OpenClaw 壓縮摘要的思考等級："off"、"minimal"、"low"、"medium"、"high"、"xhigh"、"adaptive"、"max"、"ultra" 或 "inherit"。預設採用供應商的壓縮偏好設定，否則使用 "low"；原生本機 Ollama 偏好 "off"。設為 "inherit" 可沿用工作階段的等級。明確指定的設定會覆寫供應商預設值，且所選等級會限制在實際壓縮模型／執行環境支援的範圍內。原生 Codex app-server 壓縮會忽略此設定，因為其壓縮請求不支援針對個別作業覆寫思考等級，OpenClaw 也會記錄警告。`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`壓縮逾時（秒）`},help:{"v1-2bhn29-7m":`每次內建壓縮模型請求的安全時限，以秒為單位（預設：180）。多階段壓縮會在每個依序執行的請求開始時重設時限，因此整個壓縮流程可能耗時更久；由外掛程式負責的壓縮則對整個作業套用單一時限。`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`上下文注入`},help:{"v1-u18x0-7u":`控制嵌入式執行環境中的工作區啟動檔案注入："always" 使用正常注入（預設值），"continuation-skip" 會在記錄完整啟動回合後，略過符合條件的接續回合，而 "never" 則停用注入。此設定不控制由 CLI 支援的提示準備作業。`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`預設上下文限制`},help:{"v1-1coeez8-5d":`針對特定大量摘錄與注入提示區塊，設定每個代理程式上下文的用量預算預設值。使用此設定可調整有限制的讀取／注入大小，而不會重新開啟任何無限制的呼叫路徑。`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`預設 memory_get 字元數上限`},help:{"v1-1qb40qv-4v":`memory_get 在加入截斷中繼資料與接續通知前，預設回傳的字元數上限。提高此值可接近舊版較長的摘錄內容，但仍應維持合理上限。`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`壓縮後預設字元數上限`},help:{"v1-64qo8g-5r":`壓縮後重新整理上下文並注入內容時，預設從 AGENTS.md 保留的字元數上限。降低此值可減少壓縮後復原的成本；若代理程式依賴較長的啟動指引，則可提高此值。`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`工作目錄`},help:{"v1-1y8wlxn-6a":`代理程式執行回覆時使用的工作目錄，與工作區啟動初始化及記憶檔案分開。代理程式專屬的 cwd 與工作階段衍生的 cwd 具有較高優先順序。支援 ~ 與相對路徑；使用不同的 cwd 時，必須在沙箱外執行。`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`決策模型`},help:{"v1-7nd7ze-64":`選用的供應商／模型，用於具型別的選項、評分和布林機率。未設定或留空即停用決策呼叫。支援此功能的外掛程式會將限定範圍的任務佐證資料傳送至此供應商；聊天和輔助模型不受影響。`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`內嵌式 OpenClaw`},help:{"v1-1keek32-3k":`內嵌式 OpenClaw 執行器的安全強化控制項，用於管理 OpenClaw 工作階段如何信任及套用工作區本機的代理程式設定。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`網路安全政策容錯移轉`},help:{"v1-xvv6wl-2r":`在內嵌執行環境中，對於可安全重播且因 OpenAI 網路安全政策而遭拒絕的請求，自動升級至 Daybreak 處理。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`網路安全政策容錯移轉冷卻時間`},help:{"v1-16smtrl-25":`在目前工作階段中，略過無法使用的升級目標的持續時間。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`網路安全政策容錯移轉模式`},help:{"v1-rzsd2b-2h":`啟用自動升級處理（"auto"，預設值），或在供應商拒絕時終止處理（"off"）。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`網路安全政策容錯移轉模型`},help:{"v1-1aaj8nn-1t":`用於自動升級處理網路安全政策拒絕請求的供應商／模型目標。`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`內嵌式 OpenClaw 執行契約`},help:{"v1-1fch2ig-66":`內嵌式 OpenClaw 執行契約："default" 保留標準執行器行為，而 "strict-agentic" 會為支援的 OpenAI/OpenAI Codex GPT-5 系列執行啟用結構化計畫追蹤，以及使用者不可見的回合復原。`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`內嵌式 OpenClaw 專案設定政策`},help:{"v1-fdyy04-65":'內嵌式 OpenClaw 處理工作區本機 `.openclaw/settings.json` 的方式："sanitize"（預設）會移除 shellPath/shellCommandPrefix，"ignore" 會完全停用專案設定，而 "trusted" 會原樣套用專案設定。'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`實驗性代理程式旗標`},help:{"v1-cvv5cl-2w":`代理程式的實驗性預設旗標。除非您有意測試預覽功能，否則請保持關閉。`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`啟用精簡本機模型模式（實驗性）`},help:{"v1-gj06u6-7b":`進階疑難排解覆寫設定，可限制 browser、automations 和 message 等選用工具。預設關閉；支援的本機執行環境會使用自動 Tool Search，不受此限制。明確允許使用的工具及必要的傳送工具會予以保留。`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`代理程式預設快速模式`},help:{"v1-zv4y98-2z":`代理程式迴圈的預設快速模式策略（"auto"、true 或 false）。個別代理程式項目可覆寫此設定。`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`心跳代理程式`},help:{"v1-1jynxej-3w":`未設定個別代理程式心跳時，負責執行背景心跳的代理程式。保持未設定即可保留已設定的預設路由。`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`心跳直接傳送策略`},help:{"v1-nhyxa9-41":`控制心跳是否可傳送至直接對話／私訊："allow"（預設）允許傳送私訊，而 "block" 會阻止傳送至直接對話目標。`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`心跳逾時（秒）`},help:{"v1-1se21py-5f":`心跳代理回合在中止前允許執行的最長時間，以秒為單位。若留空，會使用已設定的 agents.defaults.timeoutSeconds；否則會使用心跳間隔，最長為 600 秒。`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`擬人延遲上限（毫秒）`},help:{"v1-vnmvli-1m":`自訂 humanDelay 的延遲上限，以毫秒為單位（預設：2500）。`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`擬人延遲下限（毫秒）`},help:{"v1-5nrtr5-1l":`自訂 humanDelay 的延遲下限，以毫秒為單位（預設：800）。`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`擬人延遲模式`},help:{"v1-k7hyg3-1n":`區塊回覆的延遲方式（"off"、"natural"、"custom"）。`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`圖片最大尺寸（像素）`},help:{"v1-vju8x-2u":`清理對話記錄或工具結果中的圖片酬載時，圖片的最大邊長，以像素為單位（預設：1200）。`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`備援圖片模型`},help:{"v1-1kgx5i9-1b":`依順序排列的備援圖片模型（provider/model）。`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`圖片模型`},help:{"v1-dstqyh-2c":`當主要模型不支援圖片輸入時使用的選用圖片模型（provider/model）。`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`圖片品質`},help:{"v1-1uyxc5s-6u":`影像工具的媒體壓縮偏好設定："auto" 會依供應商／模型的限制及影像數量自動調整，"efficient" 可節省 token 和位元組，"balanced" 維持目前的折衷設定，而 "high" 則為螢幕截圖和文件影像保留更多細節。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`影像生成備援模型`},help:{"v1-oljfk4-1m":`依順序排列的影像生成備援模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`影像生成模型`},help:{"v1-g4yw0h-2o":`共用影像生成功能使用的選用影像生成模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`影像生成逾時時間（毫秒）`},help:{"v1-9yesfj-31":`image_generate 呼叫向供應商發出請求的預設逾時時間，以毫秒為單位。各次呼叫的 timeoutMs 會覆寫此設定。`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`音樂生成備援模型`},help:{"v1-wyg9xe-1m":`依順序排列的音樂生成備援模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`音樂生成模型`},help:{"v1-xs1e2h-2o":`共用音樂生成功能使用的選用音樂生成模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`影片生成備援模型`},help:{"v1-wpbf1e-1m":`依序使用的備援影片生成模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`影片生成模型`},help:{"v1-hfmlbl-2o":`共用影片生成功能使用的選用影片生成模型（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`影片生成逾時時間（毫秒）`},help:{"v1-1bqj80s-4i":`video_generate 呼叫的預設供應商請求逾時時間，以毫秒為單位。每次呼叫的 timeoutMs 會覆寫此值，而此值會覆寫供應商設定的預設值。`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`備援模型`},help:{"v1-t4djq2-24":`依序使用的備援模型（provider/model）。主要模型失敗時使用。`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`主要模型`},help:{"v1-1i8a1v4-v":`主要模型（provider/model）。`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`模型政策`},help:{"v1-z0txb7-2e":`明確指定模型覆寫政策。省略此設定或將 allow 留空，即可允許使用任何模型。`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`允許的模型`},help:{"v1-1fqace-3x":`允許用於模型覆寫的參照。接受別名、完整的 "provider/model" 參照，以及 "openai/*" 等供應商萬用字元。留空即可允許使用任何模型。`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`模型`},help:{"v1-13cvq23-4i":`已設定的模型目錄與各模型設定。項目提供別名、參數、執行階段中繼資料及 Code Mode 覆寫設定；不會限制模型覆寫。`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`預設代理程式模型執行環境`},help:{"v1-6km9kx-41":`預設代理程式的選用個別模型執行環境策略。可用來設定特定模型的執行環境例外，而非設定整個代理程式的執行環境。`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`預設代理程式模型執行環境 ID`},help:{"v1-1co96w7-4a":`預設代理程式的模型執行環境 ID："openclaw"、"auto"、已註冊的外掛程式執行框架 ID（例如 "codex"），或支援的 CLI 後端別名（例如 "claude-cli"）。`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`程式碼模式`},help:{"v1-rsdl5o-6x":`此特定供應商／模型的 OpenClaw 程式碼模式：開啟會強制啟用，關閉會停用，預設則沿用 tools.codeMode.enabled。代理程式專屬的啟用設定具有優先權。這不會變更所選的執行環境或 Codex 原生程式碼模式。`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`模型選擇範圍`},help:{"v1-sj8owq-bl":`聊天命令與 Gateway 工作階段模型更新未明確指定範圍時使用的範圍："session"（預設）僅變更目前的工作階段，"agent" 也會更新該代理程式的主要模型，"global" 則還會更新共用的 agents.defaults.model 備援模型。明確指定的範圍旗標具有優先權；寫入已設定的預設值需要擁有者／管理員權限。Telegram 回呼選擇器與內嵌的本機 TUI 仍僅作用於工作階段。`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`PDF 大小上限（MB）`},help:{"v1-1uig1dr-1u":`PDF 工具允許的 PDF 檔案大小上限，以 MB 為單位（預設：10）。`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`PDF 頁數上限`},help:{"v1-11na7hp-1y":`PDF 工具可處理的 PDF 頁數上限（預設：20）。`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`PDF 備援模型`},help:{"v1-89ebd8-19":`依序使用的 PDF 備援模型（provider/model）。`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF 模型`},help:{"v1-2ktkxt-2y":`PDF 分析工具使用的選用 PDF 模型（provider/model）。預設使用 imageModel，其次使用工作階段模型。`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`儲存庫根目錄`},help:{"v1-j3sh74-2h":`顯示於系統提示詞執行階段資訊列的選用儲存庫根目錄（覆寫自動偵測結果）。`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`沙箱瀏覽器 CDP 來源連接埠範圍`},help:{"v1-1jkowdc-2b":`用於容器邊界 CDP 輸入流量的選用 CIDR 允許清單（例如 172.21.0.1/32）。`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`沙箱瀏覽器網路`},help:{"v1-8m74ud-5w":`沙箱瀏覽器容器使用的 Docker 網路（預設：openclaw-sandbox-browser）。請使用專用的預設網路或自訂橋接網路；不支援 "none"，因為瀏覽器控制需要已發布的 CDP 連接埠。`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`允許沙箱 Docker 加入容器命名空間`},help:{"v1-qm39de-4c":`危險的緊急覆寫設定，允許沙箱 Docker 使用 container:<id> 網路模式。這會加入另一個容器的命名空間，並削弱沙箱隔離效果。`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`沙箱 Docker GPU`},help:{"v1-jj0yhw-4k":`傳遞給 --gpus 的選用 Docker GPU 直通值，例如 "all" 或 "device=GPU-uuid"。需要相容的主機執行環境，例如 NVIDIA Container Toolkit。`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`舊版工作階段儲存目標`},help:{"v1-1xkej6i-2g":`為已停用的 main-agent 資料列及固定的舊版工作階段儲存區指定擁有者，以維持升級相容性。`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`舊版工作階段儲存區擁有者`},help:{"v1-ommm7e-5w":`預設標記停用後，擁有已停用的 main-agent 資料列，或固定舊版工作階段儲存區中未限定範圍資料列的代理程式。若原擁有者不是 main，也不是唯一的代理程式，則會在升級期間自動寫入。`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`選用的預設技能允許清單，由未設定 agents.entries.*.skills 的代理程式繼承。省略此設定即不限制技能；設為 [] 則讓繼承此設定的代理程式不具備任何技能。請注意，明確設定的 agents.entries.*.skills 會取代此預設值，而非與其合併。`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`略過建立工作區啟動檔案`},help:{"v1-kbstgw-5v":`略過自動建立工作區啟動檔案，但不會略過注入現有檔案。在嵌入式執行環境中，將 agents.defaults.contextInjection 設為 "never" 即可停用注入，除非個別代理的設定覆寫了此設定。`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`略過的選用初始化檔案`},help:{"v1-1j2z4yj-4c":`不應在代理程式工作區中建立的選用初始化檔案。有效值：SOUL.md、USER.md、IDENTITY.md（接受 HEARTBEAT.md，但不會產生任何作用）。`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`啟動時的上下文`},help:{"v1-1ugsihy-5o":`由執行階段管理的首輪前置內容，適用於不帶參數的 "/new" 和 "/reset"。使用此設定可控制是否將最近的每日記憶檔案預先載入第一個提示，而非讓模型自行決定要讀取哪些內容。`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`啟動情境套用對象`},help:{"v1-wav4a5-36":`選擇哪些不帶參數的重設命令會取得啟動情境：可包含 "new"、"reset" 或兩者（預設：["new","reset"]）。`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`啟動情境每日記憶天數`},help:{"v1-4i5xcm-3p":`依設定的使用者時區，從今天往回計算要載入的日期記憶檔案數量（預設：2，即今天與昨天）。`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`啟用啟動情境`},help:{"v1-1d5vz2u-4i":`為不帶參數的工作階段重設啟用啟動情境前置內容（預設：true）。停用後將恢復為僅使用提示的行為，不會由執行階段載入每日記憶。`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`啟動情境檔案位元組數上限`},help:{"v1-11cbian-41":`建立啟動情境時，每個每日記憶檔案允許的位元組數上限（預設：16384）。超過此安全讀取界限的檔案將被略過。`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`啟動情境檔案字元數上限`},help:{"v1-10z53s-2u":`啟動前置內容中，從每個已載入的每日記憶檔案保留的字元數上限（預設：1200）。`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`啟動上下文總字元數上限`},help:{"v1-sf676u-54":`啟動前置內容中，所有已載入的每日記憶檔案可保留的總字元數上限（預設值：2800）。達到此上限後，額外檔案的內容將從前置內容中截除。`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`子代理委派模式`},help:{"v1-pqewbk-5o":`僅透過提示詞控制的子代理委派強度。每個代理的主要工作階段預設為 "prefer"，其他工作階段則為 "suggest"；"prefer" 會強烈指示代理透過 sessions_spawn 委派非簡單的工作。`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`系統代理目標`},help:{"v1-1wwimo9-34":`背景 OpenClaw 系統代理與 Custodian 推論，以及部分未指定範圍的操作員讀取作業所使用的目標設定。`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`系統代理擁有者`},help:{"v1-15rvt92-8c":`提供模型與憑證，供背景系統代理與 Custodian 諮詢使用的代理。當 models.list、models.authStatus、skills.status、doctor.memory.status，或用於解析代理所屬模型或驗證狀態的 infer CLI 命令未指定 agentId 或 --agent 時，也會使用此代理；請求中明確指定的 agentId 一律優先。`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`輸入狀態更新間隔（秒）`},help:{"v1-1y701ox-42":`控制每個代理維持輸入中指示器的更新間隔，單位為秒。調高此值可降低所有支援輸入中狀態之管道的更新頻率。`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`輸入狀態模式`},help:{"v1-m2hvpw-3m":`控制代理程式何時開始顯示輸入中狀態："never"、"instant"、"thinking" 或 "message"。個別代理程式的 typingMode 會覆寫此預設值。`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`輔助模型`},help:{"v1-1wg7h1a-7s":`選用的低成本模型（provider/model 或別名），用於產生標題、描述進度等簡短的內部任務。未設定時，會使用主要供應商宣告的小型模型（若有），否則使用主要模型；設為空字串可停用輔助模型路由。`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`語音模型備援清單`},help:{"v1-faazv4-1b":`依使用順序排列的備援語音模型（provider/model）。`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`語音模型`},help:{"v1-1yeh3h4-2t":`選用的語音模型（provider/model），供語音、轉錄及即時語音功能使用。`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`語音逾時（毫秒）`},help:{"v1-1sbergs-32":`呼叫端支援逾時設定時，語音模型操作向供應商發出請求的預設逾時時間，以毫秒為單位。`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`工作區`},help:{"v1-1lssx8l-5w":`用於存放啟動初始化與記憶檔案的預設代理程式工作區。未設定 agents.defaults.cwd 時，也會用作工作目錄。透過包裝程式執行時，請明確設定此值，以確保路徑解析結果一致。`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`代理程式清單`},help:{"v1-yurood-5l":`明確列出已設定的代理程式，包含 ID，以及模型、工具、身分和工作區的選用覆寫設定。請保持 ID 穩定不變，以確保綁定、核准和工作階段路由的結果一致。`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`舊版代理執行環境`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`舊版代理執行環境 ID`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`代理啟動初始化字元數上限`},help:{"v1-rsf1es-4j":`為個別代理覆寫注入其系統提示的每個工作區啟動初始化檔案的字元數上限。省略則繼承 agents.defaults.bootstrapMaxChars。`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`代理啟動初始化總字元數上限`},help:{"v1-1bal68p-4y":`為個別代理覆寫注入其系統提示的所有工作區啟動初始化檔案的總字元數上限。省略則繼承 agents.defaults.bootstrapTotalMaxChars。`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`代理上下文注入`},help:{"v1-1j68ys8-50":`針對個別代理程式，覆寫嵌入式執行環境中的工作區啟動檔案注入設定。省略此設定即可繼承 agents.defaults.contextInjection。不控制以 CLI 為基礎的提示準備作業。`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`代理上下文限制`},help:{"v1-f1qxq8-3c":`可選的個別代理覆寫設定，用於調整特定上下文容量限制。省略的欄位會繼承 agents.defaults.contextLimits。`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`代理 memory_get 字元數上限`},help:{"v1-12hlmsv-1v":`為個別代理覆寫預設的 memory_get 字元數上限。`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`代理壓縮後字元數上限`},help:{"v1-15s0npd-1w":`針對個別代理覆寫壓縮後 AGENTS.md 摘錄的字元額度。`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`代理工作目錄`},help:{"v1-mv43ak-6a":`此代理執行回覆時使用的工作目錄。會覆寫 agents.defaults.cwd，但不會覆寫工作階段建立時指定的 cwd；啟動與記憶檔案仍保留在工作區中。支援 ~ 和相對路徑；若使用不同的 cwd，則必須在沙箱外執行。`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`代理程式決策模型`},help:{"v1-1mih8bf-3j":`個別代理程式的決策模型。未設定時會繼承 agents.defaults.decisionModel；空字串則會停用此代理程式的決策呼叫。`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`代理內嵌 OpenClaw`},help:{"v1-uoomza-4b":`選用的個別代理內嵌 OpenClaw 覆寫設定。使用此設定可讓特定代理採用更嚴格的 GPT-5 執行行為，而不變更全域預設值。`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`代理內嵌 OpenClaw 執行契約`},help:{"v1-1d1jaoi-7k":`選用的個別代理內嵌 OpenClaw 執行契約覆寫設定。設為 "strict-agentic"，即可在支援的 OpenAI/OpenAI Codex GPT-5 系列執行中，為該代理啟用結構化計畫追蹤與不可見回合復原；或設為 "default" 以沿用標準執行器行為。`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`代理實驗性旗標`},help:{"v1-1r06jov-2a":`個別代理的實驗性旗標。省略的欄位會沿用 agents.defaults.experimental。`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`代理精簡本機模型模式`},help:{"v1-5o3tgx-58":`針對個別代理程式的精簡本機模型模式疑難排解覆寫設定。僅在限制選用工具能解決已確認的模型故障時啟用，無須刪減所有代理程式的工具。`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`代理程式快速模式預設值`},help:{"v1-1ujydjc-3o":`可選的個別代理程式快速模式預設值（"auto"、true 或 false）。未設定個別訊息或工作階段的快速模式覆寫值時套用。`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`心跳直接傳送政策`},help:{"v1-11gl9l0-41":`個別代理程式的心跳直接傳送／私訊傳遞政策覆寫值；若代理程式應僅將心跳警示傳送至非私訊目的地，請使用 "block"。`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`心跳逾時（秒）`},help:{"v1-kdetv4-6s":`個別代理程式執行心跳回合所允許的最長時間（秒），超過後即中止。留空時會繼承合併後的心跳逾時值，其次採用已設定的 agents.defaults.timeoutSeconds；若皆未設定，則採用心跳間隔，上限為 600 秒。`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`身分頭像`},help:{"v1-pzp9gr-1t":`代理程式頭像（相對於工作區的路徑、http(s) URL 或 data URI）。`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`代理程式模型政策`},help:{"v1-17d5je8-2r":`個別代理程式的模型覆寫政策。明確指定的允許清單會取代此代理程式的預設政策。`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`允許的代理程式模型`},help:{"v1-v1ueke-5b":`此代理程式允許用於覆寫的模型參照。接受別名、完整的 "provider/model" 參照，以及結尾帶萬用字元的前綴模式，例如 "provider/*" 或 "provider/namespace/*"；留空表示允許任何模型。`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`代理程式模型覆寫設定`},help:{"v1-nld1vq-1v":`個別代理的模型目錄覆寫設定，以完整的供應商／模型 ID 為索引鍵。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`代理模型執行環境`},help:{"v1-7b59y-3s":`此代理可選用的個別模型執行環境原則。用於設定特定代理的模型例外，而非為整個代理設定執行環境。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`代理模型執行環境 ID`},help:{"v1-1ckfc39-46":`個別代理的模型執行環境 ID："openclaw"、"auto"、已註冊的外掛程式執行框架 ID（例如 "codex"），或支援的 CLI 後端別名（例如 "claude-cli"）。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`程式碼模式`},help:{"v1-91zu7f-7m":`此代理與指定供應商／模型的 OpenClaw 程式碼模式：開啟會強制啟用，關閉會停用，預設則依序繼承代理啟用設定、共用模型覆寫設定，最後是 tools.codeMode.enabled。這不會變更所選的執行環境或 Codex 原生程式碼模式。`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`代理推理預設值`},help:{"v1-13ly0xf-3m":`可選的個別代理預設推理顯示設定（on|off|stream）。未設定個別訊息或工作階段的推理覆寫設定時套用。`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`代理執行環境`},help:{"v1-avjgkf-3l":`此代理可選用的執行環境描述設定。使用 embedded 採用預設的 OpenClaw 執行方式，或使用 acp 採用外部 ACP 執行框架的預設設定。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`代理 ACP 執行環境`},help:{"v1-91zvdk-3i":`runtime.type=acp 時此代理程式的 ACP 執行環境預設值。各對話仍優先採用綁定層級的 ACP 覆寫設定。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`代理程式的 ACP 執行框架代理程式`},help:{"v1-1pm98vp-37":`供此 OpenClaw 代理程式使用的 ACP 執行框架代理程式 ID，選填（例如 codex、claude、cursor、gemini、openclaw）。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`代理程式的 ACP 後端`},help:{"v1-1u3cdsg-2n":`此代理程式 ACP 工作階段的 ACP 後端覆寫設定，選填（未設定時使用全域 acp.backend）。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`代理程式的 ACP 工作目錄`},help:{"v1-d9p9rf-1t":`此代理程式 ACP 工作階段的預設工作目錄，選填。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`代理程式的 ACP 模式`},help:{"v1-yatuk4-21":`此代理程式的預設 ACP 工作階段模式，選填（persistent 或 oneshot）。`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`代理程式執行環境類型`},help:{"v1-139fbk6-2r":`此代理程式的執行環境類型："embedded"（預設 OpenClaw 執行環境）或 "acp"（ACP 執行框架預設值）。`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`代理程式沙箱瀏覽器的 CDP 來源範圍`},help:{"v1-1q1qyso-1d":`各代理程式的 CDP 來源 CIDR 允許清單覆寫設定。`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`代理程式沙箱瀏覽器網路`},help:{"v1-13bdfww-4c":`個別代理程式的沙箱瀏覽器 Docker 網路覆寫設定。請使用橋接網路；不支援 "none"，因為瀏覽器控制需要對外發布的 CDP 連接埠。`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`代理程式沙箱 Docker 允許加入容器命名空間`},help:{"v1-1xtnseb-2i":`個別代理程式的危險覆寫設定，允許在沙箱 Docker 網路模式中加入容器命名空間。`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`代理程式沙箱 Docker GPU`},help:{"v1-1kek1n2-1t":`個別代理程式的沙箱容器 Docker GPU 直通覆寫設定。`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`代理程式技能篩選器`},help:{"v1-igchue-6v":`此代理程式的選用技能允許清單。若省略，代理程式會在 agents.defaults.skills 已設定時繼承該設定；否則技能維持不受限制。設為 [] 表示不使用任何技能。明確指定的清單會完全取代繼承的預設值，而非與其合併。`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`代理程式 Skills 限制`},help:{"v1-1sv10v9-4y":`個別代理程式的技能子系統額度選用覆寫設定。當代理程式需要不同的技能提示額度，且不想引入第二條通用上下文限制設定路徑時，可使用此設定。`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`代理程式 Skills 提示最大字元數`},help:{"v1-dys63y-52":`個別代理程式的技能提示字元額度覆寫設定。這會擴充現有的 skills.limits.maxSkillsPromptChars 路徑，而非透過 contextLimits 設定相同額度。`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`子代理程式委派模式`},help:{"v1-1rkgh6p-4s":`個別代理程式的子代理程式委派強度覆寫設定。省略時，此代理程式的主要工作階段會使用 "prefer"，其他情況則使用 "suggest"；明確設定的 "prefer" 或 "suggest" 一律優先。`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`代理程式預設思考層級`},help:{"v1-173q7vy-43":`可選的個別代理程式預設思考層級。未設定個別訊息或工作階段的覆寫值時，會覆寫此代理程式的 agents.defaults.thinkingDefault。`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`代理程式工具允許清單新增項目`},help:{"v1-1550ui9-46":`在全域及設定檔原則之外，為個別代理程式額外允許的工具清單。請將範圍限縮，以免意外擴大專用代理程式的權限。`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`依供應商設定的代理程式工具原則`},help:{"v1-mthxv9-4t":`個別代理程式針對特定供應商的工具原則覆寫設定，用於控制通道範圍內的能力。當單一代理程式需要對某個供應商施加比其他供應商更嚴格的限制時，請使用此設定。`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`代理程式程式碼模式`},help:{"v1-118t8u5-65":`各代理程式的 Code Mode 選項。明確設定的 enabled 會覆寫共用模型及全域啟用預設值；代理程式專屬的模型 codeMode 覆寫設定則具有最高優先順序。其他選項會合併至 tools.codeMode 並覆寫對應設定，但不會變更啟用狀態。`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`代理程式執行逾時（秒）`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`代理程式 GitHub CLI 身分覆寫`},help:{"v1-mjwdh4-38":`此代理程式完整的受管理 GitHub CLI 身分與 Git 作者覆寫設定。省略此設定即可繼承系統身分。`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`代理程式 Git 作者電子郵件`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`代理程式 Git 作者姓名`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`代理程式 GitHub 憑證類型`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`代理程式 GitHub 設定檔版本`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`代理程式訊息動作允許清單`},help:{"v1-1g5gov3-67":`message 工具中各代理程式的訊息動作允許清單。針對公開沙箱代理程式，請設為最精簡的清單，例如 ["send"]，以便隱藏並封鎖讀取、編輯、刪除、表情回應及其他供應商專屬的訊息動作。`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`代理程式跨情境訊息傳送（跨供應商）`},help:{"v1-pehesn-49":`個別代理程式的跨服務供應商傳送覆寫設定。繼承全域設定（預設值：true）。設為 false 可封鎖此代理程式跨服務供應商傳送訊息。`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`代理跨情境傳訊（同一供應商）`},help:{"v1-s9u09h-4t":`個別代理程式向同一服務供應商上的其他對話傳送訊息時的防護設定。若公開代理程式僅限於目前對話，請將此設定和 allowAcrossProviders 皆設為 false。`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`代理工具設定檔`},help:{"v1-1du76ix-57":`當某個代理需要不同的基礎能力時，可為其覆寫工具設定檔選擇。請謹慎使用，確保代理之間的政策差異皆為刻意設定且可供審查。`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`代理群集`},help:{"v1-420ljs-2c":`個別代理的群集覆寫設定。這些值會合併至頂層 tools.swarm 設定，並覆寫對應值。`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`代理輸入狀態模式`},help:{"v1-oxir52-2e":`覆寫單一代理開始顯示輸入狀態的預設政策，不影響其他代理。`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`代理輔助模型`},help:{"v1-1v9oskz-2z":`用於簡短內部任務的個別代理輔助模型覆寫設定（選填）。會覆寫 agents.defaults.utilityModel。`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`代理擁有權世代`},help:{"v1-m2hp61-8g":`持久化的多代理擁有權世代標記。"explicit" 表示背景頻道、心跳、系統代理諮詢、Talk、cron 及未指定代理的 CLI 操作，都必須解析出特定介面的擁有者，否則拒絕執行。OpenClaw 會在建立或遷移代理群時自動寫入此標記；僅有單一代理時請省略。`}},approvals:{label:{"v1-1m405m7-9":`核准`},help:{"v1-4y3in-5w":`核准路由控制項，用於將 exec 和外掛程式的核准請求轉送至來源工作階段以外的聊天目的地。除非操作人員需要明確在工作階段外查看核准請求，否則請保持停用。`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`exec 核准轉送`},help:{"v1-1r2mozk-5v":`集中管理 exec 核准轉送行為，包括啟用狀態、路由模式、篩選條件及明確指定的目標。若核准提示必須傳送至維運頻道，而非僅限於來源討論串，請在此設定。`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`核准代理程式篩選條件`},help:{"v1-xbuhd3-5i":'選用的代理程式 ID 允許清單，指定哪些代理程式的核准請求可被轉送，例如 `["primary", "ops-agent"]`。可用於限制轉送的影響範圍，避免因不相關的代理程式而向頻道傳送通知。'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`轉送 exec 核准請求`},help:{"v1-1t0whe8-5s":`啟用後，會將 exec 核准請求轉送至已設定的傳送目的地（預設值：false）。低風險設定下請保持停用，僅在負責核准的人員需要於頻道中查看提示時啟用。`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`核准轉送模式`},help:{"v1-1dedfo4-69":`控制核准提示的傳送位置："session" 使用來源聊天，"targets" 使用已設定的目標，"both" 則同時傳送至兩者。請以 "session" 為基本設定，僅在維運工作流程需要備援通知時擴大傳送範圍。`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`核准工作階段篩選條件`},help:{"v1-smeg8e-5u":'選用的工作階段鍵篩選條件，以子字串或類似正規表示式的模式進行比對，例如 `["discord:", "^agent:ops:"]`。請使用範圍較窄的模式，確保只有預期的核准情境會轉送至共用目的地。'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`核准轉送目標`},help:{"v1-17ah848-5u":`當轉送模式包含目標時使用的明確傳送目標，每個目標都包含頻道與目的地詳細資訊。請讓目標清單遵循最小權限原則，並在啟用廣泛轉送前驗證每個目的地。`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`核准目標帳號 ID`},help:{"v1-16zopng-5e":`適用於多帳號頻道設定的選用帳號選擇器，用於核准必須透過特定帳號情境路由的情況。僅在目標頻道已設定多個身分時使用。`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`核准目標頻道`},help:{"v1-ji1igl-59":`用於傳送轉送核准的頻道／供應商 ID，例如 discord、slack 或外掛程式的頻道 ID。請僅使用有效的頻道 ID，以免核准因未知路由而在未顯示錯誤的情況下傳送失敗。`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`核准目標討論串 ID`},help:{"v1-1axynw7-59":`選用的討論串／主題目標，適用於支援透過討論串傳送轉送核准的頻道。使用此設定可將核准訊息集中在作業討論串中，而非主要頻道。`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`核准目標目的地`},help:{"v1-1ijng7e-5n":`目標頻道內的目的地識別碼（依供應商而定，可以是頻道 ID、使用者 ID 或討論串根訊息）。請確認各供應商的語意，因為不同頻道整合的目的地格式有所不同。`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`外掛程式核准轉送`},help:{"v1-1m6pzxv-6b":`集中管理外掛程式核准的轉送行為，包括啟用狀態、路由模式、篩選條件及明確指定的目標。此設定獨立於執行核准轉送。當外掛程式核准提示必須送達作業頻道時，請在此設定。`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`外掛程式核准代理程式篩選條件`},help:{"v1-jb1bra-4b":'選用的代理程式 ID 允許清單，指定哪些代理程式的外掛程式核准可被轉送，例如 `["primary", "ops-agent"]`。使用此設定可限制轉送的影響範圍。'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`轉送外掛程式核准`},help:{"v1-1ntctaf-3v":`啟用將外掛程式核准請求轉送至已設定的傳送目的地（預設值：false）。此設定獨立於 approvals.exec.enabled。`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`外掛程式核准轉送模式`},help:{"v1-1h62vy4-3z":`控制外掛程式核准提示的傳送位置："session" 使用來源聊天，"targets" 使用已設定的目標，而 "both" 則同時傳送至兩者。`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`外掛程式核准工作階段篩選條件`},help:{"v1-1eppxmt-57":'選用的工作階段鍵篩選條件，以子字串或正規表示式樣式的模式進行比對，例如 `["discord:", "^agent:ops:"]`。請使用精確的模式，確保只轉送預期情境中的核准請求。'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`外掛程式核准轉送目標`},help:{"v1-o92qze-3k":`外掛程式核准轉送模式包含 targets 時使用的明確傳送目標，每個目標皆包含頻道與目的地詳細資訊。`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`外掛程式核准目標帳號 ID`},help:{"v1-1wf3lqn-3j":`多帳號頻道設定中的選用帳號選擇器，適用於必須透過特定帳號情境路由外掛程式核准的情況。`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`外掛程式核准目標頻道`},help:{"v1-1mzhzi9-34":`用於傳送轉送之外掛程式核准的頻道／提供者 ID，例如 discord、slack 或外掛程式頻道 ID。`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`外掛程式核准目標討論串 ID`},help:{"v1-1scaw9c-2v":`選用的討論串／主題目標，適用於支援以討論串方式傳送轉送之外掛程式核准的頻道。`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`外掛程式核准目標目的地`},help:{"v1-sh5te1-31":`目標頻道內的目的地識別碼（依提供者而定，可為頻道 ID、使用者 ID 或討論串根節點）。`}},attachments:{label:{"v1-8925gh-b":`附件`},help:{"v1-1xvgkss-40":`儲存媒體的提供者與工具共用的頂層保留行為。當一般暫存媒體需要限時清理時，請使用 ttlHours。`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`附件保留 TTL（小時）`},help:{"v1-1g90day-9e":`由一般 mtime 清理作業處理的持久儲存媒體可選用的保留期限，以小時為單位。留空可停用該清理作業，或設為 24（1 天）、168（7 天）等數值，以定期移除較舊的暫存媒體。受管理的傳出媒體（聊天產生的附件）不在此範圍內，並遵循其專屬、會考量 SQLite 與對話記錄的保留機制。`}},audio:{label:{"v1-11wczsp-5":`音訊`}},auth:{label:{"v1-5xz433-4":`驗證`},help:{"v1-1eu3aud-5c":`驗證設定檔的根節點，用於管理多個設定檔的供應商憑證，以及依冷卻時間決定的容錯移轉順序。請讓設定檔保持精簡且明確，以便稽核自動容錯移轉行為。`}},"auth%2Eorder":{label:{"v1-gadtii-i":`驗證設定檔順序`},help:{"v1-1x6kknp-1w":`各供應商依序排列的驗證設定檔 ID（用於自動容錯移轉）。`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`驗證設定檔`},help:{"v1-kzoqcn-1j":`具名驗證設定檔（供應商 + 模式 + 選填的電子郵件）。`}},bindings:{label:{"v1-1hcih9f-8":`按鍵綁定`},help:{"v1-y7hrzb-4i":`用於路由與持久性 ACP 對話歸屬的頂層綁定規則。一般路由請使用 type=route，持久性 ACP 執行框架綁定請使用 type=acp。`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`ACP 綁定覆寫設定`},help:{"v1-1t4lisi-44":`適用於 bindings[].type=acp 的選用個別綁定 ACP 覆寫設定。此層會針對符合條件的對話，覆寫 agents.entries.*.runtime.acp 的預設值。`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP 綁定後端`},help:{"v1-rsrbkp-2x":`此綁定的 ACP 後端覆寫設定（未設定時使用代理執行環境的 ACP 後端，再未設定則使用全域 acp.backend）。`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`ACP 綁定工作目錄`},help:{"v1-ngpkj0-1y":`覆寫透過此綁定建立的 ACP 工作階段所使用的工作目錄。`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`ACP 綁定標籤`},help:{"v1-azce82-23":`用於此綁定對話中 ACP 狀態與診斷資訊的易讀標籤。`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`ACP 綁定模式`},help:{"v1-cgq8xv-1v":`覆寫此綁定的 ACP 工作階段模式（persistent 或 oneshot）。`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`綁定代理程式 ID`},help:{"v1-17ra0cl-4m":`符合對應的綁定比對規則時，接收流量的目標代理程式 ID。請僅使用已設定的有效代理程式 ID，以免路由在執行時失敗。`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`綁定比對規則`},help:{"v1-sc1w2e-51":`用於判定何時套用綁定的比對規則物件，包含頻道及選用的帳號／對端限制條件。請縮小規則範圍，避免代理程式意外接管其他情境。`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`綁定帳號 ID`},help:{"v1-1d209g7-56":`多帳號頻道設定中選用的帳號選擇條件，讓綁定僅套用至單一身分。當路由需要限定帳號範圍時使用，否則請勿設定。`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`綁定頻道`},help:{"v1-d22m5-54":"此綁定適用的頻道／供應商識別碼，例如 `telegram`、`discord` 或外掛程式頻道 ID。請使用與設定完全一致的頻道鍵，以確保綁定判定可靠運作。"}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`綁定伺服器 ID`},help:{"v1-jzzfj1-4x":`選用的 Discord 式社群／伺服器 ID 限制，用於多伺服器部署中的綁定評估。當相同的對端識別碼可能出現在不同社群時，請使用此設定。`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`綁定對端比對`},help:{"v1-gcjxff-4i":`選用的對端比對條件，用於特定對話，包含對端類型與對端 ID。當只需將單一私訊／群組／頻道目標固定指派給某個代理程式時，請使用此設定。`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`綁定對端 ID`},help:{"v1-86fbh7-4b":`用於對端比對的對話識別碼，例如供應商提供的聊天 ID、頻道 ID 或群組 ID。請確保此值完全正確，以免比對失敗卻未收到提示。`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`綁定對端類型`},help:{"v1-uufscp-4x":`對端對話類型："direct"、"group"、"channel" 或舊版的 "dm"（direct 的已棄用別名）。新設定請優先使用 "direct"，並確保 kind 與頻道語意一致。`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`綁定角色`},help:{"v1-6s891m-4k":`選用的角色篩選清單，適用於會將角色附加至聊天情境的供應商。使用此設定可將特權或維運角色的流量路由至專門的代理程式。`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`綁定團隊 ID`},help:{"v1-hh9ps2-48":`選用的團隊／工作區 ID 限制，適用於將聊天歸屬於團隊的供應商。當您需要將綁定限定於單一工作區情境時，請新增此設定。`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`綁定工作階段`},help:{"v1-x325l2-4v":`針對此綁定所匹配對話的選用路由工作階段覆寫設定。當特定路由需要保留相同代理程式，但以不同方式隔離工作階段連續性時，可使用此設定。`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`綁定工作階段私訊範圍`},help:{"v1-10sg3xw-4s":`此路由綁定的選用私訊工作階段範圍覆寫設定。例如，保留全域 session.dmScope="main"，同時對選定的私訊對象使用 "per-account-channel-peer"。`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`綁定工作階段群組範圍`},help:{"v1-1ys2u7k-6n":`此路由綁定的選用群組／頻道工作階段範圍覆寫設定。"per-group" 會將匹配的聊天室分開，並由代理程式的主要工作階段在背景持續監看，不受 dmScope 影響；"main" 則會將其上下文合併至主要工作階段，無須監看。`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`綁定類型`},help:{"v1-172mhtk-3o":`綁定的種類。一般路由使用 "route"（舊版路由項目可省略），持續性的 ACP 對話綁定則使用 "acp"。`}},broadcast:{label:{"v1-awqjh0-j":`代理群組討論串`},help:{"v1-1tz72sr-6b":`使用代理群組討論串，讓多個已設定的代理在同一個傳入對話中運作，且各自使用獨立的工作階段。指定通道的項目支援有限次數的後續回合；舊版 WhatsApp 對端陣列則維持單次執行行為。`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`代理群組參與者與選項`},help:{"v1-1b63zmt-7d":`使用指定通道的對端 ID（例如 "telegram:-100123"），設定代理 ID 陣列，或包含 agents、mentionGating、maxRounds 和 maxTurns 的嚴格格式物件。指定通道的項目優先於舊版 WhatsApp 對端鍵，且最多允許 16 個代理。`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`代理群組參與者`},help:{"v1-g5o0ky-43":`來自 agents.entries 的參與代理 ID（最多 16 個）。每位參與者都會針對此通道、帳號、對話及討論串使用獨立的工作階段。`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`代理群組最大輪數`},help:{"v1-i6v4jc-5a":`每則傳入訊息的最大輪數，包含初始輪次（整數：1–4，預設值：1）。後續輪次會共用有數量限制且標明來源的其他參與者回覆，並在所有參與者都選擇略過時停止。`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`代理群組最大回合數`},help:{"v1-1kiv8dy-72":`每則傳入訊息在所有輪次中的參與者回合數上限（整數：1–32，預設值：agents.length）。並行派送前會先保留名額；此設定限制的是代理回合數，而非實際訊息區塊數或工具傳送次數。重新啟動後不會延續先前的額度。`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`代理群組提及篩選`},help:{"v1-uay9zu-5u":`若有參與者被明確以 @ 提及，則僅選取這些參與者；否則讓所有參與者執行（預設值：true）。僅輸入名稱或表情符號不會選取參與者。頻道允許清單與准入規則仍然適用。`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`代理群組策略`},help:{"v1-p4k9hu-4q":`參與者執行順序："parallel"（預設值）會並行執行代理，而 "sequential" 會依設定順序執行。每一輪都必須完成後才會開始下一輪。`}},browser:{label:{"v1-13dzmen-7":`瀏覽器`},help:{"v1-5b74wi-5l":`瀏覽器執行階段控制項，用於本機或遠端 CDP 連接、設定檔路由，以及螢幕截圖／快照行為。除非您的自動化工作流程需要自訂瀏覽器傳輸設定，否則請保留預設值。`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`允許匯入系統設定檔`},help:{"v1-1lsvlxw-5w":`允許 macOS 主機將 Cookie 從本機 Chrome 系列瀏覽器的系統設定檔匯入受管理的 OpenClaw 瀏覽器設定檔。停用此選項可防止匯入瀏覽器設定檔的 Cookie，並避免顯示相關的 macOS 鑰匙圈授權提示。`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`瀏覽器僅連接模式`},help:{"v1-xaw7xm-4s":`將瀏覽器模式限制為僅連接現有執行個體，不啟動本機瀏覽器程序。當所有瀏覽器工作階段皆由遠端 CDP 提供者在外部管理時，請使用此模式。`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`瀏覽器 CDP URL`},help:{"v1-2n72jb-65":`用於連接外部管理之瀏覽器執行個體的 CDP/DevTools 端點 URL。適用於集中式瀏覽器主機、通道或現有工作階段連接，並請將 URL 存取限制在受信任的網路路徑內。`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`瀏覽器預設設定檔`},help:{"v1-a6xo96-52":`呼叫端未明確選擇設定檔時所使用的預設瀏覽器設定檔名稱。請使用穩定且權限較低的設定檔作為預設值，以減少意外跨情境使用狀態的情況。`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`啟用瀏覽器`},help:{"v1-19qr4oj-56":`在 Gateway 中啟用瀏覽器功能整合，讓瀏覽器工具和由 CDP 驅動的工作流程得以執行。不需要瀏覽器自動化時，請停用此功能，以減少暴露面和啟動負擔。`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`啟用瀏覽器求值`},help:{"v1-1oa79mq-59":`啟用瀏覽器端的求值輔助功能，以便在支援的環境中於執行階段對指令碼求值。除非您的工作流程需要快照與導覽以外的求值功能，否則請保持停用。`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`瀏覽器執行檔路徑`},help:{"v1-1plb4ki-6i":`當自動探索不足以滿足主機環境需求時，明確指定瀏覽器執行檔路徑。請使用固定的絕對路徑，或以 ~ 開頭、指向作業系統家目錄的路徑，確保重新啟動後的啟動行為保持一致。`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`瀏覽器擴充功能中繼`},help:{"v1-6ywlwr-4e":`Chrome 擴充功能中繼驗證的相容性設定。僅在已配對的舊版擴充功能或外部 CDP 用戶端仍有需要時，才保留舊版相容期。`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`允許舊版瀏覽器中繼驗證`},help:{"v1-pj2e90-63":`暫時接受舊版 Bearer、Basic 和 token-subprotocol 中繼驗證。預設值：在一個遷移期間內為 true。所有擴充功能和外部 CDP 用戶端都改用 Browser Relay Authentication v2 後，請設為 false。`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`瀏覽器無頭模式`},help:{"v1-1rswq8j-5a":`當本機啟動器啟動瀏覽器執行個體時，強制以無頭模式啟動。伺服器環境請保持啟用無頭模式，僅在需要透過可見的使用者介面進行偵錯時才停用。`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`瀏覽器無沙箱模式`},help:{"v1-slntux-4w":`停用 Chromium 沙箱隔離旗標，適用於沙箱在執行階段無法運作的環境。請盡可能保持關閉，因為此模式會降低程序隔離的保護程度。`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`瀏覽器設定檔`},help:{"v1-1x8lf05-51":`具名瀏覽器設定檔的連線對應表，用於明確路由至 CDP 連接埠或 URL，並可選擇附加中繼資料。請保持設定檔名稱一致，並避免端點定義重疊。`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`瀏覽器設定檔僅附加模式`},help:{"v1-2b5zs0-5a":`各設定檔的僅附加覆寫設定，會略過本機瀏覽器啟動，僅附加至現有的 CDP 端點。適用於某個設定檔由外部管理，而其他設定檔在本機啟動的情況。`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`瀏覽器設定檔 CDP 連接埠`},help:{"v1-gx1yiq-49":`各設定檔的本機 CDP 連接埠，用於透過連接埠而非 URL 連線至瀏覽器執行個體。請為每個設定檔使用不同的連接埠，以避免連線衝突。`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`瀏覽器設定檔 CDP URL`},help:{"v1-x491r0-64":`各設定檔的 CDP/DevTools 端點 URL，用於依設定檔名稱明確指定瀏覽器路由。適用於遠端 CDP 主機、通道，或應透過執行中的 Chrome DevTools 端點附加至既有工作階段的設定檔。`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`瀏覽器設定檔驅動程式`},help:{"v1-17byyx6-5r":`各設定檔的瀏覽器驅動程式模式。以 CDP 為基礎的設定檔請使用 "openclaw"（或舊版的 "clawd"）；透過 Chrome DevTools MCP 連接請使用 "existing-session"；透過已驗證的 Chrome 擴充功能中繼請使用 "extension"。`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`瀏覽器設定檔執行檔路徑`},help:{"v1-29azyv-4w":`各設定檔的瀏覽器執行檔路徑，適用於在本機啟動的受管理瀏覽器設定檔。此設定會覆寫 browser.executablePath，並接受以 ~ 開頭的路徑，以表示作業系統的使用者主目錄。`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`瀏覽器設定檔無頭模式`},help:{"v1-p4jtgv-4u":`各設定檔的無頭模式覆寫設定，適用於在本機啟動的瀏覽器執行個體。若某個設定檔需要維持無頭模式，但不想透過 browser.headless 強制其他所有設定檔使用此模式，請使用此設定。`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`瀏覽器設定檔 Chrome MCP 引數`},help:{"v1-rc45ke-5g":`各設定檔用於 existing-session 連接的額外 Chrome DevTools MCP 引數，例如 --no-usage-statistics。此處的端點引數會覆寫內建的自動連線或瀏覽器 URL 選擇。`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`瀏覽器設定檔 Chrome MCP 命令`},help:{"v1-1xpty8o-2h":`各設定檔用於 existing-session 連接的 Chrome DevTools MCP 命令。預設為 npx。`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`瀏覽器設定檔使用者資料目錄`},help:{"v1-5xvgex-9h":`各設定檔的 Chromium 使用者資料目錄，用於透過 Chrome DevTools MCP 連接至現有工作階段。若內建的自動連線流程會在所選主機或瀏覽器節點上選到錯誤的瀏覽器資料目錄，可使用此設定指定 Brave、Edge、Chromium 或非預設 Chrome 設定檔的目錄。以 ~ 開頭的路徑會展開為作業系統的家目錄。`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`瀏覽器快照預設值`},help:{"v1-v19wdy-4y":`呼叫端未明確提供快照選項時使用的預設快照擷取設定。調整此設定，可讓各管道與自動化流程的擷取行為保持一致。`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`瀏覽器快照模式`},help:{"v1-joeyxp-5c":`預設的快照擷取模式，控制如何轉換頁面內容以供代理使用。請選擇能在可讀性、保真度與詞元用量之間取得平衡，且適合您工作流程的模式。`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`瀏覽器 SSRF 政策`},help:{"v1-1qbp9im-5e":`針對可能存取內部主機的瀏覽器與網路擷取流程，設定伺服器端請求偽造防護措施。在正式環境中，請保留嚴格的預設設定，且僅開放明確核准的目標。`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`瀏覽器允許的主機名稱`},help:{"v1-1rng39-2k":`瀏覽器 SSRF 政策檢查允許的完整主機名稱或 IP 位址字面值。請將清單維持在最小必要範圍。`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`瀏覽器允許 IPv6 唯一本機位址範圍`},help:{"v1-1glx5cy-2c":`允許在受信任的 fake-IP 代理環境中使用 IPv6 唯一本機位址（fc00::/7）。`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`瀏覽器允許 RFC 2544 基準測試範圍`},help:{"v1-10ateu3-2i":`允許在受信任的 fake-IP 代理環境中使用 RFC 2544 基準測試範圍 IP（198.18.0.0/15）。`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`瀏覽器封鎖的主機名稱`},help:{"v1-nug0we-6k":`在 DNS 解析及允許規則之前優先拒絕的主機名稱模式，即使已啟用私人網路存取也一樣。支援精確主機名稱，以及僅適用於子網域的 "*.example.com"；若要封鎖根網域，請另外加入 "example.com"。留空或未設定時，不會新增任何拒絕規則。`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`瀏覽器允許私人網路存取（危險）`},help:{"v1-17103pi-4m":`允許瀏覽器工具存取私人網路位址範圍。未設定時預設為停用；僅應針對明確信任的私人網路目的地啟用。`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`瀏覽器分頁清理`},help:{"v1-1ctwaad-4y":`盡可能清理主要代理程式工作階段所開啟之瀏覽器分頁的原則。請保持啟用，以免過時的沙箱或受管理瀏覽器分頁在長時間運作的 Gateway 中不斷累積。`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`啟用瀏覽器分頁清理`},help:{"v1-4sv97p-3u":`啟用清理主要代理程式工作階段中受追蹤的閒置瀏覽器分頁。僅在外部工具完全管理分頁生命週期時才停用。`}},channels:{label:{"v1-1ju93md-8":`頻道`},help:{"v1-12yv6ma-5n":`通道供應商設定及共用預設值，用於控制存取原則、心跳可見性及各介面的行為。請集中管理預設值，並僅在必要時針對個別供應商覆寫。`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`頻道預設值`},help:{"v1-uz6veb-4p":`未設定供應商專屬設定時，套用至各供應商的預設頻道行為。使用此設定可在針對各供應商微調前，先落實一致的基本政策。`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`預設機器人迴圈防護`},help:{"v1-1lpznyk-4w":`適用於支援機器人間迴圈防護的頻道供應商之預設配對迴圈防護設定。僅在個別頻道需要不同額度時，才使用供應商專屬覆寫設定。`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`預設機器人迴圈冷卻秒數`},help:{"v1-1yl5ird-2z":`配對超過迴圈額度後套用的冷卻秒數。支援此功能的頻道預設為 60。`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`預設啟用機器人迴圈防護`},help:{"v1-3ruik-4r":`當機器人撰寫的訊息可進入分派流程時，為支援此功能的頻道預設啟用配對迴圈防護。若忽略機器人訊息，供應商仍可停用此防護。`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`預設機器人迴圈每個時間視窗的事件數`},help:{"v1-1u0mdjc-41":`在開始抑制前，傳送者／接收者配對可於設定的時間視窗內交換的事件數上限。支援此功能的頻道預設為 20。`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`預設機器人迴圈時間視窗秒數`},help:{"v1-12xpmen-2m":`配對迴圈額度的滑動視窗長度，以秒為單位。支援此功能的頻道預設為 60。`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`預設上下文可見性`},help:{"v1-1hze3g1-5o":`擷取的引用、討論串及歷史記錄內容之預設補充上下文可見性："all"（保留所有上下文）、"allowlist"（僅限允許清單中的傳送者）或 "allowlist_quote"（允許清單加上明確引用的內容）。`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`預設群組政策`},help:{"v1-ntl9m4-4n":`所有頻道的預設群組政策："open"、"disabled" 或 "allowlist"。除非有意開放廣泛的群組參與，否則請保留 "allowlist"，以提高正式環境設定的安全性。`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`預設心跳可見性`},help:{"v1-49bw75-4v":`供應商或頻道發出的狀態訊息之預設心跳可見性設定。可全域調整此設定，減少正常狀態更新的干擾，同時保持警示可見。`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`心跳顯示警示`},help:{"v1-8dk8zx-4g":`設為 true 時，會顯示降級或錯誤的心跳警示，讓操作人員使用的頻道能及時呈現問題。請在正式環境中保持啟用，以便察覺頻道異常狀態。`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`心跳顯示正常狀態`},help:{"v1-17tg3mk-4z":`設為 true 時，會在頻道狀態輸出中顯示正常的心跳狀態項目。在訊息繁雜的環境中，請維持 false，僅在操作人員需要明確確認運作正常時啟用。`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`心跳使用指示器`},help:{"v1-1w12cs2-4m":`在支援的介面中，啟用簡潔的指示器式心跳顯示，取代冗長的狀態文字。若儀表板資訊密集且有許多使用中的頻道，請使用指示器模式。`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`預設隱含提及`},help:{"v1-4gtdyv-48":`預設原則，決定回覆機器人、引用機器人訊息，以及在機器人曾參與的討論串中發言等情況，是否能在未明確提及機器人時，於支援此功能的訊息頻道中觸發機器人。`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`預設將引用機器人訊息視為隱含提及`},help:{"v1-va1u5v-2v":`預設將引用機器人訊息視為隱含提及。為維持向後相容性，預設值為 true。`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`預設將回覆機器人視為隱含提及`},help:{"v1-lm44c3-39":`預設將對機器人自身訊息的回覆視為隱含提及。為維持向後相容性，預設值為 true。`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`預設將討論串參與視為隱含提及`},help:{"v1-160205h-3o":`預設將機器人曾參與之討論串中的後續訊息視為隱含提及。為維持向後相容性，預設值為 true。`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`頻道模型覆寫`},help:{"v1-1b01spx-2p":`對應關係：供應商 -> 頻道 ID／私訊對象 ID -> 模型覆寫（值為 provider/model 或別名）。`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`雲端工作節點`},help:{"v1-10carc4-5v":`供拋棄式遠端環境使用、需主動啟用的雲端工作節點設定檔。若省略此區段或未包含任何設定檔，將無法建立雲端工作節點，且現有的 Gateway／節點狀態行為維持不變。`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`雲端工作節點桌面（實驗室）`},help:{"v1-vllayc-3n":`為支援桌面的雲端工作節點環境啟用實驗性的 worker.desktop.observe 介面及 Control UI 桌面面板。`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`雲端工作節點預備集區`},help:{"v1-rw51o5-6b":`限制預先備妥、供後續工作階段使用的雲端工作節點數量。在供應商完成清理前，保留的工作節點會持續產生機器執行費用；其固定到期時間依專案實際需求與供應商現行的閒置政策而定。`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`雲端工作節點就緒備用上限`},help:{"v1-1mpd1dt-7u":`Gateway 全域中，跨專案與設定檔的未指派預備雲端工作節點數量上限（預設：4）。準備中的工作節點與尚未確認清理完成的備用節點均計入此上限。設為 0 可清空未指派的備用節點並停用補充，同時保留快照重用功能與進行中的工作階段。`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`雲端工作節點設定檔`},help:{"v1-eii67l-3j":`具名的雲端工作節點設定檔。每個設定檔會選用由外掛程式註冊的工作節點供應商，並包含該供應商專屬的設定。`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`雲端工作節點設定檔`},help:{"v1-1v2w7jl-4u":`建立環境時依名稱選取的雲端工作節點設定檔。請使用支援的參照方式保存供應商憑證，避免將機密資料直接嵌入此區塊。`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`雲端工作節點安裝方式`},help:{"v1-blrtbf-74":`工作節點安裝方式："bundle"（預設）會傳輸 Gateway 已安裝且帶有內容雜湊的建置版本，支援已發行、開發中及尚未發行的版本；"npm" 會安裝與 Gateway 完全相同的版本，且僅在該版本已發行時可用。`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`雲端工作節點供應商`},help:{"v1-1p4s4c1-44":`由外掛註冊的工作節點供應商 ID。設定的外掛必須提供此 ID，Gateway 才能依據此設定檔佈建環境。`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`雲端工作節點就緒備用目標`},help:{"v1-1nwve9s-7w":`使用此設定檔的每個符合資格專案所需的未指派預備工作節點目標數量（預設：1），受 Gateway 全域預備集區上限限制。設為 0 可停用此設定檔的備用節點，同時保留快照重用功能。準備中的工作節點與尚未確認清理完成的備用節點均計入此目標數量。`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`雲端工作節點供應商設定`},help:{"v1-mq7u32-4j":`由供應商定義並由所選外掛驗證的設定。含有機密的值請使用 SecretRef 物件；不透明設定不會自動解析機密。`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`雲端工作節點閒置暫停時限`},help:{"v1-1keuwgh-4w":`雲端工作節點閒置達此時限後會自動回收，例如 45m 或 2h；下一則訊息會觸發佈建替代節點。最短為 1m。不設定則讓工作節點持續運作。`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`雲端工作節點專案設定檔`},help:{"v1-1kkfrif-46":`以正規化為小寫的儲存庫識別資訊 (host/owner/repo) 為索引鍵的預設雲端工作節點設定檔名稱。明確指定的派送設定檔 ID 優先。`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`雲端工作節點專案設定檔`},help:{"v1-1mux5u0-30":`當工作階段工作樹的 origin 與此儲存庫識別資訊相符時，預設使用的雲端工作節點設定檔名稱。`}},commands:{label:{"v1-15x4mpf-8":`命令`},help:{"v1-1gi0dr2-5a":`控制各供應商的聊天指令介面、擁有者存取限制，以及指令的提權存取行為。除非需要更嚴格的操作人員管控或更廣泛的指令可用範圍，否則請保留預設值。`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`指令提權存取規則`},help:{"v1-7azkw-5g":`依頻道和傳送者定義擁有者層級命令介面的提權命令允許規則。請使用範圍明確的提供者專屬身分，避免向廣泛的聊天對象開放特權命令。`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`允許 Bash 聊天命令`},help:{"v1-83ah7w-36":"允許 bash 聊天命令（`!`；別名為 `/bash`）執行主機 shell 命令（預設值：false；需要 tools.elevated）。"}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash 前景執行時間（毫秒）`},help:{"v1-1o0o4dw-2c":`bash 轉入背景執行前的等待時間（預設值：2000；0 表示立即轉入背景）。`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`允許 /config`},help:{"v1-151bb7c-21":`允許 /config 聊天命令讀取及寫入磁碟上的設定（預設值：false）。`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`允許 /debug`},help:{"v1-y1lc3j-1y":`允許 /debug 聊天命令進行僅在執行期間生效的覆寫（預設值：false）。`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`允許 /mcp`},help:{"v1-1rtwcgd-2o":`允許 /mcp 聊天命令管理 mcp.servers 下的 OpenClaw MCP 伺服器設定（預設值：false）。`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`原生命令`},help:{"v1-dighr2-5n":`向支援命令註冊的頻道（Discord、Slack、Telegram）註冊原生斜線命令／選單命令。建議保持啟用，方便使用者探索命令，除非您刻意採用純文字命令工作流程。`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`原生技能命令`},help:{"v1-19gtqci-5h":`註冊原生技能命令，讓使用者在支援的情況下，直接從提供者的命令選單呼叫技能。請與您的技能政策保持一致，確保開放的命令符合操作人員的預期。`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`指令擁有者`},help:{"v1-1di38gv-3y":`明確指定可使用擁有者專用指令的擁有者允許清單。請使用頻道原生 ID（可選擇加上前綴，例如 "whatsapp:+15551234567"）。'*' 會被忽略。`}},"commands%2Eplugins":{label:{"v1-culv09-e":`允許 /plugins`},help:{"v1-akwy9y-33":`允許使用 /plugins 聊天指令列出已探索到的外掛程式，並在設定中切換外掛程式的啟用狀態（預設：false）。`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`允許重新啟動`},help:{"v1-m32fv2-27":`允許 /restart、/update 及外部 SIGUSR2 重新啟動請求（預設值：true）。`}},"commands%2Etext":{label:{"v1-5g1c88-d":`文字指令`},help:{"v1-1utu76s-5j":`除了可用的原生指令介面外，也啟用聊天輸入中的文字指令解析。請保持啟用，以相容於不支援原生指令註冊的各個頻道。`}},cron:{label:{"v1-1qlte4b-b":`自動化`},help:{"v1-4md8ic-5u":`全域排程器設定，涵蓋已儲存的自動化、並行執行數、傳送備援及執行工作階段保留期限。除非您要擴大自動化規模或整合外部 webhook 接收端，否則請保留預設值。`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`啟用自動化`},help:{"v1-y8otx6-5i":`啟用 Gateway 管理的已儲存排程的自動化執行。一般提醒與自動化流程應保持啟用；只有在需要暫停所有自動化執行且不刪除作業時，才停用此選項。`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`自動化工作階段保留期限`},help:{"v1-4wagu6-7e":"控制已完成的自動化執行工作階段在清除前的保留時間（`24h`、`7d`、`1h30m`，或設為 `false` 以停用清除；零時長如 `0h` 也會停用清除；預設值：`24h`）。對於高頻率排程，可縮短保留時間以減少儲存空間的增長。"}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`略過錯過的週期性自動化作業`},help:{"v1-w9wfmo-66":`在 Gateway 啟動時略過錯過的週期性 cron/every 排程時段，改為安排下一個未來的執行時間，而不補執行。預設值：false。啟用後可避免停機後出現過期提醒；一次性的 at 作業仍會補執行。`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`自動化 Webhook SSRF 政策`},help:{"v1-1xlfqnu-5h":`套用至每個對外自動化 Webhook 的 SSRF 政策。除非此政策明確允許，否則私有、回送、鏈路本地及內部目標仍會遭到封鎖。保持未設定，以採用嚴格的傳送限制。`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`自動化 Webhook 允許的主機名稱`},help:{"v1-1i94hyz-3n":`允許自動化 Webhook 傳送至的確切主機名稱或 IP 字面值，包括原本會遭到封鎖的目標。請僅列出必要項目。`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`自動化 Webhook 允許 IPv6 唯一本地位址範圍`},help:{"v1-rke0oj-3b":`允許將自動化 Webhook 傳送至 IPv6 唯一本地位址（fc00::/7）。僅限在受信任的 fake-IP 代理環境中使用。`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`自動化 Webhook 允許 RFC 2544 基準測試位址範圍`},help:{"v1-x1usg4-3h":`允許自動化 Webhook 傳送至 RFC 2544 效能測試範圍內的 IP（198.18.0.0/15）。僅應在受信任的 fake-IP 代理環境中使用。`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`自動化 Webhook 封鎖的主機名稱`},help:{"v1-16cv1ic-6a":`自動化 Webhook 傳送時，在 DNS 解析和允許規則之前套用的主機名稱拒絕模式。支援完整主機名稱，以及僅比對子網域的 "*.example.com"；若要封鎖根網域，請另行加入 "example.com"。留空或未設定時不會新增任何拒絕規則。`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`自動化 Webhook 允許私人網路（危險）`},help:{"v1-1n9710c-3t":`允許自動化 Webhook 傳送至私人及內部網路目標。除非所有已設定的 Webhook 目的地皆受信任，否則請保持停用。`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`自動化 Webhook Bearer 權杖`},help:{"v1-1l90hxg-5l":`使用 Webhook 模式時，附加於自動化 Webhook POST 傳送請求的 Bearer 權杖。建議使用密鑰或環境變數替換；若共用的 Webhook 端點可從網際網路存取，請定期輪替此權杖。`}},desktop:{label:{"v1-rs698z-7":`桌面`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`本機桌面`},help:{"v1-99weio-30":`透過本機 VNC 伺服器，檢視已配對節點或實驗性 Gateway 主機來源的桌面。`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`桌面共享`},help:{"v1-m9lbcj-83":`啟用這台機器的桌面來源。已配對的 macOS、Windows 和 Linux 節點預設為啟用；若已明確設定桌面應用程式的分享偏好，則優先採用該設定。Gateway 主機的 Labs 來源預設為停用，且變更會即時套用。變更已配對節點的桌面設定後，請重新啟動該節點。`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`受管理的 Linux 主機桌面`},help:{"v1-1r7n22m-49":`在 Linux 上執行並監管僅限迴路介面存取的無頭 TigerVNC/XFCE 桌面。明確指定的連接埠或已在預設連接埠執行的 VNC 伺服器仍會優先使用。`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`本機 VNC 密碼檔案`},help:{"v1-1m5lsox-37":`VNC 密碼檔案的絕對路徑。在 macOS 上可省略此設定，以便在開啟桌面檢視器時輸入帳號憑證。`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`本機 VNC 連接埠`},help:{"v1-1ku4w9b-2b":`此電腦上已在執行的 VNC 伺服器所使用的回送 RFB 連接埠（預設值：5900）。`}},diagnostics:{label:{"v1-1stxhg7-b":`診斷`},help:{"v1-1d5rnym-5p":`診斷控制項，用於偵錯期間的針對性追蹤、遙測匯出及快取檢查。在正式環境中，請將基本診斷維持在最低限度，僅在調查問題時啟用更深入的診斷訊號。`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`快取追蹤`},help:{"v1-10523zm-5b":`快取追蹤記錄設定，用於觀察嵌入式執行期間的快取決策及承載資料脈絡。請在偵錯時暫時啟用，並在完成後停用，以減少敏感資訊的記錄量。`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`啟用快取追蹤`},help:{"v1-2c1umi-1v":`記錄嵌入式代理程式執行時的快取追蹤快照（預設值：false）。`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`啟用診斷`},help:{"v1-a46pxt-4h":`控制日誌與遙測串接路徑中診斷檢測輸出的總開關。預設為啟用；僅在受到嚴格限制的環境中才設為 false。`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`診斷旗標`},help:{"v1-x4w5ok-33":`依旗標啟用特定的診斷日誌（例如 ["telegram.http"]）。支援 "telegram.*" 或 "*" 等萬用字元。`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`OpenTelemetry 匯出設定，適用於 Gateway 元件產生的追蹤、指標和日誌。與集中式可觀測性後端及分散式追蹤管線整合時，請使用此設定。`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry 內容擷取`},help:{"v1-19tid4t-2t":`需主動啟用的 OTEL span 內容擷取功能。預設為關閉；設為 true 時會擷取非系統訊息與工具內容。`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`啟用 OpenTelemetry`},help:{"v1-193bm0-5b":`根據已設定的端點與通訊協定，啟用 OpenTelemetry 的追蹤、指標和日誌匯出管線。除非已完整設定收集器端點與驗證資訊，否則請保持停用。`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry 端點`},help:{"v1-4rrd1x-4y":`用於 OpenTelemetry 匯出傳輸的收集器端點 URL，包含通訊協定與連接埠。請使用可連線且可信任的收集器端點，並在部署後監控資料擷取錯誤。`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry 緩衝區排送間隔（毫秒）`},help:{"v1-1moqogc-53":`定期將遙測資料從緩衝區排送至收集器的間隔，以毫秒為單位。增加此值可減少匯出頻率；在處理事件期間降低此值，可更快掌握狀況。`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry 標頭`},help:{"v1-s26t2a-52":`隨 OpenTelemetry 匯出請求傳送的額外 HTTP 請求標頭，通常用於租戶驗證或路由。請將機密資訊存放在由環境變數提供的值中，並避免加入不必要的標頭。`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`啟用 OpenTelemetry 日誌`},help:{"v1-12wo6rv-4k":`除了本機日誌輸出目的地之外，也啟用透過 OpenTelemetry 匯出日誌訊號。需要集中關聯各服務與代理程式的日誌時，請使用此功能。`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry 日誌端點`},help:{"v1-1vgzldu-40":`專用於日誌訊號的 OTLP/HTTP 端點。設定後，僅在匯出日誌時覆寫 diagnostics.otel.endpoint 和 OTEL_EXPORTER_OTLP_ENDPOINT。`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry 日誌匯出器`},help:{"v1-9bzywd-5q":`diagnostics.otel.logs 的日誌匯出目的地。使用 "otlp" 將日誌匯出至已設定的 OTLP 日誌端點；使用 "stdout" 在容器日誌管線中，於 stdout 每行輸出一筆 JSON 記錄；需要同時輸出至兩個目的地時，請使用 "both"。`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry 指標名稱前綴`},help:{"v1-1epdpi9-b2":`取代 OpenClaw 自有指標名稱的預設 "openclaw." 前綴。使用空字串可移除前綴，或使用以字母開頭、最多 128 個 ASCII 字母、數字、底線、句點、連字號與斜線組成的字串。請包含所需的分隔符號，例如 "acme."；標準 gen_ai.* 指標名稱不受影響。變更此值後，必須更新查詢舊名稱的儀表板與警示。`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`啟用 OpenTelemetry 指標`},help:{"v1-13r4cf4-4x":`啟用指標訊號匯出至已設定的 OpenTelemetry 收集器端點。若需使用執行階段健康狀態儀表板，請保持啟用；僅在必須盡量減少指標資料量時停用。`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry 指標端點`},help:{"v1-qlfh7x-47":`專用於指標訊號的 OTLP/HTTP 端點。設定後，僅在匯出指標時覆寫 diagnostics.otel.endpoint 和 OTEL_EXPORTER_OTLP_ENDPOINT。`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry 通訊協定`},help:{"v1-17ine8s-5e":`用於匯出遙測資料的 OTel 傳輸通訊協定。僅接受 "http/protobuf"；請執行 "openclaw doctor --fix" 以修復已儲存的舊版 "grpc" 值，或取得針對特定來源的手動編輯指引。`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry 追蹤取樣率`},help:{"v1-brcwep-50":`追蹤取樣率（0-1），控制匯出至可觀測性後端的追蹤流量比例。較低的取樣率可減少額外負荷與成本，較高的取樣率則可提高偵錯資料的完整度。`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry 服務名稱`},help:{"v1-1hpiqon-5d":`在遙測資源屬性中回報的服務名稱，用於在可觀測性後端識別此 Gateway 執行個體。請使用固定名稱，讓儀表板和警示在各次部署之間保持一致。`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`啟用 OpenTelemetry 追蹤`},help:{"v1-j7zrrp-4s":`啟用追蹤訊號匯出至已設定的 OpenTelemetry 收集器端點。需要延遲分析或偵錯追蹤時，請保持啟用；若只需要指標或日誌，則可停用。`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry 追蹤端點`},help:{"v1-8yw5p1-43":`特定訊號專用的 OTLP/HTTP 追蹤端點。設定後，僅在匯出追蹤資料時覆寫 diagnostics.otel.endpoint 和 OTEL_EXPORTER_OTLP_ENDPOINT。`}},discovery:{label:{"v1-l2sr05-9":`探索`},help:{"v1-1sqleij-4w":`服務探索設定，用於本機 mDNS 公告及選用的廣域存在訊號傳送。請將探索範圍限制在預期的網路內，以避免洩漏服務中繼資料。`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS 探索`},help:{"v1-vtbyyq-4w":`mDNS 探索設定群組，用於調整區域網路公告和探索行為。除非需要額外的中繼資料，否則一般區域網路探索請維持最小模式。`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS 探索模式`},help:{"v1-1p28pd5-2m":`mDNS 廣播模式（預設為 "minimal"，"full" 包含 cliPath/sshPort，"off" 停用 mDNS）。`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`廣域探索`},help:{"v1-1akkqjm-53":`廣域探索設定群組，用於將探索訊號公開至本機鏈路範圍之外。僅在刻意跨站點彙整 Gateway 存在資訊的部署中啟用。`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`廣域探索網域`},help:{"v1-rxrygo-4m":`用於廣域探索的選用單播 DNS-SD 網域，例如 openclaw.internal。若您刻意將 Gateway 探索資訊發布至本機 mDNS 範圍之外，請使用此設定。`}},env:{label:{"v1-1zc80q-b":`環境`},help:{"v1-1ao5po6-55":`環境匯入與覆寫設定，用於向 Gateway 程序提供執行階段變數。使用此區段來控制 Shell 環境載入及明確指定的變數注入行為。`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Shell 環境匯入`},help:{"v1-1gw487t-4y":`Shell 環境匯入控制項，用於在啟動時從登入 Shell 載入變數。若您依賴設定檔中定義的機密資訊或 PATH 自訂設定，請保持啟用。`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`啟用 Shell 環境匯入`},help:{"v1-5tiuup-5u":`啟用後，會在啟動初始化期間從使用者的 Shell 設定檔載入環境變數。開發用電腦請保持啟用；若服務環境受到嚴格限制，且已明確管理環境變數，則可停用。`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Shell 環境匯入逾時（毫秒）`},help:{"v1-nsk2yf-5c":`解析 Shell 環境所允許的最長時間，以毫秒為單位；超過此時間後會採用後備行為。縮短逾時時間可加快啟動速度；若 Shell 初始化作業較繁重，則可延長。`}},"env%2Evars":{label:{"v1-grhbhj-u":`環境變數覆寫`},help:{"v1-yxc3z7-5n":`明確指定的索引鍵／值環境變數覆寫，會合併至 OpenClaw 執行階段的程序環境。使用此設定可確保環境設定明確可控，而非僅依賴 Shell 設定檔的間接影響。`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Gateway 執行階段設定，涵蓋繫結模式、驗證、Control UI、遠端傳輸及運作安全控制。除非您有意讓受信任的本機介面以外的來源存取 Gateway，否則請保留保守的預設值。`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway 允許以 x-real-ip 作為後備`},help:{"v1-1wr3qmw-4c":`啟用後，在使用代理的情境下，若缺少 x-forwarded-for，則會改用 x-real-ip。除非您的入口架構需要此相容性行為，否則請保持停用。`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway 驗證`},help:{"v1-70b6ni-50":`Gateway HTTP/WebSocket 存取的驗證政策，包含模式、憑證、受信任代理行為及速率限制。所有非回送位址部署都應保持啟用驗證。`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Gateway 驗證允許 Tailscale 身分`},help:{"v1-vqtmgw-53":`設定後，允許透過受信任的 Tailscale 身分途徑通過 Gateway 驗證檢查。僅在 tailnet 身分安全機制完善，且操作人員工作流程依賴此功能時使用。`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Gateway 身分權限範圍授權`},help:{"v1-1h0zxy7-5n":`將已驗證的受信任代理或 Tailscale 身分對應至僅限該連線的操作人員權限範圍授權。電子郵件鍵值比對不區分大小寫；授權會在套用連線權限範圍上限前，擴充裝置的權限範圍。`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway 驗證模式`},help:{"v1-j8rodq-9t":`Gateway 驗證模式：依據您的邊緣架構選擇 "none"、"token"、"password" 或 "trusted-proxy"。權杖／密碼模式會選用已設定的密鑰（gateway.auth.token 或 gateway.auth.password）；用戶端可透過任一連線驗證欄位傳送密鑰。直接對外開放時請使用權杖／密碼模式；只有在經過安全強化且具備身分識別能力的代理後方，才使用 trusted-proxy。`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway 密碼`},help:{"v1-1ndt0u2-4g":`由 gateway.auth.mode=password 選用的共用密鑰。用戶端可透過 auth.token 或 auth.password 傳送此密鑰。Tailscale Funnel 必須使用密碼模式。`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Gateway 驗證速率限制`},help:{"v1-1kstr42-54":`登入／驗證嘗試的節流控制，可降低 Gateway 邊界遭受憑證暴力破解的風險。在對外開放的環境中請保持啟用，並依據流量基準調整閾值。`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway 權杖`},help:{"v1-16i7cxs-5q":`由 gateway.auth.mode=token 選定的共用密鑰，這是新本機初始設定的預設方式。用戶端可透過 auth.token 或 auth.password 傳送此密鑰。繫結至非回送位址時，必須啟用驗證模式。`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway 受信任 Proxy 驗證`},help:{"v1-12fsi5d-58":`受信任 Proxy 的驗證標頭對應設定，適用於注入使用者宣告的上游身分提供者。僅應搭配已知的 Proxy CIDR 範圍和嚴格的標頭允許清單使用，以防止身分標頭遭到偽造。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Cloudflare Access OIDC GitHub 身分`},help:{"v1-1puth4k-6t":`來自所選 Cloudflare Access OIDC 提供者的已驗證 GitHub 身分（選用）。需要標準的 Access 電子郵件與斷言標頭。若缺少宣告，個人資料將維持僅含電子郵件的狀態；既有的個人資料角色與共同作者偏好設定會予以保留。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`GitHub 帳號 ID 宣告`},help:{"v1-pcaaw7-57":`轉送的 OIDC 宣告的確切名稱，其值為已驗證、以正整數十進位字串表示的 GitHub 帳號 ID。請設定 Access，透過 oidc_fields 轉送此宣告；切勿使用未經驗證且可由使用者編輯的宣告。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access 簽發者`},help:{"v1-gykv03-56":`受信任的 Cloudflare Access 團隊的確切 HTTPS 來源，例如 https://example.cloudflareaccess.com，結尾不含斜線。其他簽發者的宣告不會提供 GitHub 身分。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC 提供者 ID`},help:{"v1-kbyo5w-44":`受信任的 OIDC 整合所使用的確切 Access 身分提供者 ID。僅有提供者顯示名稱或相符的宣告名稱，並不足以建立信任。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`受信任 Proxy 裝置自動核准`},help:{"v1-uh32ha-6z":`選用政策，可在受信任 Proxy 驗證後，自動核准新的瀏覽器與原生 UI 操作員裝置，以及使用相同金鑰的權限範圍升級。授予的權限受 deviceAutoApprove.scopes 限制；若 Proxy 提供 x-openclaw-scopes 標頭，也會受該標頭限制。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`啟用受信任 Proxy 裝置自動核准`},help:{"v1-1nntwls-78":`反向 Proxy 驗證允許的使用者後，自動核准新的瀏覽器與原生 UI 操作員裝置，以及使用相同金鑰的權限範圍升級。預設值：false。僅當 Proxy 的身分驗證邊界足夠安全、可取代手動裝置配對時，才應啟用。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`受信任 Proxy 裝置自動核准權限範圍`},help:{"v1-raeila-g3":`授予自動核准的操作員裝置的最大權限範圍。預設為 operator.read、operator.write、operator.approvals 和 operator.questions。請求的權限範圍以此清單為上限；未指定權限範圍的請求會獲得此清單中的權限。未設定時，自動核准也會為舊版 UI 用戶端加入 operator.questions；明確指定的清單則絕不會擴大。明確列出 operator.admin 會讓每位透過 Proxy 驗證的使用者自動獲准取得完整管理員權限，並讓未指定權限範圍的請求自動取得完整管理員權限；這也會觸發嚴重等級的安全性稽核發現事項，以及 Gateway 啟動警告。`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway 綁定位址模式`},help:{"v1-1unqude-4y":`網路綁定設定檔：使用 "auto"、"lan"、"loopback"、"custom" 或 "tailnet" 來控制介面的對外開放範圍。若僅限本機運作，請保留 "loopback"；"auto" 可能會對外開放所有介面。`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI 代理程式`},help:{"v1-1qqo8m2-5a":`讓 Control UI 探索 Gateway 工作階段目錄所提供的外部 CLI 工作階段引擎。預設啟用；停用後，即可防止從新工作階段的模型選擇器啟動這些引擎。`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`啟用 CLI 代理程式`},help:{"v1-ufu7fx-8p":`設為 true 時，會在 Control UI 新工作階段的模型選擇器中顯示目錄提供的 CLI 代理程式（預設：true）。設為 false 可停用 CLI 代理程式及原生 CLI 工作階段建立功能。只會列出宣告支援建立工作階段的目錄；若 Gateway 未宣告支援工作階段目錄，選擇器會保持隱藏。`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Control UI 託管設定，包括啟用狀態、路徑設定，以及瀏覽器來源與驗證的安全強化行為。請盡量縮小 UI 的對外暴露範圍，並在部署至網際網路前搭配強式驗證控制措施。`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Control UI 允許的來源`},help:{"v1-1stgitk-9i":`Control UI/WebChat WebSocket 連線允許的瀏覽器來源（僅限完整來源，例如 https://control.example.com）。非回送位址的 Control UI 部署必須設定此項，除非已明確啟用具危險性的 Host 標頭後備機制。設定為 ["*"] 表示允許任何瀏覽器來源，除非是在嚴格控管的本機測試環境中，否則應避免使用。`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`允許 Control UI 使用外部嵌入網址`},help:{"v1-obwpfg-6s":`具危險性的開關，允許託管的嵌入內容載入外部 http(s) 絕對網址。除非您的 Control UI 有意嵌入受信任的第三方頁面，否則請保持關閉；託管的 /__openclaw__/canvas 和 /__openclaw__/a2ui 文件不需要此設定。`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`自動擷取連結的網站圖示`},help:{"v1-bn9u34-ag":`透過 Gateway 擷取連結的網站圖示及瀏覽器分頁的社群分享預覽（預設啟用）。瀏覽器分頁卡片會載入公開網頁中繼資料及頁面宣告的圖片，不使用瀏覽器 Cookie 或網站憑證。所有請求皆經過嚴格的 SSRF 檢查，且 HTML／圖片處理設有上限。設為 false 可停用網站圖示與頁面預覽的自動擷取；即時瀏覽器螢幕截圖不受影響。`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Control UI 基底路徑`},help:{"v1-1dx68ar-1w":`提供 Control UI 的選用網址前綴（例如 /openclaw）。`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Control UI 社群邀請`},help:{"v1-1rz3zsx-73":`在此 Gateway 提供的 Control UI 中顯示 Discord 社群邀請（預設開啟）。設為 false 可對使用此 UI 部署的所有瀏覽器隱藏邀請。變更會在瀏覽器重新整理或重新連線後生效；重新啟用時，會保留瀏覽器本機的關閉紀錄。`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`允許使用 Host 標頭作為來源備援（危險）`},help:{"v1-1t1qi4c-7v":`此開關具有危險性，會在 Control UI/WebChat 的 WebSocket 檢查中啟用以 Host 標頭為基礎的來源備援。若您的部署刻意採用以 Host 標頭為基礎的來源政策，可使用此模式；但仍建議明確設定 gateway.controlUi.allowedOrigins，作為強化安全性的預設做法。`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Control UI 嵌入沙箱模式`},help:{"v1-d54l3a-7c":'託管的 Control UI 嵌入內容所使用的 iframe 沙箱政策。"strict" 會停用指令碼，"scripts" 允許互動式嵌入內容，同時維持來源隔離（預設值），而 "trusted" 會加入 `allow-same-origin`，供確實需要更高權限的同站文件使用。'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`啟用 Control UI`},help:{"v1-1hhyymc-4w":`設為 true 時，會透過 Gateway HTTP 程序提供 Gateway Control UI。若要進行本機管理，請保持啟用；若已由外部控制介面取代，則可停用。`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI 環境`},help:{"v1-paarso-4n":`選用的公開環境識別資訊，會顯示於 Control UI 色帶、代理程式頭像、膠囊標籤、瀏覽器標題及網站圖示中。省略此設定即可保留預設外觀。`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Control UI 環境色彩`},help:{"v1-mp6cta-2i":`具名環境色階：teal、amber、purple、coral、pink、blue、green、red 或 gray。`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Control UI 環境標籤`},help:{"v1-1njve3z-3z":`顯示於 Control UI 與瀏覽器分頁中的環境標籤；前後的空白會被移除，且標籤必須包含 1 至 24 個字元。`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`實驗性 Control UI 功能`},help:{"v1-1qobi2m-3g":`可自行選擇啟用的 Control UI 實驗性功能。這些功能可能隨版本變更，除非明確啟用，否則一律停用。`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`自訂外掛程式使用者介面`},help:{"v1-108u6ts-9e":`允許使用者安裝的外掛程式在 Control UI 中執行原生 JavaScript（預設值：false）。內建外掛程式的檢視仍可使用。自訂介面會共用已登入操作者的 Gateway 權限；請僅對信任的外掛程式啟用。變更無須重新啟動 Gateway 即可套用。重新載入已開啟的 Control UI 頁面即可清除先前載入的外掛程式程式碼。`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Control UI GitHub 服務憑證`},help:{"v1-1p31phh-d6":`由 SecretRef 支援的服務憑證，用於在沒有受控身分識別的情況下，進行 Control UI 專案探索及 GitHub 懸停預覽。懸停預覽會優先使用所選代理程式設定的 GitHub 身分識別；若未覆寫，則繼承系統身分識別。建議明確設定，以釐清服務歸屬。省略此項可保留從共用 Gateway 程序環境取得 GH_TOKEN/GITHUB_TOKEN 的備援機制。若明確設定的憑證無法使用，系統將拒絕存取。`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Control UI 資源根目錄`},help:{"v1-elck04-25":`Control UI 資源的選用檔案系統根目錄（預設為 dist/control-ui）。`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Control UI 工作階段觀察器`},help:{"v1-1ahs80-8a":`使用各代理程式的輔助模型，為已訂閱的 Control UI 用戶端產生即時工作階段狀態摘要（預設開啟）。設為 false 可在整個 Gateway 停用觀察器模型呼叫；將 agents.defaults.utilityModel 設為空字串，則會為未覆寫此設定的代理程式停用輔助模型觀察功能。`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Gateway 自訂繫結主機`},help:{"v1-lwjcyo-4d":`用於自訂繫結的 IPv4 位址。使用特定 IPv4 位址時，也需要在 127.0.0.1 上使用相同的 Gateway 連接埠；除非需要對所有網路介面開放，否則請避免使用 0.0.0.0。`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`Gateway HTTP API`},help:{"v1-ebtex7-4j":`Gateway HTTP API 設定，整合端點開關與面向傳輸層的 API 開放控制。請僅啟用必要的端點，以縮小攻擊面。`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Gateway HTTP 端點`},help:{"v1-1a0r104-55":`Gateway API 範圍內的 HTTP 端點功能開關，用於相容性路由和選用整合。請審慎啟用端點，並在推出後監控存取模式。`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions 端點`},help:{"v1-1271mpb-2b":"啟用與 OpenAI 相容的 `POST /v1/chat/completions` 端點（預設值：false）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`OpenAI Chat Completions 圖片限制`},help:{"v1-xgscw1-20":"與 OpenAI 相容的 `image_url` 部分的圖片擷取與驗證控制項。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions 圖片 MIME 允許清單`},help:{"v1-1guijf3-1t":"`image_url` 部分允許的 MIME 類型（清單不區分大小寫）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions 允許圖片 URL`},help:{"v1-55cb3n-47":"允許伺服器端透過 URL 擷取 `image_url` 部分的圖片（預設值：false；仍支援資料 URI）。將此設定設為 `false` 可完全停用 URL 擷取。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions 圖片位元組數上限`},help:{"v1-d920yx-1s":"每張擷取或解碼的 `image_url` 圖片的位元組數上限（預設值：10MB）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions 圖片重新導向次數上限`},help:{"v1-1enujsk-1z":"擷取 `image_url` 網址時允許的 HTTP 重新導向次數上限（預設：3）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions 圖片逾時時間（毫秒）`},help:{"v1-89w2b9-1x":"擷取 `image_url` 網址的逾時時間，以毫秒為單位（預設：10000）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions 圖片 URL 允許清單`},help:{"v1-n4hlt1-4r":"用於擷取 `image_url` 網址的選用主機名稱允許清單；支援完整主機名稱比對及 `*.example.com` 萬用字元。清單為空或省略時，表示不限制主機名稱。"}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway HTTP 安全性標頭`},help:{"v1-n8z1hb-44":`由 Gateway 程序本身套用的選用 HTTP 回應安全性標頭。若 TLS 在反向 Proxy 終止，建議優先在該處設定這些標頭。`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`嚴格傳輸安全性標頭`},help:{"v1-1buwhc3-3v":`Strict-Transport-Security 回應標頭的值。僅應在您完全控制的 HTTPS 來源上設定；使用 false 可明確停用。`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway 模式`},help:{"v1-nfjirv-5m":`Gateway 運作模式："local" 在此主機上執行頻道與代理程式執行環境，而 "remote" 則透過遠端傳輸連線。除非您刻意採用分離式遠端 Gateway 拓撲，否則請保留 "local"。`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`啟用 Gateway 節點 Skills`},help:{"v1-1xwu6at-3g":`接受已配對節點在連線期間發布的技能（預設：true）。設為 false 可忽略節點發布的技能。`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Gateway 節點瀏覽器模式`},help:{"v1-oeu1nc-69":`節點瀏覽器路由（"auto" = 優先使用主機瀏覽器，本機功能無法使用時，使用單一已連線的瀏覽器節點；"manual" = 必須明確選取節點或設定固定節點；"off" = 停用節點路由）。`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Gateway 節點瀏覽器固定節點`},help:{"v1-1cykty2-1p":`將瀏覽器路由固定至特定節點 ID 或名稱（選填）。`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Gateway 節點允許清單（額外命令）`},help:{"v1-6l4otb-5m":"除 Gateway 預設允許的命令外，額外允許的 node.invoke 命令（命令字串陣列）。在此啟用危險命令屬於涉及安全性的覆寫設定，會由 `openclaw security audit` 標示。"}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Gateway 節點拒絕清單`},help:{"v1-u7c8wx-53":"要封鎖的節點命令名稱，即使出現在節點宣告或預設允許清單中也會封鎖（僅精確比對命令名稱，例如 `system.run`；不會檢查該命令內的 shell 文字）。"}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway 節點配對`},help:{"v1-gldsi2-4s":`節點配對原則設定。預設啟用經 SSH 驗證的自動核准；除非明確設定受信任的 CIDR/IP 允許清單，否則 CIDR 自動核准會維持停用。`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Gateway 節點配對自動核准 CIDR`},help:{"v1-1m6jsxj-6x":`可自行啟用的 CIDR/IP 允許清單，用於自動核准未要求任何權限範圍的節點角色裝置首次配對。未設定時停用。操作員、瀏覽器、Control UI，以及涉及任何角色、權限範圍、中繼資料或公開金鑰升級的配對，仍須手動核准。`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Gateway 節點配對本機自動核准`},help:{"v1-glzm36-41":`無提示地核准受信任的本機配對與存取權限升級（預設：true）；設為 false 可改為逐一明確核准每部裝置，但便利性會降低。`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Gateway 節點配對 SSH 驗證`},help:{"v1-1e4da92-ct":"對節點角色裝置的首次配對進行 SSH 驗證後自動核准（預設：啟用）。Gateway 會透過 SSH 反向連線至配對主機（BatchMode、嚴格主機金鑰檢查），且僅在遠端 `openclaw node identity` 的輸出與待核准的裝置金鑰相符時核准。設為 false 可停用 SSH 驗證（與 autoApproveCidrs 無關，後者仍保持作用）；若要僅允許手動配對，還需取消設定 autoApproveCidrs。傳入物件可覆寫 user/identity/timeoutMs/cidrs。"}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Gateway 節點外掛工具`},help:{"v1-1c24iq3-28":`控制已配對的節點是否可發布代理可見的外掛工具描述資訊。`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`啟用 Gateway 節點外掛工具`},help:{"v1-14lgfu6-47":`接受由已配對節點發佈、對代理程式可見的外掛工具描述資訊（預設值：true）。設為 false 可忽略並移除所有由節點發佈的外掛工具。`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway 連接埠`},help:{"v1-for8t5-54":`Gateway 接聽器用於 API、Control UI 及面向通道的傳入路徑的 TCP 連接埠。請使用專用連接埠，避免與反向代理或本機開發服務衝突。`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway 入口網站`},help:{"v1-1v2lkw9-1c":`入口網站發佈與私有傳入設定。`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`私有入口網站傳入設定`},help:{"v1-20w4gq-69":`可選用由管理員管理的私有 HTTPS 萬用字元反向代理。將原始 Host、路徑及 WebSocket 升級請求轉送至專用的回送監聽器。入口網站仍需要 Bearer 驗證。需要重新啟動 Gateway。`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`入口網站萬用字元網域`},help:{"v1-1ipbfad-53":`用於隨機入口網站子網域的裸 DNS 網域（例如 previews.example.net）。請以私有方式設定萬用字元 DNS 和 HTTPS；請勿共用 Gateway 或 Control UI 的主機名稱命名空間。`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`入口網站傳入回送連接埠`},help:{"v1-1mb98cv-4g":`專用的回送 HTTP 連接埠，用於接收來自私有萬用字元 HTTPS 代理的流量。必須與 Gateway 連接埠不同。這是後端連接埠，而非公開的 HTTPS 連接埠。`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Gateway 公開來源`},help:{"v1-17vekvx-87":`可從外部存取的 Gateway HTTPS 來源。僅 localhost、127.0.0.1 或 [::1] 允許使用 HTTP。各請求者的 MCP OAuth 會使用此來源建立位於 /oauth/mcp/callback 的回呼 URL；通道工作階段連結與外掛產生的檢視器連結則使用此來源存取 Control UI 和 Gateway 路由。`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway 推播傳遞`},help:{"v1-h23oz7-5s":`Gateway 需要喚醒已配對裝置或向其傳送通知時使用的推播傳遞設定。正式 iOS 組建所使用的中繼式 APNs 可在此設定；本機或手動組建的直接 APNs 驗證仍透過環境變數設定。`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway APNs 傳遞`},help:{"v1-4bbafr-4e":`與此 Gateway 配對的 iOS 裝置所使用的 APNs 傳遞設定。透過外部推播中繼服務註冊的正式 App Store 組建，請使用中繼設定。`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway APNs 中繼`},help:{"v1-7glbel-6x":`透過轉送服務傳送 APNs 通知的外部轉送設定。在已配對的官方 iOS 版本發布透過轉送服務的註冊資訊後，Gateway 預設會使用託管的 OpenClaw 轉送服務，或使用此自訂轉送服務來執行 push.test、喚醒提醒及重新連線喚醒。`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Gateway APNs 轉送服務基底 URL`},help:{"v1-1o8mgnq-69":`官方 App Store iOS 版本所使用的外部 APNs 轉送服務的選用自訂基底 HTTPS URL。請讓此 URL 與 iOS 版本內建的轉送服務 URL 保持一致，確保註冊與傳送流量都連到同一個部署。`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Gateway APNs 轉送逾時（毫秒）`},help:{"v1-a0jkb1-4z":`Gateway 向 APNs 轉送服務發出傳送請求的逾時時間，以毫秒為單位（預設：10000）。轉送服務或網路較慢時可增加此值，或降低此值以更快判定喚醒嘗試失敗。`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`重新載入設定`},help:{"v1-d02mvq-4w":`即時重新載入設定的策略，決定如何套用編輯內容，以及何時觸發完整重新啟動。除非正在對重新載入的內部機制進行偵錯，否則請保留混合模式，以最安全的方式更新運作中的設定。`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`設定重新載入模式`},help:{"v1-1q1etcf-3m":`控制設定編輯內容的套用方式："off" 會忽略即時編輯，"hybrid" 則會先套用可安全熱更新的變更，再於必要時重新啟動。`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`遠端 Gateway`},help:{"v1-6xv7gd-5a":`當此執行個體代理連線至另一台執行環境主機時，透過直接連線或 SSH 傳輸的遠端 Gateway 連線設定。只有在刻意設定為分離主機運作時，才應使用遠端模式。`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`遠端 Gateway 邊緣驗證標頭`},help:{"v1-jg9p7d-5o":`以密鑰提供值的 HTTP 標頭，用於傳送至所設定遠端 Gateway 前方的身分感知 Proxy。標頭僅透過 WSS 傳送至與 gateway.remote.url 完全相符的來源，且絕不跟隨重新導向。`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`遠端 Gateway 密碼`},help:{"v1-16jc0yx-7y":`透過密碼欄位傳送的共用密鑰，用於向遠端閘道驗證此用戶端。伺服器的 gateway.auth.mode 會選用其設定的密鑰；用戶端的權杖或密碼欄位皆可接受。請在外部管理此密鑰，避免在提交至版本控制的設定中使用明文值。`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`遠端 Gateway SSH 主機金鑰原則`},help:{"v1-7qoxtb-49":`macOS SSH 主機金鑰驗證原則。"strict" 要求使用已受信任的主機金鑰；"openssh" 則明確交由實際生效的 OpenSSH 設定處理。`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`遠端 Gateway SSH 身分`},help:{"v1-hz2hsm-1f":`選填的 SSH 身分檔案路徑（傳遞給 ssh -i）。`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`遠端 Gateway SSH 目標`},help:{"v1-85w39w-2t":`透過 SSH 連線的遠端閘道（將閘道連接埠透過通道轉送至 localhost）。格式：user@host 或 user@host:port。`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`遠端 Gateway TLS 指紋`},help:{"v1-1ri16lk-23":`遠端閘道的預期 sha256 TLS 指紋（固定指紋以防止中間人攻擊）。`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`遠端 Gateway 權杖`},help:{"v1-1pb9q8w-7v":`透過 token 欄位傳送的共用密鑰，用於向遠端 Gateway 驗證此用戶端的身分。伺服器的 gateway.auth.mode 會選擇其設定的密鑰；用戶端的 token 或 password 欄位皆可接受。請透過密鑰／環境變數替換來儲存，並在遠端 Gateway 的驗證設定變更時一併輪替。`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`遠端 Gateway 傳輸方式`},help:{"v1-1acfs7m-54":`遠端連線的傳輸方式："direct" 使用設定的 URL 連線，而 "ssh" 則透過 SSH 建立通道。若需要加密通道且不想對外開放遠端連接埠，請使用 SSH。`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`遠端 Gateway URL`},help:{"v1-va7exe-1b":`遠端 Gateway WebSocket URL（ws:// 或 wss://）。`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway 操作員角色`},help:{"v1-b59sc5-6w":`供團隊 Gateway 使用的選用操作員角色，與個人資料綁定。每個具名角色都會控制對他人工作階段的存取、沙箱隔離、工作階段與執行的代理程式，以及授予的操作員權限範圍；省略此區段會保留現有的操作員行為。`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`預設操作員角色`},help:{"v1-1v8add8-4u":`設定操作員角色時，此為必要角色，會指派給未明確指派有效角色的已驗證個人資料。其名稱必須符合已設定的角色定義。`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`操作員角色定義`},help:{"v1-uv91an-53":`由管理員命名且不可為空的角色定義，整合了套用至已驗證使用者個人資料的封閉式工作階段共用、沙箱隔離、代理程式存取及操作員權限範圍原則。`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`操作員角色定義`},help:{"v1-p8tfws-6q":`一個具名的操作員角色。每項定義都必須明確提供其工作階段分享政策、允許用於工作階段與執行的代理程式，以及操作員權限範圍上限，也可以要求新建立的工作階段採用沙箱隔離，並指定外掛程式存取政策。`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`操作員角色存取政策外掛程式`},help:{"v1-1gq4q08-9n":`選填的精確外掛程式 ID，其 Gateway 存取政策必須授權此角色。若外掛程式不存在、已停用、載入失敗，或未提供目前有效的授權，則會拒絕存取。無法使用的外掛程式 ID 仍視為有效設定，以便獨立的工作人員角色與 Gateway 擁有者修復存取權。省略此欄位不會新增任何外掛程式相依性。`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`操作員角色允許的代理程式`},help:{"v1-fvun18-4v":`此角色建立工作階段或啟動執行作業時可用的代理程式：設為 "*" 以允許所有代理程式，列出代理程式 ID 以僅允許指定的代理程式，或使用空白清單以停用這兩項功能。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`操作員角色沙箱隔離`},help:{"v1-sknx21-66":`新建工作階段的執行隔離："inherit"（預設值）使用代理程式政策；"required" 則永久要求使用沙箱，即使代理程式的沙箱模式已關閉也一樣，且在後端無法使用時會拒絕執行。`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`操作員角色權限範圍上限`},help:{"v1-1selr2i-4s":`授予此角色的操作員權限範圍限定清單，作為其連線權限上限。請求的、配對的、依身分授予的，以及升級的權限範圍，都會與此清單取交集。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`操作員角色工作階段存取權`},help:{"v1-hsoiop-45":`針對其他已驗證身分的人員所建立的工作階段，授予此角色的工作階段共用權限；每個人仍可存取自己擁有的工作階段。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`操作員角色對其他工作階段的存取權`},help:{"v1-vf8umx-5r":`對其他人工作階段的存取權限："none" 會隱藏這些工作階段，"view" 允許讀取，"suggest" 允許使用建議流程，"write" 則允許參與。明確指定的工作階段成員資格可授予額外的存取權限。`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Tailscale 整合設定，用於透過 Serve/Funnel 對外提供存取，以及在 Gateway 啟動／結束時處理生命週期。除非您的部署刻意依賴 Tailscale 入口流量，否則請保持關閉。`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale 模式`},help:{"v1-6l2099-5a":`Tailscale 發布模式："off"、"serve" 或 "funnel"，用於設定私人或公開的存取路徑。僅限 tailnet 存取時請使用 "serve"；只有需要從公用網際網路存取時，才使用 "funnel"。`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway Tailscale 外部 Funnel 遷移防護`},help:{"v1-1mntkor-7q":`已棄用的 mode='serve' 遷移防護。如果外部 Funnel 仍指向一般的 Gateway 接聽器，OpenClaw 會維持對外存取設定不變，並警告：在設定密碼驗證並將模式遷移至 'funnel' 之前，只有經外掛程式驗證的 webhook 仍可使用。`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`操作員終端機`},help:{"v1-18f5rgm-8b":`提供給 Control UI 和行動用戶端的操作員終端機：在 Gateway 主機上執行、以 PTY 為基礎的 shell，僅限具有管理員範圍權限的操作員工作階段使用。它會在目標代理的工作區中啟動；對於完全沙箱化的代理（sandbox.mode 'all'），系統會拒絕提供終端機，而不是傳回不受限制的主機 shell。`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`操作員終端機分離工作階段逾時`},help:{"v1-k6qbgr-9e":`終端機工作階段在連線中斷（筆記型電腦進入睡眠、頁面重新載入）後保留的秒數，期間仍可透過 terminal.attach 重新連接，並重播最近的輸出。設為 0 會在連線中斷時立即終止工作階段。預設值：300（5 分鐘）。已分離的工作階段會繼續執行命令，因此在共用或對外開放的主機上，請縮短此時間。`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`啟用操作人員終端機`},help:{"v1-1nez06v-7p":`為具備管理員權限範圍的用戶端啟用操作員終端機（預設值：true）。這會提供使用 Gateway 程序環境的瀏覽器／行動裝置 shell；若部署環境不應讓管理員操作員取得主機 shell，請設為 false 以停用。變更無須重新啟動 Gateway 即可套用。`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`操作人員終端機命令殼層`},help:{"v1-19mfe6t-5i":`操作人員終端機啟動的命令殼層執行檔。保留未設定狀態以使用主機的登入命令殼層（Unix 上的 $SHELL、Windows 上的 %ComSpec%），或指定固定的直譯器，確保操作人員環境一致。`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway TLS`},help:{"v1-1dx77dq-4z":`用於直接在 Gateway 程序中終止 HTTPS 連線的 TLS 憑證與金鑰設定。在正式環境中請明確指定憑證，並避免在不受信任的網路上以明文傳輸。`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway TLS 自動產生憑證`},help:{"v1-1ld6uiu-4w":`未明確設定檔案時，自動產生一組本機 TLS 憑證與金鑰。僅適用於本機／開發環境；處理正式環境流量時，請改用正式憑證。`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Gateway TLS CA 路徑`},help:{"v1-andqlu-52":`選用的 CA 憑證組合路徑，用於在 Gateway 邊界驗證用戶端或滿足自訂信任鏈需求。部署中使用私有 PKI 或自訂憑證鏈時，請使用此設定。`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Gateway TLS 憑證路徑`},help:{"v1-1wznaof-4q":`啟用 TLS 時，Gateway 所使用的 TLS 憑證檔案在檔案系統中的路徑。請使用受管理的憑證路徑，並確保自動續期作業使用相同位置。`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`啟用 Gateway TLS`},help:{"v1-ykhwp0-4o":`在 Gateway 接聽器上啟用 TLS 終止，讓用戶端直接透過 HTTPS/WSS 連線。直接對網際網路開放或位於任何不受信任的網路邊界時，請保持啟用。`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Gateway TLS 金鑰路徑`},help:{"v1-15knri0-4i":`啟用 TLS 時，Gateway 所使用的 TLS 私密金鑰檔案在檔案系統中的路徑。請限制此金鑰檔案的存取權限，並依照您的安全政策定期輪替金鑰。`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway 工具開放政策`},help:{"v1-1ffol26-5a":`Gateway 層級的工具開放允許／拒絕政策，可獨立於代理程式／工具設定檔，限制執行階段可用的工具。可用於概括性的緊急控管及正式環境安全強化。`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway 工具允許清單`},help:{"v1-163khb1-4y":`明確指定的 Gateway 層級工具允許清單，適用於只希望在執行階段提供少量工具的情況。請用於必須嚴格控管工具範圍的受限環境。`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway 工具拒絕清單`},help:{"v1-1lhssnf-4o":`明確設定的 Gateway 層級工具拒絕清單，即使較低層級的政策允許，也會封鎖高風險工具。使用拒絕規則進行緊急應變，並強化縱深防禦。`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Gateway 信任的 Proxy CIDR`},help:{"v1-n5zcvf-4f":`允許提供轉送用戶端身分標頭的上游 Proxy CIDR/IP 允許清單。請將此清單限制在最小必要範圍，避免不受信任的中繼節點冒充使用者。`}},hooks:{label:{"v1-j9ywl7-5":`掛鉤`},help:{"v1-1mzh0ry-5v":`用於將外部事件對應至 OpenClaw 喚醒或代理程式動作的傳入 Webhook 自動化介面。在向信任網路以外開放此介面之前，請先透過明確的權杖、工作階段及代理程式控制措施，嚴格限制存取。`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`掛鉤允許的代理程式 ID`},help:{"v1-hree88-7c":`掛鉤請求與對應可指定的實際代理程式 ID 允許清單，也涵蓋省略 agentId 時的預設代理程式路由。使用此設定可將自動化事件限制於專用服務代理程式，並在掛鉤權杖外洩時縮小影響範圍。`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`掛鉤允許的工作階段金鑰前綴`},help:{"v1-b346oh-4r":`啟用呼叫端提供金鑰的功能時，傳入掛鉤請求可接受的工作階段金鑰前綴允許清單。請使用範圍有限的前綴，防止任意工作階段金鑰注入。`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`允許掛鉤請求提供工作階段金鑰`},help:{"v1-11n9ps-52":`設為 true 時，允許呼叫端在掛鉤請求中提供工作階段金鑰，以便由呼叫端控制路由。除非受信任的整合方明確需要自訂工作階段串接，否則請維持 false。`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`掛鉤預設工作階段金鑰`},help:{"v1-bzdgkn-57":`當請求未透過允許的管道提供工作階段金鑰時，掛鉤傳遞所使用的備援工作階段金鑰。請使用穩定且限定範圍的金鑰，避免混合不相關的自動化對話。`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`啟用掛鉤`},help:{"v1-1mixmjf-4n":`啟用掛鉤端點及對應執行流程，以處理傳入的 webhook 請求。除非您正在將外部事件路由至 Gateway，否則請保持停用。`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail 掛鉤`},help:{"v1-4cibmt-4r":`Gmail 推播整合設定，用於 Pub/Sub 通知及選用的本機回呼服務。請盡可能將使用範圍限於專用的 Gmail 自動化帳戶。`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Gmail 掛鉤帳戶`},help:{"v1-12l1h96-4v":`此掛鉤整合中用於 Gmail 監看／訂閱作業的 Google 帳戶識別碼。請使用專用的自動化信箱帳戶，以隔離作業權限。`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`允許 Gmail 掛鉤使用不安全的外部內容`},help:{"v1-1w3gdvs-55":`啟用後，允許經過較少安全清理的外部 Gmail 內容進入處理流程。請保持停用以維持較安全的預設設定，僅在郵件串流可信且轉換作業受控時啟用。`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Gmail 掛鉤回呼 URL`},help:{"v1-19fhn6q-4z":`Gmail 或中介服務呼叫的公開回呼 URL，用於將通知傳遞至此掛鉤流程。請使用權杖驗證並限制網路存取範圍，以保護此 URL。`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail 掛鉤包含內文`},help:{"v1-14cf1c3-52":`設為 true 時，擷取並包含電子郵件內文，以供下游對應或代理處理。除非需要內文，否則請保持 false，因為這會增加酬載大小及資料敏感性。`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Gmail 掛鉤標籤`},help:{"v1-9zpdg8-4g":`選用的 Gmail 標籤篩選器，用於限制哪些帶有標籤的郵件會觸發掛鉤事件。請縮小篩選範圍，避免大量無關的收件匣郵件湧入自動化流程。`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Gmail 掛鉤內文位元組數上限`},help:{"v1-2aaxx1-4b":`啟用 includeBody 時，每個事件可處理的 Gmail 酬載位元組數上限。請採用保守的限制，以降低處理過大郵件的成本與風險。`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Gmail 掛鉤模型覆寫`},help:{"v1-1var65t-59":`選用的模型覆寫設定，適用於信箱自動化需要專用模型行為時，由 Gmail 觸發的執行作業。除非信箱任務需要特化處理，否則請保持未設定，以沿用代理的預設值。`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Gmail 掛鉤推播權杖`},help:{"v1-h1vx01-4o":`Gmail 推播掛鉤回呼在處理通知前必須提供的共用密密權杖。請使用環境變數替換；若回呼端點對外開放，請定期輪替權杖。`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Gmail 掛鉤續訂間隔（分鐘）`},help:{"v1-pr1z9-49":`Gmail 監看訂閱的續訂頻率，以分鐘為單位，用於防止訂閱到期。請設定為短於供應商的到期時限，並透過記錄監控續訂失敗情況。`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Gmail 掛鉤本機伺服器`},help:{"v1-hom4wq-54":`本機回呼伺服器設定區塊，用於直接接收 Gmail 通知，無需獨立的流量入口層。僅在此程序應自行處理 webhook 傳入流量時啟用。`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Gmail 掛鉤伺服器繫結位址`},help:{"v1-55bieu-4d":`直接提供掛鉤服務時，本機 Gmail 回呼 HTTP 伺服器使用的繫結位址。除非明確需要外部流量入口，否則請僅繫結至回送位址。`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Gmail 掛鉤伺服器路徑`},help:{"v1-1jqhcw4-4h":`本機 Gmail 回呼伺服器上用於接收推播通知的 HTTP 路徑。請確保此路徑與訂閱設定一致，以免遺漏事件。`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Gmail 掛鉤伺服器連接埠`},help:{"v1-1yku7dz-43":`啟用 serve 模式時，本機 Gmail 回呼 HTTP 伺服器使用的連接埠。請使用專用連接埠，以免與 Gateway 或控制介面衝突。`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail 掛鉤訂閱`},help:{"v1-127h8vg-5b":`Gateway 用來從已設定的主題接收 Gmail 變更通知的 Pub/Sub 訂閱。請明確界定訂閱的擁有權，以免多個取用者發生非預期的競爭。`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Gmail 掛鉤 Tailscale`},help:{"v1-7jzidp-4l":`Tailscale 對外開放設定區塊，用於透過 Serve/Funnel 路由發布 Gmail 回呼。在啟用任何公開流量入口路徑之前，請先使用私人 tailnet 模式。`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Gmail 掛鉤 Tailscale 模式`},help:{"v1-vhm395-4u":`用於 Gmail 回呼的 Tailscale 對外開放模式："off"、"serve" 或 "funnel"。私人 tailnet 傳遞請使用 "serve"，只有需要從公用網際網路接收連入流量時才使用 "funnel"。`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Gmail 掛鉤 Tailscale 路徑`},help:{"v1-fr8qi-4m":`啟用後，由 Tailscale Serve/Funnel 發布、用於轉送 Gmail 回呼的路徑。請確保此路徑與 Gmail webhook 設定一致，讓請求能送達預期的處理常式。`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Gmail 掛鉤 Tailscale 目標`},help:{"v1-1twwxge-47":`Tailscale Serve/Funnel 轉送至的本機服務目標（例如 http://127.0.0.1:8787）。請明確指定迴路位址目標，避免路由不明確。`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Gmail 掛鉤思考覆寫設定`},help:{"v1-17owk9q-4z":`針對 Gmail 觸發的代理程式執行，覆寫思考投入程度："off"、"minimal"、"low"、"medium" 或 "high"。例行收件匣自動化作業請採用適度的預設值，以控制成本與延遲。`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Gmail 掛鉤 Pub/Sub 主題`},help:{"v1-iled0e-4p":`Gmail 監看功能用於發布此帳戶變更通知的 Google Pub/Sub 主題名稱。啟用監看前，請確保主題的 IAM 已授予 Gmail 發布權限。`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`內部掛鉤`},help:{"v1-piq9k-4v":`內部掛鉤的執行階段設定，適用於從模組路徑載入的內建或自訂事件處理常式。請用於受信任的處理程序內自動化作業，並嚴格限制處理常式的載入範圍。`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`啟用內部掛鉤`},help:{"v1-1wv0289-4c":`啟用內部掛鉤執行環境中的內部掛鉤與已設定項目的處理功能。除非已明確設定內部掛鉤，否則請保持停用。`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`內部掛鉤項目`},help:{"v1-1ovi38l-4o":`已設定的內部掛鉤項目記錄，用於註冊具體的執行階段處理常式與中繼資料。請明確定義項目並進行版本控管，以便稽核正式環境中的行為。`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`內部掛鉤載入器`},help:{"v1-11re5ph-4p":`內部掛鉤載入器設定，控制啟動時搜尋處理常式模組的位置。請限制載入根目錄，以減少意外的模組衝突或遮蔽。`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`內部掛鉤額外目錄`},help:{"v1-1xfdqxg-4c":`除了預設載入路徑之外，用於搜尋內部掛鉤模組的額外目錄。請盡量減少目錄數量並加以管控，以減少意外的模組遮蔽。`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`掛鉤對應`},help:{"v1-frhp3v-5i":`依序比對傳入掛鉤請求的對應規則，用於選擇喚醒或代理程式動作，並可選擇設定傳遞路由。請將較具體的對應放在前面，避免過於寬泛的模式規則攔下所有請求。`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`掛鉤對應動作`},help:{"v1-1r5zt5f-5f":`對應動作類型："wake" 會觸發代理程式喚醒流程，而 "agent" 會直接交由代理程式處理。需要立即執行時請使用 "agent"；偏好由心跳驅動處理時，請使用 "wake"。`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`掛鉤對應代理程式 ID`},help:{"v1-l0uioz-4y":`當動作路由不應使用預設值時，用於執行對應的目標代理程式 ID。使用專用的自動化代理程式，將 webhook 行為與操作人員的互動式工作階段隔離。`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`掛鉤對應允許不安全的外部內容`},help:{"v1-1np9426-57":`設為 true 時，對應內容可在產生的訊息中包含未經充分淨化的外部酬載資料。預設應保持 false，僅針對可信任且轉換邏輯經過審查的來源啟用。`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`掛鉤對應傳送頻道`},help:{"v1-oz7pu5-5s":`覆寫對應輸出的傳送頻道（例如 "last"、"telegram"、"discord"、"slack"、"signal"、"imessage" 或 "msteams"）。請明確指定頻道覆寫值，以免意外跨頻道傳送。`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`掛鉤對應傳送回覆`},help:{"v1-12tbbam-5o":`控制是否將對應執行結果傳回目標頻道，而非靜默處理。對於不應發布使用者可見輸出的背景自動化作業，請停用傳送。`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`掛鉤對應展開鍵`},help:{"v1-1d593op-7e":`指定對應要逐項展開的頂層酬載陣列鍵：每個元素各自派送一個動作，而範本或轉換所取得的酬載，其陣列僅包含目前元素。Gmail 預設組態使用 forEach: messages，因此批次推送會為每封電子郵件分別派送一次執行。`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`掛鉤對應 ID`},help:{"v1-q1t4zw-57":`掛鉤對應項目的選用固定識別碼，用於稽核、疑難排解及針對性更新。請使用唯一 ID，讓日誌與設定差異能明確參照對應項目。`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`掛鉤對應比對`},help:{"v1-6u73k2-5a":`用於彙整路徑、來源等對應比對條件的物件，這些條件會在套用動作路由前進行比對。請明確設定比對條件，避免無關的 webhook 流量觸發自動化作業。`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`掛鉤對應比對路徑`},help:{"v1-1d7dc5j-4k":`掛鉤對應的路徑比對條件，通常會與傳入請求的路徑進行比對。可用來依 webhook 端點路徑群組區分自動化行為。`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`掛鉤對應比對來源`},help:{"v1-177zgy7-52":`掛鉤對應的來源比對條件，通常由受信任的上游中繼資料或介接器邏輯設定。請使用固定的來源識別碼，確保重試時的路由結果一致。`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`掛鉤對應訊息範本`},help:{"v1-ggqszl-5c":`用於將結構化的對應輸入整合為最終訊息內容的範本，訊息會傳送至目標動作路徑。請確保範本產生的結果一致，讓下游剖析與行為維持穩定。`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`掛鉤對應模型覆寫`},help:{"v1-10qyo4j-5e":`選用的模型覆寫設定，適用於自動化作業需要使用不同於代理程式預設模型的情況，用於對應觸發的執行。請審慎使用，讓各次對應執行的行為維持可預測。`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`掛鉤對應名稱`},help:{"v1-zrd9tn-4v":`易於辨識的對應顯示名稱，用於診斷資訊及操作人員使用的設定介面。請使用簡潔且具描述性的名稱，以便在事件檢討時清楚辨識路由意圖。`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`掛鉤對應工作階段金鑰`},help:{"v1-lfnt1n-58":`為透過對應傳送的訊息明確覆寫工作階段金鑰，以控制對話串的連續性。請使用穩定且具範圍限制的金鑰，讓重複事件彼此關聯，而不會混入無關的對話。`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`掛鉤對應工作階段模式`},help:{"v1-1ggtdze-5k":`控制對應工作階段的連續性："isolated" 會啟動全新的執行工作階段，而 "persistent" 會重複使用解析出的 sessionKey。除非整合功能確實需要持久保留上下文，否則請維持 isolated。`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`掛鉤對應文字範本`},help:{"v1-1rg732b-4y":`不需要或不支援豐富格式的負載呈現時，使用的純文字備用範本。可用於為聊天訊息傳送介面提供簡潔且一致的摘要字串。`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`掛鉤對應思考覆寫設定`},help:{"v1-17hq8me-57":`可選的思考強度覆寫設定，用於調整映射觸發執行時的延遲與推理深度。對於高流量掛鉤，請維持低或最低強度，除非明確需要更深入的推理。`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`掛鉤映射逾時（秒）`},help:{"v1-1r44ox2-4i":`映射動作在觸發逾時處理前允許執行的最長時間。對於高流量的 webhook 來源，請設定較嚴格的時間限制，以避免佇列堆積。`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`掛鉤映射傳送目的地`},help:{"v1-1p7928e-55":`當映射回覆應傳送至固定目標時，所選頻道內的目的地識別碼。在正式環境中啟用映射前，請先確認各供應商專用的目的地格式。`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`掛鉤映射轉換`},help:{"v1-14igxpm-5m":`轉換設定區塊，定義在處理映射動作前用於前置處理的模組及匯出項目。請僅使用經過審查的程式碼路徑中的轉換，並確保行為具有確定性，以實現可重複的自動化。`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`掛鉤轉換匯出項目`},help:{"v1-atn8v-4b":`要從轉換模組呼叫的具名匯出項目；省略時會使用模組的預設匯出項目。當單一檔案包含多個轉換處理常式時，請設定此項。`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`掛鉤轉換模組`},help:{"v1-56futq-4v":`從 hooks.transformsDir 載入的轉換模組相對路徑，用於在傳遞前改寫傳入的酬載。請確保模組位於本機、經過審查，且不含路徑遍歷模式。`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`掛鉤對應喚醒模式`},help:{"v1-1dzqfnw-59":`喚醒排程模式："now" 會立即喚醒，而 "next-heartbeat" 會延後至下一個心跳週期。對於可容忍些許延遲的低優先順序自動化作業，請使用延後模式。`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`掛鉤端點路徑`},help:{"v1-1l9ijzv-4u":"Gateway 控制伺服器上掛鉤端點使用的 HTTP 路徑（例如 `/hooks`）。請使用難以猜測的路徑，並搭配權杖驗證，以實現縱深防禦。"}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`掛鉤預設組合`},help:{"v1-dp8m0l-4v":`載入時套用的具名掛鉤預設組合，用於建立標準對應與預設行為。請明確指定使用的預設組合，讓操作人員能稽核哪些自動化作業正在啟用中。`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`掛鉤驗證權杖`},help:{"v1-1ihf6mv-82":`掛鉤入口在執行對應前檢查的共用持有者權杖，用於驗證請求。對於掛鉤入口介面，應將權杖持有者視為完全受信任的呼叫者，而非獨立的非擁有者角色。當網路掛鉤端點可從網際網路存取時，請使用環境變數替換並定期輪替權杖。`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`掛鉤轉換目錄`},help:{"v1-1ayj9p0-4t":`對應中的 transform.module 路徑所參照的掛鉤轉換模組基底目錄。請使用受控的儲存庫目錄，確保動態匯入可供審查且行為可預測。`}},logging:{label:{"v1-rq08xq-7":`日誌`},help:{"v1-11an9pb-5e":`控制日誌記錄行為，包括嚴重程度、輸出目的地、格式及敏感資料遮蔽。請設定足夠嚴格的記錄層級與遮蔽規則，以符合正式環境的需求，同時保留有用的診斷資訊。`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`稽核紀錄簿`},help:{"v1-1lauvy2-6w":`僅包含中繼資料且有保留上限的稽核歷程，供操作人員檢閱。執行與工具記錄預設為啟用；訊息生命週期中繼資料涉及隱私，需另行選擇啟用。背景寫入程序僅盡力寫入，並非保證不遺漏資料的合規封存機制。`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`啟用稽核紀錄簿`},help:{"v1-snknxb-4v":`記錄新的執行、工具及已啟用的訊息稽核事件。預設值：true。變更會立即生效；已接受的寫入會完成，保留的資料列在到期前仍可查詢。`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`執行身分稽核`},help:{"v1-1ucirwv-5b":`保留有限的執行身分歸屬資訊，以供檢視特定執行。預設值：false。需要啟用 logging.audit.enabled，且僅適用於新接受的執行；現有上下文維持不變。`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`訊息稽核範圍`},help:{"v1-1yg4lc3-76":`控制不含內容的訊息生命週期記錄："off"（預設值）、"direct"（僅限已知的直接對話），或 "all"（涵蓋直接對話、群組、頻道及未知對話類型）。需要啟用 logging.audit.enabled。變更會套用至後續的生命週期事件。`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`主控台日誌層級`},help:{"v1-16badbd-5u":`主控台專用的日誌層級門檻："silent"、"fatal"、"error"、"warn"、"info"、"debug" 或 "trace"，用於控制終端機輸出。使用此設定可減少本機主控台的輸出，同時視需要在檔案中保留更詳細的日誌。`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`主控台日誌樣式`},help:{"v1-d7u0iq-3q":`主控台輸出格式樣式："pretty" 或 "json"。機器解析管線請使用 json，以人工閱讀為主的終端機工作流程請使用 pretty。`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`日誌檔案路徑`},help:{"v1-16gaitv-4w":`選用的檔案路徑，用於持久儲存日誌輸出，可搭配或取代主控台日誌。請使用受管理且可寫入的路徑，並讓保留與輪替設定符合您的維運政策。`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`日誌層級`},help:{"v1-1r5yku0-5o":`執行階段日誌記錄器輸出的主要層級門檻："silent"、"fatal"、"error"、"warn"、"info"、"debug" 或 "trace"。正式環境請維持使用 "info" 或 "warn"，僅在調查問題時使用 debug/trace。`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`自訂遮蔽模式`},help:{"v1-1esa6eg-7k":`自訂正規表示式字串會取代日誌／對話記錄輸出的預設字串清單，並補充安全邊界的 UI／工具／診斷規則。內建的表單主體、結構化驗證資訊及 AWS 裸金鑰保護一律適用。使用此設定可遮蔽特定部署的權杖和識別碼。`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`由 OpenClaw 管理的全域 MCP 伺服器定義。嵌入式 OpenClaw 和其他執行階段介接器可使用這些伺服器，無須將其儲存在執行階段專屬的專案設定中。`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP 應用程式`},help:{"v1-amyd91-38":`MCP Apps UI 支援。啟用後，已設定的 MCP 伺服器可為其工具結果提供互動式 HTML 檢視。`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`啟用 MCP Apps`},help:{"v1-ghqy98-3w":`選擇啟用 MCP Apps 轉譯及應用程式與伺服器之間的橋接。除非您信任已設定且提供應用程式 UI 資源的 MCP 伺服器，否則請保持停用。`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`MCP Apps 沙箱來源`},help:{"v1-1sxv3mf-6v":`MCP Apps 的選用專用公開 HTTP(S) 來源。請在反向代理或 TLS 終止器後方使用此來源，並僅將其代理至已設定的 MCP Apps 沙箱連接埠。此來源必須與 Control UI 的來源不同，且不得提供需要驗證的內容。`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`MCP Apps 沙箱連接埠`},help:{"v1-1b8n71l-4p":`MCP Apps 沙箱的專用監聽連接埠。預設為 Gateway 連接埠加一。若其他本機服務或 Gateway 設定檔已佔用該連接埠，請設定未使用的連接埠。`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP 伺服器`},help:{"v1-157ozoz-42":`具名的 MCP 伺服器定義。OpenClaw 會將其儲存在自身的設定中，由執行階段配接器在執行時決定支援哪些傳輸方式。`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP 伺服器驗證`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP 用戶端憑證`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP 用戶端金鑰`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP 用戶端憑證`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP 用戶端金鑰`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP 投影`},help:{"v1-slcmq1-6x":`僅適用於 Codex app-server 執行緒的 OpenClaw 投射中繼資料。不會影響 ACP 工作階段或一般 Codex harness 設定。省略此區塊，即可讓所有 Codex app-server 代理程式使用此伺服器，並採用 Codex 預設的 MCP 核准行為。`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP 代理程式`},help:{"v1-8q98n8-67":`選填的非空 OpenClaw 代理程式 ID 清單，指定哪些代理程式的 Codex app-server 執行緒設定應包含此 MCP 伺服器。空清單、僅含空白或無效的清單會預設拒絕存取；省略時，伺服器會投射至所有 Codex app-server 代理程式。`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCP 工具核准`},help:{"v1-1xql0qr-3d":`同一個伺服器層級 MCP 工具核准模式的 Codex 原生寫法。在 OpenClaw 設定中，請優先使用 defaultToolsApprovalMode。`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCP 工具核准`},help:{"v1-y5vsqq-3s":`此伺服器的選填 Codex MCP 工具核准模式："auto"、"prompt" 或 "approve"。僅適用於您明確信任的 MCP 伺服器。`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP 連線逾時（毫秒）`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP 伺服器已啟用`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth 驗證設定檔`},help:{"v1-fcrb4u-5z":`支援更新的驗證設定檔 ID，用於將目前的 bearer 權杖注入此遠端 MCP 伺服器。設定後，OpenClaw 會在執行階段解析並更新設定檔，且不會將更新所需的資料傳遞至下游。`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`MCP OAuth 用戶端中繼資料 URL`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth 身分`},help:{"v1-1ie6ys7-59":`此伺服器的 OAuth 憑證歸屬。省略此欄位或使用 "shared"，即可使用由操作人員管理的憑證；使用 "per-requester" 則可讓每位已通過驗證的傳送者連結自己的帳戶。`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth 重新導向 URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth 範圍`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`MCP 請求逾時（毫秒）`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS 驗證`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS 驗證`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`MCP 平行工具呼叫`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`MCP 平行工具呼叫`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP 工具選擇`},help:{"v1-10poyzb-4v":`各伺服器的 MCP 工具選擇設定。使用 include 僅公開選定的 MCP 工具名稱，或使用 exclude 隱藏選定的 MCP 工具名稱。項目可使用完整名稱及簡單的 '*' 萬用字元模式。`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`已排除的 MCP 工具`},help:{"v1-ijrc5y-1u":`要從此伺服器隱藏的 MCP 工具完整名稱，或使用 '*' 的簡單萬用字元模式。`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`納入的 MCP 工具`},help:{"v1-89fdfq-3o":`要從此伺服器公開的 MCP 工具完整名稱，或使用 '*' 的簡單萬用字元模式。省略時，所有伺服器工具皆可使用，除非已被排除。`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`MCP 工作階段閒置 TTL（毫秒）`},help:{"v1-j9si74-87":`選用的 OpenClaw 工作階段 MCP 執行環境閒置移除時間，以毫秒為單位。未設定或設為 0 時，執行環境會持續運作，直到工作階段清理或 Gateway 關閉。正值會無條件捨去至整數；有效租用及待處理的取得請求會阻止移除。隸屬於單次執行的執行環境仍會在該次執行結束時終止。`}},memory:{label:{"v1-oopaku-6":`記憶體`},help:{"v1-1wlx40m-13":`內建記憶設定（全域）。`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`記憶引用模式`},help:{"v1-1q6dxr5-4u":`控制回覆中的引用顯示方式："auto" 在有幫助時顯示引用，"on" 一律顯示，"off" 則隱藏。保留 "auto" 可在資訊量與干擾之間取得平衡，作為預設設定。`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`記憶搜尋`},help:{"v1-1ukbud1-25":`對 MEMORY.md 和 memory/*.md 進行向量搜尋（支援個別代理覆寫設定）。`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`記憶搜尋嵌入快取`},help:{"v1-d8h2e4-5b":`將計算完成的區塊嵌入向量快取至 SQLite，以加快重新建立索引及增量更新的速度（預設值：true）。除非正在調查快取正確性或需要盡量減少磁碟使用量，否則請保持啟用。`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`記憶搜尋文件輸入類型`},help:{"v1-1ui33sv-5f":"選用的供應商專屬 `input_type` 值，用於文件與記憶索引的嵌入向量。適用於需要段落或文件標籤、且相容於 OpenAI 的非對稱嵌入向量端點。"}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`啟用記憶搜尋`},help:{"v1-14f11b9-4t":`此代理程式設定檔中記憶搜尋索引與檢索行為的總開關。保持啟用可進行語意回憶；若需要完全無狀態的回應，請停用。`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`記憶搜尋工作階段索引（實驗性）`},help:{"v1-qvhv8z-3i":`將工作階段對話記錄納入記憶搜尋索引。當根層級與個別代理程式的回憶繼承設定不同時，請保留此進階覆寫設定。`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`額外記憶路徑`},help:{"v1-ojqokq-7i":`除了預設記憶檔案外，將額外目錄或 .md 檔案加入記憶索引。項目可以是路徑字串，或包含相對於根目錄之 glob 模式的物件。啟用多模態記憶時，這些路徑下符合條件的影像與音訊檔案也可納入索引。`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`額外記憶路徑`},help:{"v1-b9mbq8-3m":`設定額外的記憶目錄或檔案。相對路徑以代理程式工作區為基準解析；直接指定的檔案項目則按指定檔案建立索引。`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`額外記憶路徑模式`},help:{"v1-j8br1v-4e":`將目錄項目限制為符合此相對於根目錄之 glob 模式的支援檔案，例如 "runbooks/**/*.md"。省略此設定即可遞迴掃描所有支援的檔案。`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`記憶搜尋備援`},help:{"v1-1r6368w-6p":`主要嵌入服務失敗時使用的備援供應商："openai"、"gemini"、"voyage"、"mistral"、"bedrock"、"lmstudio"、"ollama"、"local" 或 "none"。請設定實際的備援供應商，以確保正式環境的可靠性；只有在您希望明確回報失敗時，才使用 "none"。`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`記憶搜尋輸入類型`},help:{"v1-26vbwe-5u":"只有在查詢與文件的嵌入請求應套用相同標籤時，才使用此供應商專屬的選用 `input_type` 值。對於非對稱供應商，請優先使用 queryInputType 和 documentInputType。"}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`本機嵌入模型路徑`},help:{"v1-13ymbnt-5q":"指定本機記憶搜尋使用的本機嵌入模型來源，例如 GGUF 檔案路徑或 `hf:` URI。僅在 provider 為 `local` 時使用，並在大規模重建索引前確認模型相容性。"}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`記憶搜尋模型`},help:{"v1-11pohrl-59":`需要非預設模型時，用來覆寫所選記憶供應商使用的嵌入模型。只有在需要超出供應商預設設定，明確調整檢索品質或成本時，才設定此項目。`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`記憶搜尋多模態`},help:{"v1-1jn02s-9e":'選用的多模態記憶設定，用於為已設定的額外路徑中的影像與音訊檔案建立索引。除非您的嵌入模型明確支援跨模態嵌入，否則請保持關閉；啟用時，請將 `memory.search.fallback` 設為 "none"。建立索引期間，符合條件的檔案會上傳至已設定的遠端嵌入供應商。'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`啟用記憶搜尋多模態功能`},help:{"v1-1dk5d7o-7e":`啟用 extraPaths 中影像與音訊的記憶索引功能。目前需要使用 Gemini embedding-2，預設記憶根目錄仍僅限 Markdown，且會停用記憶搜尋的備援供應商，並將符合條件的二進位內容上傳至已設定的遠端嵌入供應商。`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`記憶搜尋多模態檔案位元組數上限`},help:{"v1-1mmdrvk-5d":`設定每個多模態檔案允許的位元組數上限，超過此上限的檔案會在建立記憶索引時略過。可藉此限制上傳成本與索引延遲，或提高上限以處理高品質的短音訊片段。`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`記憶搜尋多模態類型`},help:{"v1-alp4vh-4l":`選擇要從 extraPaths 建立索引的多模態檔案類型："image"、"audio" 或 "all"。請盡量縮小範圍，以免意外為大量二進位資料建立索引。`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`記憶搜尋輸出維度`},help:{"v1-1f7zu53-93":`覆寫記憶嵌入的輸出向量大小，具體設定依供應商而定。Gemini 模型支援 128-3072 維，建議使用 768、1536 或 3072 維；Titan V2、Cohere V4 和 Nova 等 Bedrock 模型系列各有其允許的大小。變更此設定後將需要重建完整索引，因為儲存的向量維度必須保持一致。`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`記憶搜尋供應商`},help:{"v1-5evseb-71":`選擇用於建立及查詢記憶向量的嵌入後端。預設為 "openai"；若要使用其他後端，請設為 "openai-compatible"、"gemini"、"voyage"、"mistral"、"bedrock"、"deepinfra"、"github-copilot"、"lmstudio"、"ollama" 或 "local"。`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`記憶搜尋結果數量上限`},help:{"v1-13ekath-4x":`在後續重新排序及注入提示之前，搜尋傳回的記憶命中結果數量上限。提高此值可擴大召回範圍，降低則可精簡提示並加快回應。`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`記憶搜尋最低分數`},help:{"v1-1ww231l-4v":`將記憶結果納入最終召回輸出所需的最低相關性分數門檻。提高此值可減少相關性低或含雜訊的相符結果；需要較寬鬆的檢索條件時，則可降低此值。`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`記憶搜尋查詢輸入類型`},help:{"v1-831yrv-4q":"用於查詢時記憶嵌入的選填 `input_type` 值，依供應商而定。適用於需要查詢標籤且相容於 OpenAI 的非對稱嵌入端點。"}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`跨對話記憶`},help:{"v1-k1itm8-7y":`透過受保護的對話記錄召回，使用此代理其他私人對話中的相關脈絡。僅在全域 session.dmScope 未設定或為 "main"，且沒有任何繫結覆寫私訊範圍時，才預設啟用；只要設定了任何私訊隔離，就會預設停用。明確設定的 true 或 false 一律優先。`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`遠端嵌入 API 金鑰`},help:{"v1-nfuuu-62":`提供專用 API 金鑰，用於記憶索引及查詢時產生嵌入向量的遠端呼叫。當記憶嵌入向量需要使用不同於全域預設值或環境變數的憑證時，請使用此設定。`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`遠端嵌入向量基底 URL`},help:{"v1-1ugvqgt-5p":`覆寫嵌入向量 API 端點，例如相容於 OpenAI 的代理伺服器或自訂 Gemini 基底 URL。僅在透過自己的閘道或供應商端點路由請求時使用此設定；否則請保留供應商預設值。`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`啟用遠端批次嵌入向量`},help:{"v1-1fehqi-5x":`在供應商支援時（OpenAI/Gemini），啟用批次 API 來執行嵌入向量作業，以提升大型索引作業的處理量。除非正在偵錯供應商的批次作業失敗問題，或執行的工作負載非常小，否則請保持啟用。`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`遠端嵌入向量標頭`},help:{"v1-1uic0kd-5i":`在遠端嵌入向量請求中加入自訂 HTTP 標頭，並與供應商預設值合併。可用於代理驗證及租戶路由標頭，並請將標頭值限制在必要的最少範圍，以免洩漏敏感中繼資料。`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`記憶搜尋來源`},help:{"v1-btxtzg-57":`選擇要建立索引的來源："memory" 會讀取 MEMORY.md 和記憶檔案，"sessions" 則包含歷史對話記錄。除非需要從先前的聊天記錄中擷取資訊，否則請保留 ["memory"]。`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`記憶搜尋向量索引`},help:{"v1-fbybkj-37":`控制 sqlite-vec 語意索引。當根層級與個別代理程式的向量政策不同時，請保留此進階覆寫設定。`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`記憶搜尋向量擴充套件路徑`},help:{"v1-1hysv5q-58":"覆寫自動偵測到的 sqlite-vec 擴充程式庫路徑（`.dylib`、`.so` 或 `.dll`）。當執行環境無法自動找到 sqlite-vec，或您要固定使用已知可正常運作的建置版本時，請使用此設定。"}},messages:{label:{"v1-1wwzqad-8":`訊息`},help:{"v1-i5k0iw-5k":`訊息基礎架構與跨代理程式預設值。根層級的同層設定負責基礎架構與跨代理程式預設值；agents.defaults 負責代理程式迴圈行為；在支援的情況下，個別代理程式項目可覆寫其中任一類設定。`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`確認收到的表情符號回應`},help:{"v1-1iip0zs-1x":`用於確認收到傳入訊息的表情符號回應（留空即停用）。`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`確認回應範圍`},help:{"v1-1jvdg5n-7s":`何時傳送確認回應（"group-mentions"、"group-all"、"direct"、"all"、"off"、"none"）。"group-mentions" 會對提及代理程式的群組訊息傳送確認回應，無論該群組是否要求提及；"group-all" 會對每則群組訊息傳送確認回應。"off"/"none" 會完全停用確認回應。`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`群組聊天規則`},help:{"v1-chqsvh-4l":`群組訊息處理控制項，包括提及觸發條件與歷史記錄視窗大小。請縮小提及比對模式的範圍，以免群組頻道中的每則訊息都觸發處理。`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`群組歷史記錄上限`},help:{"v1-1mkbpw-9k":`群組工作階段每回合載入作為上下文的先前群組訊息數量上限。使用較高的值可提升對話連貫性，較低的值則可加快回應並降低成本。自動納入提示的歷史訊息上限為 200 則。設為 JSON 整數最大值時，會採用頻道的預設歷史訊息範圍（共用群組歷史為 50 則），而非無限範圍。`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`群組提及模式`},help:{"v1-i7h7qc-6f":`用於偵測群組聊天中明確提及或觸發詞句的安全、不區分大小寫的正規表示式模式。在訊息量大的頻道中，請使用精確的模式以減少誤判；無效或不安全的巢狀重複模式將被忽略。`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`群組未提及的傳入訊息`},help:{"v1-17wef8h-5f":`控制持續啟用的群組聊天中，未提及助理的訊息如何提交。"user_request" 會將其視為使用者請求；"room_event" 則將其作為靜默上下文提交，必須使用訊息工具才能產生可見輸出。`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`群組可見回覆`},help:{"v1-qa4z1s-aa":`覆寫群組或頻道對話中由模型撰寫的來源回覆。未設定全域可見回覆政策時，預設為 "automatic"。"message_tool" 要求一般助理輸出及通用工具媒體必須透過 message(action=send) 傳送；明確由主機端負責的執行階段輸出仍可傳送，但背景聊天室事件除外。"automatic" 則會如同以往發布一般回覆。`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`傳入訊息防抖`},help:{"v1-ebyu5x-4a":`在佇列或回合處理開始前，直接套用於傳入訊息的防抖設定。可針對特定供應商中同一傳送者短時間內連續傳入的訊息進行設定。`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`各頻道的傳入訊息防抖（毫秒）`},help:{"v1-wbz54j-4g":`以提供者 ID 為鍵，個別覆寫各頻道的傳入訊息防抖時間，單位為毫秒。當某些提供者比其他提供者更頻繁地傳送訊息片段時，可使用此設定。`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`傳入訊息防抖時間（毫秒）`},help:{"v1-1616yo2-7w":`用於批次處理同一寄件者快速連續傳入訊息的靜默等待時間（毫秒）。若未設定全域或頻道層級的覆寫值，Telegram 預設為 300 毫秒；其他頻道預設為 0。設為 0 會停用一般連續訊息的批次處理，但 Telegram 仍會重新組合接近長度上限的長訊息片段。`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`傳入訊息佇列`},help:{"v1-hm2o31-48":`工作階段執行期間收到傳入訊息時所採用的佇列策略。可用於調整執行導向、延後跟進、批次處理或中斷行為。`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`各頻道的佇列模式`},help:{"v1-4rf8z8-54":`以提供者 ID（例如 telegram、discord、slack）為鍵，個別覆寫各頻道的佇列模式。當某個頻道的流量模式需要不同於全域預設值的行為時，可使用此設定。`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`佇列容量`},help:{"v1-16ql8c7-4j":`套用捨棄策略前，佇列中可保留的傳入項目數量上限。預設為 20；對訊息繁多的頻道，請設定適當上限，讓記憶體用量維持在可預期的範圍內。`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`各頻道的佇列備援防抖時間（毫秒）`},help:{"v1-4tpyt7-4e":`以提供者 ID 為鍵，個別覆寫各頻道佇列行為的防抖時間。可針對訊息節奏不同的聊天介面，獨立調整突發訊息的處理方式。`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`佇列捨棄策略`},help:{"v1-ydb2rw-6m":`超過佇列容量上限時的捨棄策略。「summarize」會捨棄最舊的項目，但保留精簡摘要；「old」會捨棄最舊的項目，且不保留摘要；「new」則拒絕最新的項目。對於重視上下文的長時間聊天，請使用「summarize」。`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`佇列模式`},help:{"v1-19k7gy1-67":`執行中作業的佇列模式。使用「steer」將提示注入執行中的作業、「followup」稍後執行、「collect」稍後批次處理相容的訊息，或使用「interrupt」在開始執行最新提示前中止執行中的作業。`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`傳出回覆前綴`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`預設用量頁尾模式`},help:{"v1-l3shsx-dv":`每則回覆的預設用量頁尾模式（"off"|"tokens"|"full"），會套用至尚未透過 /usage 選擇模式的工作階段。也接受「on」作為「tokens」的舊版別名。可接受單一模式，或含有「default」備用值的各通道對應表。優先順序：工作階段值 -> 通道設定 -> default -> off；明確透過 /usage 做出的選擇（包括 off）會被保存，並覆寫預設值。使用 /usage reset（別名：inherit、clear、default）可清除工作階段的覆寫設定，並重新繼承此處設定的預設值。`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`狀態表情回應`},help:{"v1-193764l-3s":`生命週期狀態表情回應，會隨著代理的執行進度，更新觸發訊息上的表情符號（排隊中 → 思考中 → 工具 → 完成／錯誤）。`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`啟用狀態表情回應`},help:{"v1-1qnmmnc-7x":`在支援的頻道上啟用生命週期狀態表情回應。當確認表情回應啟用時，Discord 會將未設定視為啟用；Slack、Signal、Telegram 和 WhatsApp 則要求此設定為 true，才會使用生命週期表情回應。Slack 預設使用原生助理討論串狀態來顯示進度。`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`用量頁尾範本`},help:{"v1-1xibc23-47":`自訂 /usage full 頁尾範本，可使用內嵌物件或 JSON 檔案路徑。若範本無效或無法使用，則會回復為內建的用量資訊行。`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`可見回覆`},help:{"v1-7yfwc2-8t":`控制私訊、群組和頻道對話中由模型撰寫的原始回覆。"message_tool" 要求一般助理輸出和通用工具媒體使用 message(action=send)；明確由主機端負責的執行階段輸出仍可傳送，但聊天室背景事件除外。"automatic" 會如同以往發布一般回覆。`}},meta:{label:{"v1-1xpfxac-m":`相容性中繼資料`},help:{"v1-1owqhgn-2w":`保留可供舊版讀取的相容性中繼資料，讓舊版執行檔能拒絕不安全的設定降級。`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`上次修改設定的版本`},help:{"v1-qykpv1-1i":`最近一次寫入此設定的 OpenClaw 版本。`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`設定遷移標記`},help:{"v1-burt8q-1q":`用於已完成設定遷移的有限相容性標記。`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`模型政策允許清單遷移`},help:{"v1-5psop1-1z":`記錄舊版模型對應限制已保留或評估。`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`輔助模型分離遷移`},help:{"v1-vzdfqx-2t":`記錄在分離輔助模型選擇之前，已保留舊版隱含的主要模型。`}},models:{label:{"v1-hzmwb-6":`模型`},help:{"v1-1h1niol-5q":`模型目錄的根設定，涵蓋供應商定義、合併／取代行為，以及選用的 Bedrock 探索整合。在依賴正式環境的容錯移轉路徑之前，請確保供應商定義明確且已通過驗證。`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`模型目錄更新`},help:{"v1-1hess4t-40":`控制內建模型目錄的背景更新。遠端資料列可以更新模型中繼資料，但無法變更供應商端點或標頭。`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`啟用模型目錄更新`},help:{"v1-1fogpjj-3j":`在背景擷取託管模型目錄的更新（預設值：true）。設為 false 可停用所有遠端模型目錄的網路流量。`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`模型目錄更新 URL`},help:{"v1-e02ai2-44":`將託管模型目錄的 URL 覆寫為自行託管的 HTTPS 鏡像站（測試時允許使用 localhost HTTP）。變更會在 Gateway 重新啟動後生效。`}},"models%2Emode":{label:{"v1-wl6vg8-i":`模型目錄模式`},help:{"v1-1ofrnsp-es":`控制供應商目錄的行為："merge" 會保留內建供應商，並以您的自訂供應商設定覆寫對應項目；"replace" 則僅使用您設定的供應商。在 "merge" 模式下，相符的供應商 ID 會保留代理程式 models.json 中非空的 baseUrl 值；而 apiKey 值僅在供應商於目前設定／驗證設定檔情境中不受 SecretRef 管理時才會保留。受 SecretRef 管理的供應商會根據目前的來源標記更新 apiKey，而相符模型的 contextWindow/maxTokens 則採用明確指定項目與隱含項目之間較高的值。`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`模型供應商`},help:{"v1-1y5jg0v-8p":`以供應商 ID 為索引鍵的供應商對應表，包含連線／驗證設定與具體模型定義。內建供應商可透過供應商層級的覆寫設定進行調整；自訂供應商必須包含 baseUrl 和 models。請使用穩定的供應商索引鍵，確保代理程式和工具的參照可跨環境使用。`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`模型供應商執行環境`},help:{"v1-1luy4fb-5o":`此供應商的選用低階代理程式執行環境原則。請使用供應商／模型層級的執行環境原則，而非為整個代理程式固定執行環境；省略或使用預設值時，OpenClaw 會為所選供應商選擇執行環境。`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`模型供應商執行環境 ID`},help:{"v1-1gusd9s-69":`供應商的代理程式執行環境 ID："openclaw"、"auto"、已註冊的外掛程式執行框架 ID（例如 "codex"），或支援的 CLI 後端別名（例如 "claude-cli"）。使用官方端點的 OpenAI 在省略此設定時，預設採用 Codex 執行框架。`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`模型供應商 API 配接器`},help:{"v1-16c28rb-57":`選擇供應商 API 配接器，以控制模型呼叫的請求／回應相容性處理。請使用與上游供應商通訊協定相符的配接器，以避免功能不相容。`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`模型供應商 API 金鑰`},help:{"v1-1p84k96-54":`供應商要求直接以金鑰驗證時，用於 API 金鑰驗證的供應商憑證。請使用密鑰／環境變數替換，並避免將實際金鑰儲存在提交至版本控制的設定檔中。`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`模型供應商驗證模式`},help:{"v1-1l1lwxr-5p":`選擇供應商的驗證方式："api-key" 使用 API 金鑰驗證，"token" 使用持有者權杖驗證，"oauth" 使用 OAuth 憑證，"aws-sdk" 則使用 AWS 憑證解析機制。請依供應商的需求設定。`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`模型供應商 Authorization 標頭`},help:{"v1-1gn3lt3-59":`設為 true 時，即使可使用其他驗證方式，仍會透過 HTTP Authorization 標頭傳送憑證。僅在供應商或 Proxy 明確要求轉送 Authorization 時使用。`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`模型供應商基底 URL`},help:{"v1-1ku88v8-53":`供應商端點的基底 URL，用於處理該供應商項目的模型請求。請使用 HTTPS 端點，並視需要透過設定範本，為不同環境指定各自的 URL。`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`模型供應商標頭`},help:{"v1-chg59u-4x":`合併至供應商請求中的靜態 HTTP 標頭，用於租用戶路由、Proxy 驗證或自訂閘道需求。請謹慎使用，並將敏感的標頭值存放於機密資料中。`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`模型供應商注入 num_ctx（OpenAI 相容）`},help:{"v1-53rmcr-6n":"控制 OpenClaw 是否為使用 OpenAI 相容介面卡（`openai-completions`）設定的 Ollama 供應商注入 `options.num_ctx`。預設為 true。僅在 Proxy 或上游服務拒絕未知的 `options` 酬載欄位時，才設為 false。"}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`模型供應商本機服務`},help:{"v1-19zkcow-4y":`此供應商可選用的隨需啟動本機模型伺服器程序。OpenClaw 會探測 healthUrl，在需要時啟動命令，等待服務就緒後，再傳送模型請求。`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`模型供應商本機服務引數`},help:{"v1-t12wib-27":`傳遞給本機模型伺服器命令的引數清單，不進行 shell 展開。`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`模型供應商本機服務命令`},help:{"v1-1x6hz64-4j":`本機模型伺服器程序的執行檔絕對路徑。請明確指定此路徑，確保供應商的啟動行為可預期，且不依賴 shell 的 PATH 查找。`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`模型供應商本機服務工作目錄`},help:{"v1-fi3xlx-1h":`本機模型伺服器程序的工作目錄。`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`模型供應商本機服務環境`},help:{"v1-1lwb9k1-3k":`本機模型伺服器程序的額外環境變數。疑似機密的值會在設定快照中遮蔽。`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`模型供應商本機服務健康檢查 URL`},help:{"v1-jv7aw-35":`在模型請求前用於探測服務是否就緒的 URL。若省略，OpenClaw 會使用供應商的 baseUrl 並在後方附加 /models。`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`模型供應商本機服務閒置停止`},help:{"v1-1efg054-3z":`最後一個請求完成後，由 OpenClaw 啟動的本機模型伺服器繼續執行的時間，單位為毫秒。設為 0 可讓它持續執行，直到 OpenClaw 結束。`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`模型供應商本機服務就緒逾時`},help:{"v1-4gp0f0-2r":`啟動程序後，等待本機模型伺服器通過就緒探測的最長時間，單位為毫秒。`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`模型供應商最大詞元數`},help:{"v1-fnj50y-38":`當模型項目未設定 maxTokens 時，套用至此供應商旗下模型的預設最大輸出詞元額度。`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`模型供應商模型清單`},help:{"v1-1vbm0gt-63":`為供應商宣告的模型清單，包含識別碼、中繼資料、供應商專屬參數，以及選用的相容性／成本提示。請確保 ID 與供應商目錄中的值完全一致，以便正確解析模型選擇與備援。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`模型執行環境`},help:{"v1-1k70g2n-3g":`此特定模型可選用的底層代理執行環境原則。模型執行環境原則會覆寫供應商的執行環境原則。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`模型執行環境 ID`},help:{"v1-1llzv33-42":`模型代理執行環境 ID："openclaw"、"auto"、已註冊的外掛執行框架 ID（例如 "codex"），或支援的 CLI 後端別名（例如 "claude-cli"）。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`模型媒體輸入`},help:{"v1-wxtj8e-2x":`選填的模型媒體能力中繼資料，供工具選擇保守的預設圖片壓縮設定。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`模型圖片輸入`},help:{"v1-1nviirq-3c":`此模型的選填圖片輸入限制，例如最大邊長、像素數上限及偏好的壓縮邊長。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`模型圖片位元組數上限`},help:{"v1-c2469j-23":`供應商針對此模型接受的編碼後圖片酬載大小上限。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`模型圖片像素數上限`},help:{"v1-9d6yqp-1u":`供應商針對此模型接受的圖片像素數上限。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`模型圖片最大邊長`},help:{"v1-1gbci08-1y":`供應商針對此模型接受的圖片寬度或高度上限。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`模型圖片偏好邊長`},help:{"v1-1u1mpcg-2x":`調整圖片大小時偏好的邊長，以平衡壓縮效果。若不設定，則使用 OpenClaw 的保守預設值。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`模型圖片詞元模式`},help:{"v1-1oy6z7v-1z":`供應商的圖片詞元計算方式："tile"、"detail" 或 "provider"。`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`模型供應商執行階段參數`},help:{"v1-464sgu-4t":`由供應商外掛程式解讀的供應商專屬執行階段參數。請保留供應商文件中記載的鍵，並優先遵循供應商的明確文件，而非臨時採用的通用假設。`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`模型供應商區域`},help:{"v1-yq7rxk-5h":`選用的供應商部署/API 區域，由提供區域端點的供應商解讀。支援的值請參閱供應商文件；若同時設定區域與 baseUrl 覆寫值，通常會優先採用 baseUrl 覆寫值。`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`模型供應商請求覆寫設定`},help:{"v1-1lkxryk-87":`模型供應商請求的選用覆寫設定，包括額外標頭、驗證覆寫、代理路由、TLS 用戶端設定，以及適用於受信任自架端點的選用 allowPrivateNetwork 設定。僅在上游服務或企業網路路徑需要自訂傳輸設定時使用。`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`允許模型供應商請求存取私人網路`},help:{"v1-1nbtcjk-fo":`設為 true 時，允許模型供應商對私有、CGNAT 或類似位址範圍的 HTTP 請求通過供應商 HTTP 擷取防護機制（fetchWithSsrFGuard）。自訂／本機供應商的基底 URL 預設已信任所設定的確切來源，但中繼資料、連結本機及本機用途 NAT64（64:ff9b:1::/48）來源除外；設為 false 可停用此信任。OpenAI Responses WebSocket 會重用 request 的標頭／TLS 設定，但不使用該擷取 SSRF 路徑。只有在端點由操作人員控制、自行託管，且必須存取所設定 baseUrl 來源以外的私有來源時，才應設為 true。`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`模型供應商請求驗證覆寫`},help:{"v1-ucdgnf-1w":`覆寫此供應商的請求驗證行為。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`模型供應商請求驗證標頭名稱`},help:{"v1-1881nqr-1i":`驗證模式為 header 時使用的自訂驗證標頭名稱。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`模型供應商請求驗證模式`},help:{"v1-1lhv8hs-24":`驗證覆寫模式："provider-default"、"authorization-bearer" 或 "header"。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`模型供應商請求驗證標頭前綴`},help:{"v1-1rbm9lz-21":`驗證模式為 header 時，加在 request.auth.value 前方的選用前綴。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`模型供應商請求 Bearer 權杖`},help:{"v1-6rcasw-1l":`驗證模式為 authorization-bearer 時使用的 Bearer 權杖。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`模型供應商請求驗證標頭值`},help:{"v1-1v69ej-1j":`驗證模式為 header 時使用的自訂驗證標頭值。`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`模型供應商請求標頭`},help:{"v1-zj3orj-2i":`完成預設歸屬資訊與驗證設定解析後，合併至供應商請求的額外標頭。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`模型供應商請求代理伺服器`},help:{"v1-md5uj8-4j":`模型供應商請求的選用代理伺服器覆寫設定。使用 "env-proxy" 可遵循環境中的代理伺服器設定，或使用 "explicit-proxy" 透過指定的代理伺服器 URL 路由請求。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`模型供應商請求代理伺服器模式`},help:{"v1-1dx0ozg-29":`模型供應商請求的代理伺服器覆寫模式："env-proxy" 或 "explicit-proxy"。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`模型供應商請求代理伺服器 TLS`},help:{"v1-rdx62w-1v":`連線至已設定的代理伺服器時使用的選用 TLS 設定。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`模型供應商請求代理伺服器 TLS CA`},help:{"v1-11pg2fd-1s":`用於驗證代理伺服器 TLS 憑證鏈的自訂 CA 憑證組合。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`模型供應商請求代理伺服器 TLS 憑證`},help:{"v1-x8nk2q-22":`需要雙向 TLS 時，向代理伺服器提供的用戶端 TLS 憑證。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`模型供應商請求代理 TLS 略過驗證`},help:{"v1-12vjdm9-2j":`略過代理伺服器的 TLS 憑證驗證。僅限在受控的開發環境中使用。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`模型供應商請求代理 TLS 金鑰`},help:{"v1-1skyr56-1w":`與 request.proxy.tls.cert 配對的私密金鑰，用於代理伺服器的雙向 TLS。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`模型供應商請求代理 TLS 密碼片語`},help:{"v1-wjvoxd-1m":`用於解密 request.proxy.tls.key 的選用密碼片語。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`模型供應商請求代理 TLS 伺服器名稱`},help:{"v1-b4oabu-22":`與代理伺服器建立 TLS 連線時使用的選用 SNI／伺服器名稱覆寫值。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`模型供應商請求代理 URL`},help:{"v1-kvbgou-48":`當 request.proxy.mode 為 explicit-proxy 時使用的明確指定代理 URL。URL 中內嵌的認證資訊會視為敏感資料，並在快照中遮蔽。`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`模型供應商請求 TLS`},help:{"v1-16u7v7h-2b":`直接連線至上游模型端點時使用的選用 TLS 設定。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`模型供應商請求 TLS CA`},help:{"v1-ny8y3e-1v":`用於驗證上游 TLS 憑證鏈的自訂 CA 憑證組合。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`模型供應商請求 TLS 憑證`},help:{"v1-1lltmhw-2e":`需要雙向 TLS 時，向上游端點提供的用戶端 TLS 憑證。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`模型供應商請求 TLS 略過驗證`},help:{"v1-1006cuy-2m":`略過上游 TLS 憑證驗證。僅限在受控的開發環境中使用。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`模型供應商請求 TLS 金鑰`},help:{"v1-w2agir-1t":`與 request.tls.cert 配對的私密金鑰，用於上游雙向 TLS。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`模型供應商請求 TLS 通行片語`},help:{"v1-10ds42f-1g":`用於解密 request.tls.key 的選用通行片語。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`模型供應商請求 TLS 伺服器名稱`},help:{"v1-18yt7x9-1y":`建立上游 TLS 連線時使用的選用 SNI／伺服器名稱覆寫值。`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`模型供應商請求逾時`},help:{"v1-t3yn8l-ih":`選用的個別供應商模型請求逾時時間，以秒為單位。供應商層級的請求設定會影響明確設定且隸屬該供應商的模型項目，不會建立隱含模型。對於自訂供應商，請將此設定與供應商的 baseUrl 和 models 一併設定。此設定適用於供應商的 HTTP 擷取作業，包括連線、標頭、本文及整體請求的中止處理，也會將此供應商的 LLM 閒置／串流監控上限提高至隱含的預設值（約 120 秒）以上。對於速度較慢的本機或自行託管模型伺服器，或會在傳輸時無聲緩衝推理 token 的雲端供應商（Gemini 預覽版、工具酬載較大的 Claude/Opus），請使用此設定，而非變更全域代理逾時時間。`}},nodeHost:{label:{"v1-nb8lk1-9":`節點主機`},help:{"v1-8recuz-4z":`節點主機控制設定，用於管理此 Gateway 節點向其他節點或用戶端開放的功能。除非您有意透過節點網路代理本機功能，否則請保留預設值。`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`節點代理執行`},help:{"v1-4uz5ur-2k":`選擇啟用此無介面節點主機上需經核准的原生代理回合。預設為停用。`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`節點 Claude 代理執行`},help:{"v1-g8az5y-2l":`控制此無介面節點主機是否可向 Gateway 宣告支援 Claude CLI 代理回合。`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`啟用節點 Claude 代理執行`},help:{"v1-1ke804l-44":`當本機 claude 執行檔可用時，宣告支援在已配對節點上接續 Claude 工作階段（預設值：false）。執行時仍需取得節點命令執行核准。`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`節點自動更新`},help:{"v1-16xjk4e-5n":`控制已封裝無介面節點主機的獨立執行環境自動更新。每小時檢查一次，並等待所有節點工作完成後才重新啟動；自動重新啟動的間隔至少為 12 小時。`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`啟用節點自動更新`},help:{"v1-1sa0yeg-7w":`為長時間執行的已封裝無介面節點啟用穩定版或測試版自動更新（預設值：true）。設為 false 即可停用。設定 update.checkOnStart=false 或 OPENCLAW_NO_AUTO_UPDATE=1 也會停用此功能；原始碼簽出版本、原生應用程式、私有工作程序、dev 和 extended-stable 不會自動套用更新。`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`節點瀏覽器代理`},help:{"v1-2xrew7-4f":`集中管理瀏覽器代理設定，以透過節點路由提供本機瀏覽器控制功能。僅在遠端節點工作流程需要使用您的本機瀏覽器設定檔時啟用。`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`節點瀏覽器代理允許的設定檔`},help:{"v1-1ew5dkm-8b":`選填的瀏覽器設定檔名稱允許清單，用於指定可透過節點代理路由存取的設定檔。留空可保留預設的完整設定檔功能，包括建立／刪除設定檔的路由。設定後，OpenClaw 會依最小權限原則限制設定檔存取，並封鎖透過代理建立／刪除持久性設定檔的操作。`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`啟用節點瀏覽器代理`},help:{"v1-pa04pd-5b":`透過節點代理路由提供本機瀏覽器控制伺服器，讓遠端用戶端能使用此主機的瀏覽器功能。除非遠端自動化明確依賴此功能，否則請保持停用。`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`節點主機 MCP`},help:{"v1-1mdhrwl-48":`將無介面節點主機啟動並發布至其配對 Gateway 的 MCP 伺服器用作代理工具。變更此區段後，請重新啟動節點主機。`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`節點主機 MCP 伺服器`},help:{"v1-19m002f-3x":`此節點本機上具名的 MCP 伺服器定義。使用與 mcp.servers 相同的伺服器結構；節點主機不支援 OAuth 伺服器。`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`節點主機 Skills`},help:{"v1-v8txza-41":`使用此區段，從無介面節點主機發布安裝於 ~/.openclaw/skills 的技能。變更技能檔案後，請重新啟動節點主機。`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`啟用節點主機 Skills`},help:{"v1-1ggpkqb-36":`連線後掃描並發布節點託管的技能（預設值：true）。設為 false 可停用節點技能發布。`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`節點工作程序執行`},help:{"v1-1w83rox-2p":`選擇啟用完整的 OpenClaw 工作程序工作階段託管，使用由 Gateway 管理的套件組。預設停用。`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`節點工作程序執行容量`},help:{"v1-10nvk8f-3w":`此節點可同時託管的工作程序工作階段數量上限（預設值：可用 CPU 核心數）。必須是 1 至 1024 之間的整數。`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`節點工作程序執行容器映像`},help:{"v1-1oqx50o-5t":`用於容器隔離工作程序的選用 Node 24.16+ 或 26.1+ 映像（預設值："node:24.19.0-slim"）。可視需要使用以摘要鎖定版本、來自私有映像登錄庫或預先載入的映像；缺少的映像會在首次使用時拉取。`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`啟用節點工作程序執行`},help:{"v1-b3t0xp-2t":`允許此已配對節點託管工作階段，且僅使用其 Gateway 安裝的確切套件組（預設值：false）。`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`節點工作程序執行隔離`},help:{"v1-19i6swo-58":`選擇工作程序工作階段的程序邊界："none" 直接在節點主機上執行（預設值）；"container" 需要可正常運作且相容於 Docker 的引擎，且絕不會退回主機執行。`}},plugins:{label:{"v1-10renyj-7":`外掛程式`},help:{"v1-1qbev2k-5c":`外掛程式系統控制項，可用於啟用擴充功能、限制載入範圍、設定項目及追蹤安裝。在正式環境中，請明確設定外掛程式政策，並遵循最小權限原則。`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`外掛允許清單`},help:{"v1-pupwbe-7z":`選用的外掛 ID 允許清單；設定後，只有列出的外掛可以載入。已設定的內建聊天頻道若在設定中明確啟用，仍可啟動其內建外掛。可用於在受控環境中強制只使用核准的擴充功能。`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`外掛封鎖清單`},help:{"v1-4gyt4z-4i":`選用的外掛 ID 封鎖清單，即使允許清單或路徑包含這些外掛，也會予以封鎖。封鎖規則可用於緊急回復及強制封鎖高風險外掛。`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`啟用外掛`},help:{"v1-pnygd7-50":`在啟動及重新載入設定時，全域啟用或停用外掛／擴充功能的載入（預設值：true）。請僅在部署環境需要擴充功能時保持啟用。`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`外掛項目`},help:{"v1-cn74rf-54":`以外掛 ID 為索引鍵的個別外掛設定，包含啟用狀態及外掛專屬的執行階段設定資料。可用於調整特定外掛，而不變更全域載入原則。`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`外掛 API 金鑰`},help:{"v1-ctytg2-53":`選用的 API 金鑰欄位，供支援在項目設定中直接設定金鑰的外掛使用。請使用機密值／環境變數替代，避免將含有真實憑證的設定檔提交至版本控制。`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`外掛設定`},help:{"v1-1he672p-51":`由外掛定義的設定資料，依該外掛本身的結構描述及驗證規則解讀。請僅使用外掛文件中列出的欄位，以免設定遭到忽略或無效。`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`啟用外掛程式`},help:{"v1-12soc0h-9a":`針對特定外掛程式項目的啟用覆寫設定，套用於全域外掛程式原則之上。在預設的混合重新載入模式下，變更會熱重載外掛程式執行環境，供新的代理回合使用，無須重新啟動 Gateway，除非外掛程式要求此設定路徑的變更必須重新啟動。可用於在不同環境中逐步推出外掛程式。`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`外掛程式環境變數`},help:{"v1-p39pu4-52":`個別外掛程式的環境變數對應表，僅注入該外掛程式的執行環境。可用於將供應商憑證的使用範圍限定於單一外掛程式，而非共用全域處理程序環境。`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`外掛程式掛鉤原則`},help:{"v1-1oslnrf-4c":`個別外掛程式的具型別掛鉤原則控制項，用於核心強制執行的安全檢查。可用於限制影響較大的掛鉤類別，而無須停用整個外掛程式。`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`允許對話存取掛鉤`},help:{"v1-xqz31z-7e":"控制此外掛程式是否可透過 `before_agent_run`、`before_model_resolve`、`before_agent_reply`、`llm_input`、`llm_output`、`before_agent_finalize` 和 `agent_end` 等具型別掛鉤讀取原始對話內容。非隨附的外掛程式必須明確選擇啟用。"}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`允許提示注入掛鉤`},help:{"v1-7y6cny-32":"控制此外掛程式是否可透過具型別掛鉤修改提示。設為 false 可封鎖 `before_prompt_build`。"}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`外掛程式掛鉤逾時（毫秒）`},help:{"v1-4ra6b7-74":`此插件具型別掛鉤的預設逾時時間，單位為毫秒，上限為 600000。若未設定，各掛鉤會使用插件宣告的逾時時間或 Gateway 的個別掛鉤原則；並無單一固定的預設值。hooks.timeouts 中的個別掛鉤設定值具有優先權。`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`外掛程式掛鉤逾時覆寫設定`},help:{"v1-yphl9b-5s":`各掛鉤的逾時覆寫設定，以具型別掛鉤名稱為索引鍵，單位為毫秒，上限為 600000。對於 before_prompt_build 或 agent_end 等已知執行緩慢的掛鉤，請針對個別掛鉤覆寫設定，而非提高所有掛鉤的逾時時間。`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`外掛程式 LLM 原則`},help:{"v1-dlca6c-4j":`各外掛程式的 api.runtime.llm.complete 控制設定，用於管理模型與代理覆寫的信任權限。除非外掛程式必須明確控制由主機管理的補全呼叫，否則請保持未設定。`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`允許外掛程式覆寫 LLM 代理`},help:{"v1-k8c08b-4n":`明確允許此外掛程式以非預設代理 ID 請求 api.runtime.llm.complete。除非信任此外掛程式可跨代理存取模型，否則請維持 false。`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`允許外掛程式覆寫 LLM 驗證設定檔`},help:{"v1-9ityw9-4x":`允許此外掛程式為隔離的代理執行階段補全選取非預設驗證設定檔。除非信任此外掛程式可明確指定隔離環境的憑證路由，否則請維持 false。`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`外掛程式 LLM 允許的補全模型`},help:{"v1-1ul08he-54":`每次外掛程式 LLM 補全所允許的目標，以標準格式的 "provider/model" 參照表示，包含由主機解析的預設值與覆寫值。僅在您確實要允許任何模型時使用 "*"。`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`外掛程式 LLM 允許的模型`},help:{"v1-154sk45-47":`受信任外掛程式的 LLM 呼叫所允許的覆寫目標，以標準格式的 "provider/model" 參照表示。僅在您確實要允許覆寫為任何模型時使用 "*"。`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`允許外掛程式覆寫 LLM 模型`},help:{"v1-uw4jmc-47":`明確允許此外掛程式在 api.runtime.llm.complete 中要求覆寫模型。除非信任此外掛程式可決定模型選擇，否則請維持 false。`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`外掛程式子代理程式原則`},help:{"v1-wbf4m1-4d":`各外掛程式的子代理程式執行階段控制設定，用於管理模型覆寫的信任權限與允許清單。除非外掛程式必須明確決定子代理程式的模型選擇，否則請勿設定此項。`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`外掛程式子代理程式允許的模型`},help:{"v1-2pvkow-42":`受信任外掛程式的子代理程式執行作業所允許的覆寫目標，以標準格式的 "provider/model" 參照表示。僅在您確實要允許任何模型時使用 "*"。`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`允許外掛程式覆寫子代理程式模型`},help:{"v1-1r5tzm1-4g":`明確允許此外掛在背景子代理執行時要求覆寫供應商／模型設定。除非信任此外掛能決定模型選擇，否則請保持為 false。`}},"plugins%2Eload":{label:{"v1-9stn89-d":`外掛載入器`},help:{"v1-1myjwbi-52":`外掛載入器設定群組，用於指定搜尋外掛的檔案系統路徑。請明確指定並審查載入路徑，以避免意外載入不受信任的擴充功能。`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`外掛載入路徑`},help:{"v1-o689p1-4z":`載入器除了內建預設位置之外，還會掃描的其他外掛檔案或目錄。請使用專用的擴充功能目錄，避免使用範圍過廣且包含無關可執行內容的路徑。`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`外掛插槽`},help:{"v1-zx6crl-5f":`選擇由哪些外掛佔用記憶等專屬執行階段插槽，確保只有一個外掛提供該功能。請明確指定插槽歸屬，避免多個提供者的功能重疊且行為衝突。`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`上下文引擎外掛`},help:{"v1-4v13iw-2t":`依識別碼選擇啟用的上下文引擎外掛，讓單一外掛負責上下文協調。`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`記憶外掛`},help:{"v1-80ngcl-23":`依識別碼選擇啟用的記憶外掛，或設為 "none" 以停用記憶外掛。`}},presence:{label:{"v1-10fdwo4-8":`上線狀態`}},proxy:{label:{"v1-ji57pa-d":`受管理的代理伺服器`},help:{"v1-vui6bx-58":`由操作人員管理的正向代理路由，適用於 OpenClaw 執行階段的 HTTP、HTTPS、WebSocket 及支援的原始輸出流量路徑。當集中式對外流量控管屬於部署邊界的一部分時，請使用此設定。`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`啟用受管代理`},help:{"v1-1456xdw-49":`明確覆寫受管代理設定。只要有 URL，預設就會啟用路由；設為 false 可忽略已設定或環境中的代理 URL，而不必刪除它們。`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`受管代理回環模式`},help:{"v1-1kaiuh0-3c":`控制受管代理模式啟用時 Gateway 回環控制平面的路由方式："gateway-only"、"proxy" 或 "block"。`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`受管代理 URL`},help:{"v1-p36b5l-3v":`受管正向代理 URL。一般 CONNECT 代理請使用 http://；若與代理端點本身的連線必須使用 TLS，則使用 https://。`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`受管代理 TLS`},help:{"v1-6i0vu-3q":`連線至受管代理端點時使用的 TLS 設定。這些設定適用於代理 TLS，而非 CONNECT 之後的目的地 TLS。`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`受管代理 TLS CA 檔案`},help:{"v1-1ntzjia-2p":`自訂 CA 憑證套件的檔案系統路徑，用於驗證 HTTPS 受管代理端點的憑證。`}},secrets:{label:{"v1-1sihgpy-7":`機密資訊`},help:{"v1-jgn0o9-2l":`機密參照提供者、共用儲存區行為，以及選用的子程序對外連線防護。`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`機密對外連線代理`},help:{"v1-1qfgid-4n":`由 Gateway 管理的回環代理，僅在發出對外請求時替換共用儲存區的機密哨兵標記。此區段的設定於啟動時生效，變更後請重新啟動 Gateway。`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`機密對外連線代理允許的主機`},help:{"v1-9ypodl-6t":`可選用的流量允許清單，適用於請求與 CONNECT 通道。設定後，目的地主機必須列於此清單、個別密鑰的主機綁定或 bypassHosts 中。空清單僅允許已綁定或略過的主機。變更後請重新啟動 Gateway。`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`密鑰對外連線代理略過主機`},help:{"v1-1oiiomv-57":`使用經驗證且不解密流量的 CONNECT 通道之確切主機名稱，適用於採用憑證釘選的用戶端。哨兵值會維持為密文，並導致供應商驗證失敗，而不會暴露明文。`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`啟用密鑰對外連線代理`},help:{"v1-u99b1i-2h":`為 Gateway 託管的代理子程序啟用對外連線密鑰替換功能。預設值：false。`}},session:{label:{"v1-8yh9jr-7":`工作階段`},help:{"v1-j86s32-5d":`用於控制對話記錄行為的全域工作階段路由、重設、傳遞政策與維護設定。除非需要更嚴格的隔離、保留或傳遞限制，否則請保留預設值。`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`私訊工作階段範圍`},help:{"v1-ql362c-5l":`私訊工作階段的範圍設定："main" 維持連續性，而 "per-peer"、"per-channel-peer" 和 "per-account-channel-peer" 則提高隔離程度。共用收件匣或多帳號部署請使用隔離模式。`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`群組工作階段範圍`},help:{"v1-1fdezx2-6i":`群組／頻道工作階段的範圍設定："per-group" 將各聊天室分開，同時讓代理的主要工作階段在背景關注這些聊天室，不受 dmScope 影響；"main" 則將聊天室的上下文合併至主要工作階段，無須另行關注。僅對受信任的聊天室使用 "main"。`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`工作階段身分連結`},help:{"v1-1y5jnsm-5n":`將標準身分對應至帶有供應商前綴的對端 ID，讓同一使用者的不同身分歸入同一個私訊對話串（例如：telegram:123456）。當同一個人出現在多個頻道或帳號中時，可使用此設定。`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`工作階段主鍵`},help:{"v1-18p638h-3q":`接受此設定但會忽略：每個代理程式的主工作階段後綴一律為 "main"。請省略此欄位；全域工作階段範圍則使用 "global"。`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`工作階段維護`},help:{"v1-imr441-66":`工作階段儲存區的自動維護控制項，涵蓋儀表板封存、清理期限、項目數上限、重設封存的保留期限，以及磁碟預算清理。請先使用 warn 模式觀察影響，調整好閾值後再強制執行。`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`儀表板工作階段閒置多久後封存`},help:{"v1-1frdtub-5n":"在儀表板工作階段閒置達指定時間後（例如 `7d`）將其封存，使其仍可存取，又不會擠滿使用中的工作階段清單。設為 `false` 或 `0` 可停用儀表板自動封存。"}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`逐字稿冷儲存`},help:{"v1-1kp9s9h-5s":`將非使用中的逐字稿移至壓縮的 JSONL 封存檔，同時保留工作階段中繼資料。封存檔會成為必要的歷史記錄，必須納入備份。變更無須重新啟動 Gateway 即可套用。`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`閒置多少天後封存`},help:{"v1-zay1q3-5b":`逐字稿閒置達此天數後即予以封存（正整數，預設為 30）。進行中的工作不受影響；變更門檻後，會在背景工作程序下次執行時生效，無須重新啟動 Gateway。`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`自動封存舊逐字稿`},help:{"v1-6p6vmb-5a":`啟用背景對話記錄封存（預設為 false）。背景工作程序每分鐘會檢查是否有符合條件的對話記錄。此明確設定的封存政策獨立於刪除及磁碟空間預算清理機制。`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`工作階段磁碟高水位目標`},help:{"v1-143vh09-7z":`磁碟預算清理後的目標大小（高水位標記）。預設為 maxDiskBytes 的 80%；若磁碟空間有限，可明確設定此值，以更嚴格地回收空間。解析結果為零時會回復為預設值；負值無效。如要停用預算限制，請改用 maxDiskBytes。`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`工作階段最大磁碟預算`},help:{"v1-147lxk3-cj":'每個代理的實體磁碟配額，涵蓋 SQLite 主資料庫／WAL 及納入計算的工作階段目錄產物（例如 `500mb`）。預設為 `10gb`；受保護的資料可能使使用量維持在目標值以上。超出配額時，warn 模式會回報空間壓力，enforce 模式則會依序移除舊的重設／刪除產物、未被參照的歷史記錄，以及因數量上限而建立的封存。手動、依保留期限、透過儀表板、復原及舊版機制建立的封存仍受保護。設為 `false`、`0` 或 `"0"` 即可停用。'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`工作階段項目數上限`},help:{"v1-1w2egrh-7u":`限制未封存的工作階段項目數（預設為 5000）。超出上限且符合條件的持久性對話會連同歷史記錄一起封存；一次性的自動化項目則會移除。現有封存不計入上限。受保護的活躍項目仍會計入，因此儲存區的項目數可能持續超出上限。`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`工作階段維護模式`},help:{"v1-bq39hk-6v":`決定修剪及磁碟空間預算政策是僅回報（"warn"）還是實際執行（"enforce"）。推出期間請維持 "warn"，並在確認閾值安全後切換為 "enforce"。冷儲存有其獨立且需明確設定的 enabled 選項。`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`保留近期工作階段`},help:{"v1-138q5wx-89":"保護在此期間內（例如 `7d`）活躍的互動式工作階段，避免其歷史記錄因保留期限、數量上限或磁碟配額而自動遭到清除。未設定或設為 `false` 時，會維持一般的最舊優先政策。合成模型執行、cron、hook、心跳、ACP 及子代理的資料列仍可依限制進行清理。"}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`工作階段清理期限`},help:{"v1-1xn50w7-76":"封存符合條件的持久對話，並移除存留時間超過此期限的一次性自動化項目（預設為 `30d`；例如 `12h`）。已封存的對話會保留歷史記錄，且可還原；受保護或可路由的對話則維持啟用狀態。"}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`工作階段重設封存保留期限`},help:{"v1-16amrs1-7r":"依存留時間保留已封存的對話記錄（`*.reset.<timestamp>` 和 `*.deleted.<timestamp>`）。預設會保留封存，直到磁碟空間配額要求依最舊優先的順序將其移除；設定期限（例如 `30d`）可啟用依實際經過時間刪除，或設為 `false` 以明確停用。"}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`建立工作階段時通知 Home`},help:{"v1-c4prn5-8b":`建立工作階段時，將系統通知加入所屬代理的 Home 工作階段佇列（預設值：true）。通知包含可用的標題和建立者中繼資料，並會在下一次 Home 回合或心跳時讀取。設為 false 可停用；草稿、無痕工作階段、內部工作階段及排程的 cron 執行均不包含在內。`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`工作階段重設原則`},help:{"v1-1hmt7n3-6r":`定義在沒有適用的類型或頻道專屬覆寫設定時使用的預設重設原則物件。預設不會自動重設工作階段；可透過每日或閒置排程啟用自動重設，而 /new 和 /reset 隨時皆可使用。`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`工作階段每日重設時刻`},help:{"v1-wry8cv-59":`設定每日重設模式的本地時間整點界線（0–23），讓工作階段在可預期的時間切換。請搭配 mode=daily 使用，並配合操作人員預期的時區，讓運作方式更直觀易懂。`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`工作階段重設閒置分鐘數`},help:{"v1-1kzj0id-5e":`設定閒置模式下觸發重設前的無活動時長，也可在每日模式中作為額外的防護條件。使用較大的值可維持連續性，較小的值則適合更常更新的短期對話串。`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`工作階段重設模式`},help:{"v1-e5ie4w-5b":`選擇重設策略："none" 停用自動重設（預設值），"daily" 在設定的時間重設，"idle" 則在閒置一段時間後重設。所有模式皆可使用 /new 和 /reset。`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`依頻道重設工作階段`},help:{"v1-1uxsulx-5h":`以供應商／頻道 ID 為索引鍵，提供個別頻道的重設覆寫設定，以精細控制行為。僅在某個頻道需要不同於類型層級原則的特殊重設行為時使用。`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`依聊天類型重設工作階段`},help:{"v1-ypdr7u-52":`當預設設定不足以滿足需求時，依聊天類型（直接聊天、群組、討論串）覆寫重設行為。當群組或討論串的訊息往來需要與直接訊息不同的重設頻率時，請使用此設定。`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`工作階段重設（直接聊天）`},help:{"v1-fjnlp5-56":`定義直接聊天的重設原則，並取代該類型的基本 session.reset 設定。請使用此設定作為直接訊息的標準覆寫設定，而非舊版 dm 別名。`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`工作階段重設（群組）`},help:{"v1-hl1200-4u":`定義群組聊天工作階段的重設原則，其對話連貫性與雜訊模式和直接訊息不同。若上下文偏移成為問題，可為訊息頻繁的群組設定較短的閒置時限。`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`工作階段重設（討論串）`},help:{"v1-1hgpeke-4w":`定義以討論串為範圍的工作階段重設原則，包括專注於特定頻道討論串的工作流程。當討論串工作階段應比其他聊天類型更快或更慢到期時，請使用此設定。`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`工作階段重設觸發條件`},help:{"v1-rcabsw-5a":`列出訊息觸發條件，當傳入內容符合條件時，便會強制重設工作階段。請僅針對明確的重設用語謹慎設定，以免在正常對話期間意外清除上下文。`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`工作階段範圍`},help:{"v1-axt4ds-5z":`設定基本的工作階段分組策略："per-sender" 依傳送者隔離工作階段，"global" 則在每個頻道上下文中共用一個工作階段。除非刻意需要共用上下文，否則請保留 "per-sender"，以確保多使用者環境中的行為更安全。`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`工作階段傳送政策`},help:{"v1-17qpipb-5l":`透過依據 channel、chatType 和鍵前綴評估的允許／拒絕規則，控制跨工作階段的傳送權限。可用於限制工作階段工具在複雜環境中能夠傳送訊息的目的地。`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`工作階段傳送政策預設動作`},help:{"v1-15plhut-53":`設定沒有任何 sendPolicy 規則符合時的備援動作："allow" 或 "deny"。較簡單的設定可保留 "allow"；若要求每個目的地都必須有明確的允許規則，則選擇 "deny"。`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`工作階段傳送政策規則`},help:{"v1-o217za-5h":'在執行預設動作前依序評估的允許／拒絕規則，例如 `{ action: "deny", match: { channel: "discord" } }`。請將最具體的規則放在最前面，以免廣泛的規則覆蓋例外情況。'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`工作階段傳送規則動作`},help:{"v1-178vm80-54":`定義符合對應比對條件時的規則決策，值為 "allow" 或 "deny"。若要強制執行嚴格界限並明確指定允許的例外情況，請將拒絕規則排在前面。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`工作階段傳送規則比對`},help:{"v1-18qh5qg-5d":`定義選用的規則比對條件，可結合 channel、chatType 和鍵前綴限制。請縮小比對範圍，讓原則意圖清楚易懂，並方便偵錯。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`工作階段傳送規則頻道`},help:{"v1-u5erwx-50":`將規則套用範圍比對至特定頻道／提供者 ID（例如 discord、telegram、slack）。當某個頻道需要獨立於其他頻道允許或拒絕傳送時，請使用此設定。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`工作階段傳送規則聊天類型`},help:{"v1-7cv4f9-4z":`依聊天類型（direct、group、thread）比對規則套用範圍，讓行為隨對話形式而異。當私訊與群組目的地需要不同的安全界限時，請使用此設定。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`工作階段傳送規則鍵前綴`},help:{"v1-ac4dee-5n":`在使用原則的元件完成內部鍵正規化步驟後，比對正規化的工作階段鍵前綴。一般前綴控制可使用此設定；若需要精確比對完整鍵，請優先使用 rawKeyPrefix。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`工作階段傳送規則原始鍵前綴`},help:{"v1-1g9w044-5e":`比對未經正規化的原始工作階段金鑰前綴，以透過完整金鑰精確指定原則的套用對象。當正規化後的 keyPrefix 範圍過廣，而您需要依代理程式前綴或特定傳輸方式精確比對時，請使用此設定。`}},"session%2Esharing":{label:{"v1-ua4axr-l":`工作階段分享模式`},help:{"v1-xbh52d-5a":`控制工作階段擁有者與管理員可選擇的協作模式。未設定的布林值預設為啟用；將某個模式設為 false，即可將其從選擇器中移除，並拒絕新的選取。`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`允許草稿工作階段`},help:{"v1-1lzap27-2p":`允許使用草稿可見性設定，對非擁有者且非管理員的操作人員隱藏工作階段。預設值：true。`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`允許唯讀工作階段`},help:{"v1-upl3nu-21":`允許將工作階段設為對非參與者唯讀。預設值：true。`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`允許建議工作階段`},help:{"v1-4i8owu-4g":`允許使用建議可見性設定。在此階段，此模式採用與唯讀模式相同的存取許可原則；建議佇列將由後續功能設定。預設值：true。`}},"session%2Estore":{label:{"v1-1udxgtl-i":`工作階段儲存路徑`},help:{"v1-hreznz-56":`設定工作階段儲存檔案的路徑，用於在重新啟動後保留工作階段記錄。僅在需要自訂磁碟配置、備份路由或掛載磁碟區儲存空間時，才明確指定路徑。`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`工作階段討論串繫結`},help:{"v1-zbzihu-4s":`支援的各個頻道中，討論串綁定工作階段建立與路由的共用預設值。在此設定全域預設值，僅在行為不同時才針對個別頻道覆寫。`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`討論串建立上下文`},help:{"v1-1set6nw-4c":`建立討論串綁定工作階段時，原生子代理的預設上下文。使用 "fork" 從請求者的對話記錄開始，或使用 "isolated" 建立全新的子代理。預設值："fork"。`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`啟用討論串綁定`},help:{"v1-foomtc-3f":`討論串綁定工作階段建立、路由與傳遞的全域總開關。停用即可在全域關閉討論串綁定。`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`討論串綁定閒置逾時（小時）`},help:{"v1-gffnx3-3h":`各提供者／頻道中，討論串綁定工作階段的預設閒置期限，以小時為單位（0 表示停用閒置到期機制）。預設值：24。`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`討論串綁定最長存續時間（小時）`},help:{"v1-1xfcyhw-39":`各提供者／頻道中，討論串綁定工作階段的選用最長存續時間硬性上限，以小時為單位（0 表示停用硬性上限）。預設值：0。`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`建立討論串綁定工作階段`},help:{"v1-1lqwbdl-46":`控制是否允許透過 sessions_spawn 與 ACP 討論串建立操作來建立討論串綁定工作階段的全域預設開關。預設值：啟用討論串綁定時為 true。`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`允許的技能符號連結目標`},help:{"v1-xzybiq-4t":`技能符號連結的實際目標位於所設定的來源根目錄之外時，允許解析至的受信任實際目標根目錄。請將範圍限縮，例如僅允許同層儲存庫中的技能目錄。`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`額外技能目錄`},help:{"v1-11o7opu-53":`以最低優先順序掃描的額外共用技能根目錄。適用於同層儲存庫或共用技能套件，無須將其複製到 OpenClaw 工作區即可使用。`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`監看 Skills`},help:{"v1-1ckr2l5-5d":`啟用檔案系統監看以偵測技能定義變更，無須完整重新啟動程序即可套用更新。建議在開發工作流程中保持啟用，並在不可變的正式環境映像中停用。`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`技能工坊自主模式`},help:{"v1-1s3kgit-6j":`控制背景學習：「off」僅保留建議提示；「propose」建立待處理提案；「auto」套用已擷取的提案，並透過一般檔案編輯，每週檢視由工坊管理的技能。預設值：「auto」。`}},surfaces:{label:{"v1-exl2ye-g":`介面政策`},help:{"v1-vgtjbs-50":`各介面的訊息政策覆寫設定，以解析後的傳遞介面 ID 為索引鍵。僅在某個已部署介面需要比代理預設值更嚴格的靜默回覆處理方式時使用。`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`介面靜默回覆政策`},help:{"v1-12zgc3n-60":`覆寫單一解析後傳遞介面的靜默回覆政策。未設定的欄位會繼承 agents.defaults.silentReply；請使用範圍明確的介面 ID，避免內部或特定群組的行為影響其他目的地。`}},talk:{label:{"v1-15ukbjj-4":`對話`},help:{"v1-1gx10xa-5g":`對話模式的語音合成設定，涵蓋聲音身分、模型選擇、輸出格式及中斷行為。使用此區段調整面向使用者的語音體驗，同時控制延遲與成本。`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`對話代理程式`},help:{"v1-iee5l9-2b":`若建立對話工作階段時未明確指定代理程式範圍的工作階段金鑰，則由此代理程式負責。`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`對話諮詢快速模式`},help:{"v1-syf3xk-2o":`使用此設定，將對話即時諮詢背後的一般代理程式執行作業的快速模式設為 true 或 false。`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`對話諮詢思考層級`},help:{"v1-1ft5njw-2o":`使用此設定，覆寫對話即時諮詢背後的一般代理程式執行作業的思考層級。`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`對話時遇到使用者說話即中斷`},help:{"v1-8n9q4o-3l":`若設為 true（預設值），當使用者在對話模式中開始說話時，便停止助理的語音。請保持啟用，以便雙方輪流說話。`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`對話使用中的供應商`},help:{"v1-wgnxhg-1g":`對話目前使用的供應商 ID（例如 "acme-speech"）。`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`對話供應商設定`},help:{"v1-oh0yuv-30":`以供應商 ID 為索引鍵的供應商專屬對話設定。遷移期間，請優先使用此設定，而非舊版 talk.* 設定鍵。`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`對話供應商組態`},help:{"v1-36pblg-1r":`對應供應商 ID 的供應商專屬對話組態欄位。`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`對話供應商 API 金鑰`},help:{"v1-1a1p9wp-v":`對話模式使用的供應商 API 金鑰。`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk 即時功能`},help:{"v1-c2re7j-3z":`即時 Talk 的供應商、模型、語音、模式、傳輸方式與推理策略。語音／TTS 供應商設定請保留在 talk.provider 和 talk.providers 中。`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Talk 即時推理`},help:{"v1-opsatw-37":`Talk 推理策略：agent-consult 表示透過 Gateway 取得代理協助，direct-tools 表示呼叫本機工具，none 表示不使用。`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Talk 即時諮詢路由`},help:{"v1-10qjcvk-5f":`當即時供應商略過 openclaw_agent_consult 時，用於最終使用者轉錄文字的 Gateway 轉送備援機制。provider-direct 會保留供應商回覆；force-agent-consult 則透過 OpenClaw 路由。`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Talk 即時指令`},help:{"v1-1jaaj84-5p":`附加至 OpenClaw 內建即時 Talk 提示詞的額外系統指令。可用於設定聲音風格、語氣及其他供應商端的即時行為，同時完整保留 agent-consult 指引。`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Talk 即時模式`},help:{"v1-1u2xui1-1l":`Talk 執行模式：realtime、stt-tts 或 transcription。`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Talk 即時模型`},help:{"v1-amou5a-27":`覆寫瀏覽器或 Gateway 管理的 Talk 工作階段所使用的即時供應商模型 ID。`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Talk 即時前置音訊保留時間（毫秒）`},help:{"v1-1cwg07n-22":`偵測到即時語音活動之前保留的音訊長度，以毫秒為單位。`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Talk 即時供應商`},help:{"v1-wwsmpt-1o":`目前使用的即時語音供應商 ID，例如 openai 或 google。`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk 即時供應商設定`},help:{"v1-ruagcu-1r":`以供應商 ID 為索引鍵的供應商專屬即時語音設定。`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk 即時供應商組態`},help:{"v1-edfpxm-1u":`與供應商 ID 對應的供應商專屬即時語音組態。`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk 即時供應商 API 金鑰`},help:{"v1-1fbmgpx-z":`用於即時 Talk 的供應商 API 金鑰。`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk 即時推理強度`},help:{"v1-157xd3e-2t":`即時 Talk 工作階段的供應商專屬推理強度，例如 minimal、low、medium 或 high。`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk 即時靜音持續時間（毫秒）`},help:{"v1-1grnu06-1y":`提交即時 Talk 使用者發話回合前所需的靜音時間，以毫秒為單位。`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk 即時發話音色`},help:{"v1-1kgb166-2h":`覆寫瀏覽器或 Gateway 管理的 Talk 工作階段所使用的即時供應商發話音色名稱。`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk 即時發話音色 ID`},help:{"v1-1k8w6vk-2f":`覆寫瀏覽器或 Gateway 管理的 Talk 工作階段所使用的即時供應商發話音色 ID。`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk 即時傳輸方式`},help:{"v1-2otjgn-2g":`Talk 位元組／工作階段傳輸方式：webrtc、provider-websocket、gateway-relay 或 managed-room。`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Talk 即時 VAD 閾值`},help:{"v1-nf5l2t-2j":`即時語音活動偵測閾值，範圍從 0（最靈敏）到 1（最不靈敏）。`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Talk 靜音逾時（毫秒）`},help:{"v1-1kim32f-59":`使用者保持靜音多少毫秒後，Talk 模式會完成並傳送目前的轉錄文字。留空可保留平台預設的停頓時間（macOS 和 Android 為 700 毫秒，iOS 為 900 毫秒）。`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Talk 語音地區設定`},help:{"v1-1un3x4l-4c":`用於裝置節點上 Talk 語音辨識及 iOS 系統語音備援的 BCP 47 地區設定識別碼，例如 "ru-RU"。留空可使用各裝置的預設值。`}},telemetry:{label:{"v1-sqprmo-9":`遙測`},help:{"v1-1o5tru3-55":`明確同意在每日更新檢查時附帶匿名功能統計資料。功能統計預設為停用，且絕不包含訊息、憑證或識別碼。`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`功能統計同意時間戳記`},help:{"v1-1t051az-3t":`記錄操作者接受或拒絕匿名功能統計資料的 ISO 時間戳記。可避免設定精靈再次詢問。`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`匿名功能統計`},help:{"v1-1ptrwuq-4r":`在每日更新檢查時分享已啟用的頻道與供應商名稱、外掛數量及近期工作階段數量。預設為停用，且在 DO_NOT_TRACK=1 時一律停用。`}},tools:{label:{"v1-15cdqf0-5":`工具`},help:{"v1-1el54kl-5h":`工具基礎架構與跨代理預設值。根層級的同層設定負責基礎架構與跨代理預設值；agents.defaults 負責代理迴圈行為；代理項目可在支援的情況下覆寫任一類設定。`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`代理間工具存取`},help:{"v1-1ynpa5f-cf":`跨代理工作階段工具呼叫的政策：傳送、列出、歷程記錄、搜尋及狀態讀取（預設：啟用）。使用 allow 限制代理配對；enabled=false 會封鎖一般的跨代理存取。在 tree 或 all 可見性下，仍可存取請求者擁有的原生子代理與 ACP 子工作階段。若要嚴格隔離，請將 tools.sessions.visibility 設為 agent 或 self（tree 仍允許存取請求者擁有的原生子代理／ACP 子工作階段），或使用獨立的 Gateway。`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`代理間目標允許清單`},help:{"v1-1jt2ari-76":`可參與跨代理呼叫的代理 ID 或 * 模式；請求代理與目標代理皆須符合。跨代理存取預設為開啟，省略 allow 或將其留空會允許所有配對。設定明確的清單以限制存取；空白項目會拒絕存取。`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`啟用代理間工具`},help:{"v1-w950oq-ba":`啟用跨代理工作階段工具存取（預設：true）；省略 allow 或將其留空會允許所有代理配對。設為 false 可封鎖一般的跨代理存取；在 tree 或 all 可見性下，仍可存取請求者擁有的原生子代理與 ACP 子工作階段。若要嚴格隔離，請將 tools.sessions.visibility 設為 agent 或 self（tree 仍允許存取請求者擁有的原生子代理／ACP 子工作階段），或使用獨立的 Gateway。`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`工具允許清單`},help:{"v1-1is3eaq-4v":`適用於嚴格環境的絕對工具允許清單，會取代設定檔衍生的預設值。僅在您有意使用經嚴格篩選的部分工具功能時使用。`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`工具允許清單新增項目`},help:{"v1-1xw9zp8-57":`合併至所選工具設定檔及預設政策的額外工具允許清單項目。請保持此清單精簡且明確，讓稽核人員能快速識別刻意設定的政策例外。`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`依提供者設定的工具政策`},help:{"v1-1ecljob-4y":`以通道／提供者 ID 為索引鍵，為各提供者覆寫工具允許／拒絕設定，以針對不同使用介面調整功能。當某個提供者需要比全域工具政策更嚴格的控管時，請使用此設定。`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`程式碼模式`},help:{"v1-1ecc39k-6k":'通用 OpenClaw 程式碼模式。若全域設定中省略此設定，則預設為 `"auto"`；若已明確設定物件但未包含 `enabled`，則維持停用。啟用此模式的代理執行只會向模型提供 `exec` 和 `wait`，並透過目錄橋接存取一般工具。'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`啟用程式碼模式`},help:{"v1-rgstxz-aj":'全域 OpenClaw 程式碼模式啟用設定。若完全未提供全域設定，則預設為 `"auto"`；若已明確設定物件但未包含 `enabled`，則維持停用。`"auto"` 會為偏好目錄的模型啟用此模式，而 `true` 會為具備工具使用能力的執行啟用此模式。代理與模型的啟用覆寫設定具有優先權。已啟用此模式的執行若無法使用執行階段，會以封閉方式失敗，而不會提供完整工具清單。'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`程式碼模式執行器`},help:{"v1-l8nlk2-6x":`JavaScript 執行器："node"（預設）使用 Node vm 執行受信任的程式碼，並非安全沙箱；"quickjs" 使用隨附的 QuickJS WASM 外掛程式，在強化防護的客體環境中執行。工具權限適用於兩者。若所選執行器不存在，將拒絕執行以確保安全。`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`程式碼模式輸出限制`},help:{"v1-1hmij9q-1n":`透過程式碼模式輸出傳回的序列化資料位元組數上限。`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`程式碼模式待處理工具呼叫上限`},help:{"v1-3b5tyd-2i":`程式碼模式虛擬機器在必須暫停並稍後恢復之前，可同時啟動的巢狀工具呼叫數量上限。`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`程式碼模式搜尋結果數量上限`},help:{"v1-1gpue5r-28":`程式碼模式程式可請求的隱藏目錄搜尋結果數量上限。`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`程式碼模式快照大小上限`},help:{"v1-1mmgkqy-1x":`為單一已暫停的 QuickJS 快照保留的序列化位元組數上限。`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`程式碼模式記憶體上限`},help:{"v1-xetora-6n":`QuickJS 客體堆積記憶體上限，或 Node 工作執行緒的 V8 堆積記憶體預算（盡力遵守），以位元組為單位。Node 執行階段的額外負擔及引擎最低記憶體配置量會影響實際可用預算；外部緩衝區與程序 RSS 不計入。這不構成安全性保證。`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`程式碼模式介面`},help:{"v1-dsp2b9-2x":'提供給模型的介面。僅支援 "only"：公開程式碼模式的 `exec` 和 `wait`，並隱藏一般工具。'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`程式碼模式預設搜尋結果數量`},help:{"v1-1io42lu-2m":"程式碼模式中 `catalog.search` 預設傳回的隱藏目錄搜尋結果數量。"}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`程式碼模式快照存留時間`},help:{"v1-1nxfczz-28":"已暫停的 Code Mode 執行作業在到期前，可使用 `wait` 恢復執行的期限。"}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`程式碼模式逾時`},help:{"v1-8csycm-1p":"單次程式碼模式 `exec` 或 `wait` 呼叫的最長時間，單位為毫秒。"}},"tools%2Edeny":{label:{"v1-fwuia7-d":`工具封鎖清單`},help:{"v1-wilr1b-4p":`全域工具封鎖清單，即使設定檔或供應商規則允許，也會封鎖清單中的工具。使用拒絕規則進行緊急封鎖及長期縱深防禦。`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`高權限工具存取`},help:{"v1-ehcm0r-5a":`針對特權命令介面的高權限工具存取控制，這些介面應僅供受信任的傳送者存取。除非操作人員的工作流程明確需要高權限操作，否則請保持停用。`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`高權限工具允許規則`},help:{"v1-1u9bhih-54":`高權限工具的傳送者允許規則，通常以頻道／供應商的身分識別格式作為索引鍵。請使用範圍明確且受限的身分識別，避免非預期使用者觸發高權限命令。`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`啟用高權限工具存取`},help:{"v1-1n8oyal-4l":`在傳送者與政策檢查通過後，啟用高權限工具執行路徑。請在公開／共用頻道中保持停用，並僅在由擁有者操作的受信任情境中啟用。`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec 工具`},help:{"v1-p5piic-56":`Exec 工具的政策群組，涵蓋 Shell 執行主機、安全模式、核准行為及執行階段繫結。請在正式環境中維持保守的預設值，並加強高權限執行路徑的限制。`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`apply_patch 模型允許清單`},help:{"v1-4q5ovf-1x":`選用的模型 ID 允許清單（例如 "gpt-5.4" 或 "openai/gpt-5.4"）。`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`啟用 apply_patch`},help:{"v1-1erkir4-31":`在工具政策允許時，為 OpenAI 和 OpenAI Codex 模型啟用或停用 apply_patch（預設：true）。`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`將 apply_patch 限制於工作區`},help:{"v1-x2z207-3o":`將 apply_patch 路徑限制於工作區目錄內（預設：true）。設為 false 可允許寫入工作區以外的位置（危險）。`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`執行核准後的進行中通知延遲（毫秒）`},help:{"v1-1gwwann-4z":`執行獲准後，顯示進行中通知前的延遲時間（毫秒）。增加此值可減少快速完成的命令造成的閃爍，降低此值則可更快向操作人員提供回饋。`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`執行詢問`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`執行命令醒目標示`},help:{"v1-kyxd4o-4n":`在執行核准提示中，顯示根據剖析器結果產生的命令醒目標示（預設：false）。啟用後會以醒目方式顯示命令文字，但不會變更執行核准政策。`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`持續授權有效期限（天）`},help:{"v1-5uxe2j-6r":`在自動化核准中透過「一律允許」建立的持續授權，其預設有效天數（1-3650）。未設定時，授權會持續有效，直到遭到撤銷或所屬自動化變更為止。授權條件在建立時即固定，因此變更此設定只會影響日後建立的授權。`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`執行目標`},help:{"v1-rno1mf-5q":`選擇 shell 命令的執行目標策略。使用 "auto" 可根據執行環境自動選擇（有 sandbox 可用時使用 sandbox，否則使用 gateway）；若需要固定的執行環境，則可明確指定 sandbox/gateway/node。`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`執行模式`},help:{"v1-1wi6t4l-5q":`標準化的執行原則選擇器。使用 "auto" 可將未符合核准條件的命令交由分類器審查，使用 "ask" 則交由人工審查，使用 "allowlist" 僅允許可確定安全的命令，或使用 "full" 進行受信任的本機操作。`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`執行節點綁定`},help:{"v1-rfnz54-4s":`透過已連線節點委派命令執行時，執行工具所使用的節點綁定設定。僅在需要多節點路由時，才明確指定節點綁定。`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`執行結束時通知`},help:{"v1-1ounlvx-3q":`設為 true（預設值）時，背景執行工作階段結束及節點執行生命週期事件都會將系統事件加入佇列，並請求心跳。`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`執行成功但無輸出時通知`},help:{"v1-1wx4xxd-3d":`設為 true 時，背景執行成功結束但輸出為空的情況，仍會將完成系統事件加入佇列（預設值：false）。`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`執行 PATH 前置目錄`},help:{"v1-s1aimc-1r":`執行命令（gateway/sandbox）時，要加到 PATH 最前面的目錄。`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`執行審查者`},help:{"v1-12y548k-4x":`自動模式在回退至人工核准之前使用的模型驅動執行審查器。若要將執行審查與主要代理程式模型隔離，請在此設定專用的模型覆寫。`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`執行審核器快速模式`},help:{"v1-175bx14-8u":`OpenClaw 核准審核的選用快速模式：true 會在支援的 OpenAI Responses 和 ChatGPT/OAuth 路由上要求優先處理；false 則要求標準處理。省略此設定可保留供應商的預設值。快速模式可能產生較高費用，且須視供應商是否提供而定。此設定不會設定原生 Codex Guardian。`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`執行審查器模型`},help:{"v1-1lltiy5-3i":`執行審查器代理程式的選用供應商／模型覆寫設定。省略此設定即可沿用目標代理程式已設定的主要模型。`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`執行審核器思考`},help:{"v1-yg2gby-6u":`OpenClaw 模型輔助核准審核的選用推理強度：minimal、low、medium、high、xhigh 或 max。省略此設定可保留供應商的預設值。支援的等級會依所選模型進行標準化。此設定不會設定原生 Codex Guardian。`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`執行審查器逾時（毫秒）`},help:{"v1-1o30chi-3w":`執行審查器在模型準備與完成階段各自的逾時時間，單位為毫秒；逾時後會回退至人工核准（預設值：30000）。`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`執行安全二進位檔設定檔`},help:{"v1-4cdcwe-29":`可選用的個別安全二進位檔設定檔（位置參數限制＋允許／拒絕的旗標）。`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`執行安全二進位檔`},help:{"v1-1of1m2s-21":`允許僅使用 stdin 的安全二進位檔在未明確列入允許清單的情況下執行。`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`執行安全二進位檔信任目錄`},help:{"v1-zljbcn-2v":`額外明確指定的信任目錄，用於安全二進位檔路徑檢查（絕不會自動信任 PATH 中的項目）。`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`執行安全性`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`要求核准行內求值`},help:{"v1-jkmgo7-5z":"要求明確核准直譯器的行內求值形式，例如 `python -c`、`node -e`、`ruby -e` 或 `osascript -e`。防止在未提示的情況下沿用允許清單，並將這些形式的「一律允許」降為「每次詢問」。"}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`執行逾時（秒）`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`僅限工作區的檔案系統工具`},help:{"v1-1mhuvka-2s":`將檔案系統工具（read/write/edit/apply_patch）限制在工作區目錄內使用（預設值：false）。`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI 身分與 Git 作者`},help:{"v1-1fl77im-5s":`供代理工具使用的受管理本機 GitHub CLI 設定檔與選用的 Git 作者資訊。省略此物件可保留 Gateway 執行階段使用者的原生帳號與作者資訊；儲存庫的遠端憑證絕不會被覆寫。`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git 作者電子郵件`},help:{"v1-kol5g6-1i":`選用的 Git 作者與提交者電子郵件，僅適用於目前程序。`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git 作者姓名`},help:{"v1-z5bl1f-1h":`選用的 Git 作者與提交者姓名，僅適用於目前程序。`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`GitHub 憑證類型`},help:{"v1-qi3qun-3q":`標記受管理的 OAuth 設定檔，其輪替更新憑證由 Gateway 持有。未指定此欄位的設定檔會使用個人存取權杖。`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub 設定檔版本`},help:{"v1-4lzl0-27":`自動產生且不具可解讀語意的設定檔版本，用於以不可分割的操作切換受管理憑證。`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`啟用連結理解`},help:{"v1-23t2io-59":`啟用自動連結理解前置處理，以便在代理推理前摘要網址內容。保持啟用可提供更豐富的上下文；若需嚴格限制為最低限度的處理，請停用此功能。`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`連結理解的連結數量上限`},help:{"v1-ksxmcv-52":`連結理解期間，每回合展開的連結數量上限。在訊息頻繁的討論串中，使用較低的值可控制延遲與成本；當多個連結的上下文至關重要時，則使用較高的值。`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`連結理解模型`},help:{"v1-6j3mnw-5a":`連結理解任務的偏好模型清單，在支援時依序評估作為備援選項。例行摘要優先使用輕量級模型，僅在需要時使用較大型的模型。`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`連結理解範圍`},help:{"v1-183cwpa-55":`根據對話上下文和訊息類型，控制何時執行連結理解。請保守設定範圍，避免對無需處理連結的訊息進行不必要的擷取。`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`連結理解逾時時間（秒）`},help:{"v1-61v30o-4p":`每個連結理解作業的逾時秒數，超過此時間便會略過尚未解析的連結。請設定合理上限，避免外部網站緩慢或無法連線時造成長時間停滯。`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`工具迴圈偵測`},help:{"v1-1e3rls8-5g":`控制以滾動歷史記錄為基礎的工具迴圈偵測及壓縮後防護。省略此設定可讓滾動偵測保持關閉，並讓壓縮後防護保持開啟。設為 true 可同時啟用兩者，設為 false 則同時停用兩者。`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`音訊理解附件政策`},help:{"v1-1s3t9s5-3o":`選擇要處理哪些符合條件的音訊附件。除非有意轉錄多個附件，否則請僅處理第一個附件。`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`轉錄文字回顯格式`},help:{"v1-glpdzh-3i":`使用 {transcript} 預留位置設定回傳轉錄文字的格式。請保留此預留位置不變，確保傳送內容包含轉錄文字。`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`將轉錄文字回傳至聊天`},help:{"v1-1dedp8c-3r":`在代理處理前，將音訊轉錄文字回傳至來源聊天。當使用者需要確認系統聽到的內容時，請啟用此功能。`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`啟用音訊理解`},help:{"v1-1v0x7te-2m":`啟用音訊理解，將語音留言或音訊片段轉錄為文字，供代理作為上下文使用。`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`音訊理解語言`},help:{"v1-1ruqt97-3z":`提供給音訊轉錄服務供應商的預設語言提示。若已知主要使用的口語語言，且供應商的語言偵測不可靠，請設定此項目。`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`音訊理解位元組數上限`},help:{"v1-1mcckc8-43":`已設定及自動偵測模型的預設音訊輸入大小上限。請將此值設為供應商與網路可接受的最大錄音大小。`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`音訊理解字元數上限`},help:{"v1-eo1dp-43":`已設定及自動偵測模型的預設轉錄文字長度上限。使用較低的值可避免冗長的語音留言增加代理的上下文長度。`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`偏好的音訊理解模型`},help:{"v1-1n5zya1-3c":`優先使用一個標有能力標籤的 tools.media.models 項目進行音訊轉錄，再使用其餘相容的備用項目。`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`音訊理解提示詞`},help:{"v1-1v5jtay-4b":`模型項目未覆寫提示詞時使用的預設音訊轉錄提示詞。若下游工作流程依賴轉錄文字的風格，請保持指令一致。`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`音訊理解範圍`},help:{"v1-1pptfg0-3w":`依頻道、聊天類型或來源鍵限制音訊理解的範圍。若自動轉錄涉及敏感內容或成本高昂，請縮小此範圍。`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`音訊理解逾時時間（秒）`},help:{"v1-n8wc6c-3b":`音訊理解請求的預設逾時時間。處理較長的錄音或使用較慢的本機轉錄模型時，請增加此值。`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`媒體理解並行數`},help:{"v1-13kr9np-58":`每回合中，圖片、音訊及影片任務可同時執行的媒體理解作業數量上限。在資源有限的部署環境中，請降低此值，以免 CPU 或網路負載飽和。`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`圖片理解附件處理原則`},help:{"v1-11hofbw-3e":`選擇要處理哪些符合條件的圖片附件。除非有意進行多圖分析，否則請僅處理第一個附件。`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`啟用圖片理解`},help:{"v1-1b2zw34-50":`啟用影像理解，將附加或引用的影像解讀為文字脈絡。若需要僅處理文字，或想避免影像處理費用，請停用此功能。`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`影像理解位元組數上限`},help:{"v1-jwwpd1-3v":`已設定及自動偵測模型的預設影像輸入大小上限。請依供應商的酬載限制與部署環境的頻寬設定此值。`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`影像理解字元數上限`},help:{"v1-ebnxhk-3q":`預設的影像描述長度上限。若要精簡脈絡，請使用較低的值；若要進行詳細的 OCR 與場景分析，請使用較高的值。`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`影像理解偏好模型`},help:{"v1-1o2uwo6-3c":`進行影像理解時，優先使用 tools.media.models 中帶有能力標籤的某個項目，再使用其餘相容的備援項目。`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`影像理解提示詞`},help:{"v1-1jdcu8b-3u":`當項目未覆寫提示詞時使用的預設影像理解提示詞。若使用端仰賴穩定的描述，請確保此提示詞能產生一致的結果。`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`影像理解範圍`},help:{"v1-tievo1-3s":`依頻道、聊天類型或來源鍵限制影像理解的範圍。在流量較大或不受信任的頻道中，請縮小此範圍以控管處理作業。`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`影像理解逾時時間（秒）`},help:{"v1-1wcm84x-31":`影像理解請求的預設逾時時間。處理大型影像或使用速度較慢的本機視覺模型時，請增加此值。`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`媒體理解共用模型`},help:{"v1-f34u65-47":`媒體理解模型的標準清單。請為每個項目加上 image、audio 或 video 能力標籤，讓各處理流程僅選用相容的備援模型。`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`影片理解附件政策`},help:{"v1-1qm1qrc-3e":`選擇要處理哪些符合條件的影片附件。除非有意分析多部影片，否則請僅處理第一個附件。`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`啟用影片理解`},help:{"v1-1ltx5gl-58":`啟用影片理解，將影片片段摘要為文字，供後續推理與回覆使用。若影片處理不符合政策，或對您的部署環境而言成本過高，請停用此功能。`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`影片理解位元組數上限`},help:{"v1-2mp77v-3v":`已設定及自動偵測模型的預設影片輸入大小上限。請根據供應商的酬載限制與部署環境的頻寬設定此值。`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`影片理解字元數上限`},help:{"v1-1j0x40b-3j":`影片描述的預設長度上限。若要精簡上下文，請使用較低的值；若要取得詳細的場景摘要，請使用較高的值。`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`偏好的影片理解模型`},help:{"v1-1cygq5k-3c":`進行影片理解時，優先使用一個帶有能力標籤的 tools.media.models 項目，再使用其餘相容的備援項目。`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`影片理解提示詞`},help:{"v1-ul2jx4-3r":`項目未覆寫提示詞時使用的預設影片理解提示詞。若使用端依賴穩定的摘要，請確保此提示詞能產生一致的結果。`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`影片理解範圍`},help:{"v1-7gfrx3-3s":`依頻道、聊天類型或來源鍵限制影片理解範圍。在訊息繁忙或不受信任的頻道中，請縮小此範圍以控制處理量。`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`影片理解逾時時間（秒）`},help:{"v1-e8rzsy-33":`影片理解請求的預設逾時時間。處理較長的影片片段或使用較慢的本機分析模型時，請增加此時間。`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`訊息動作允許清單`},help:{"v1-1iceqwa-5c":`訊息工具的全域訊息動作允許清單。僅在整個執行環境都應提供並接受較少的動作時使用；對於公開或在沙箱中執行的代理程式，建議優先使用個別代理程式的允許清單。`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`啟用訊息廣播`},help:{"v1-1ms74z7-14":`啟用廣播動作（預設值：true）。`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`允許跨情境操作（跨提供者）`},help:{"v1-276qxo-2s":`允許跨不同服務供應商傳送訊息（預設值：true）。設為 false 可封鎖跨服務供應商傳送訊息。`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`允許跨情境傳送（同一供應商）`},help:{"v1-1sg4x49-1z":`允許傳送至同一供應商的其他頻道（預設值：true）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`跨情境標記`},help:{"v1-1fg6jrp-1z":`跨情境傳送時加入可見的來源標記（預設值：true）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`跨情境標記前綴`},help:{"v1-eblsru-1p":`跨情境標記的文字前綴（支援「{channel}」）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`跨情境標記後綴`},help:{"v1-1nk0jub-1p":`跨情境標記的文字後綴（支援「{channel}」）。`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`工具設定檔`},help:{"v1-h6k98q-5k":`全域工具設定檔名稱，用於在套用允許／拒絕覆寫設定前，選取預先定義的工具政策基準。使用此設定可讓各代理維持一致的環境配置，並請保持設定檔名稱穩定。`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`沙箱工具政策`},help:{"v1-ea7awo-4k":`適用於沙箱中代理執行作業的工具政策封裝，讓沙箱執行作業具備獨立的能力界限。使用此設定可在沙箱情境中實施更嚴格的安全措施。`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`沙箱工具允許／拒絕政策`},help:{"v1-ub701o-4t":`代理在沙箱執行環境中運作時套用的工具允許／拒絕政策。請將政策權限維持在最低必要範圍，避免沙箱任務擴大為不必要的外部操作。`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`工作階段工具可見範圍`},help:{"v1-1vtq2rh-c5":`控制 sessions_list/sessions_history/sessions_search/sessions_send/session_status 可操作的工作階段。（預設值 "all" = Gateway 上的任何工作階段，包括其他代理程式和使用者的工作階段；"agent" = 目前代理程式 ID 下的任何工作階段；"self" = 僅限目前工作階段；"tree" = 目前工作階段 + 衍生的子代理程式工作階段）。跨代理程式存取預設為開啟，範圍由 tools.agentToAgent 設定；使用較窄的可見範圍可限制存取。`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`子代理程式工具政策`},help:{"v1-1xoug01-4z":`針對衍生子代理程式的工具政策封裝，可在父代理程式預設值的基礎上限制或擴大工具可用範圍。使用此設定可將受委派代理程式的能力限制在任務所需範圍內。`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`子代理程式工具允許／拒絕政策`},help:{"v1-7vxsbf-5d":`套用於衍生子代理程式執行環境的工具允許／拒絕政策。請將此範圍設得比父代理程式更窄。progress_card 等由父代理程式專用的工具一律禁止使用，即使透過 allow/alsoAllow 允許也不例外。`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`代理群組`},help:{"v1-1q96vvs-45":`收集器模式的子代理程式協調。預設為啟用；設為 false 可停用。工具權限仍適用於 agents_wait 和群集衍生選項。`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`群集預設代理程式`},help:{"v1-p4alpg-2m":`群集衍生時未指定 agentId 所使用的預設目標代理程式。子代理程式允許清單仍然適用。`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`啟用群集`},help:{"v1-1nnnrq9-2e":`啟用收集器模式的子代理程式和 agents_wait。預設為開啟；設為 false 可停用。`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`每個群集群組的存活子代理數`},help:{"v1-kfx6qp-1c":`每個群集群組中存活的收集器子代理數量上限。`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`群集並行子代理數`},help:{"v1-1d46jtm-1s":`每個群集群組中同時執行的收集器子代理數量上限。`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`每個群集群組的子代理總數`},help:{"v1-1gc9vl1-1e":`每個群集群組在整個生命週期內可建立的收集器總數上限。`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`群集等待逾時上限`},help:{"v1-bog18y-1g":`agents_wait 接受的逾時時間上限，單位為秒。`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`工具搜尋`},help:{"v1-s0kx04-7y":`精簡大型 OpenClaw、MCP 和用戶端工具目錄。未設定時，OpenClaw 執行環境會自動使用結構化 Tool Search；啟用的 Code Mode 具有優先權，而 Codex 會使用其原生搜尋。設為 false 可停用此功能，設為 true 可使用程式碼橋接，或使用物件形式來選擇模式。`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`工具搜尋程式碼逾時`},help:{"v1-105r499-34":"單次 `tool_search_code` 執行的時間上限，單位為毫秒。執行環境會將數值限制在支援的 1s..60s 範圍內。"}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`啟用工具搜尋`},help:{"v1-1vm3hfr-4h":"啟用工具搜尋。開啟後，OpenClaw 在內嵌執行環境中執行時，會隱藏大型工具目錄，改由 `tool_search_code` 或結構化的搜尋、描述及呼叫工具提供存取。"}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`工具搜尋結果數量上限`},help:{"v1-7du4kh-32":`模型可要求的工具搜尋結果數量上限。執行時會將數值限制在支援的 1..50 範圍內。`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`工具搜尋介面`},help:{"v1-jybcbe-7x":'選擇面向模型的介面："code" 提供 `tool_search_code`；"tools" 提供結構化的搜尋／描述／呼叫備援工具；"directory" 保持有限大小的工具目錄可見，提供一組數量有限、可能用到或必要的結構描述，其餘則透過搜尋／描述／呼叫按需取得。'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`工具搜尋預設結果數量`},help:{"v1-1uchq7t-39":"模型未指定數量上限時，預設傳回的工具搜尋結果數量。執行時會將此值限制為不超過 `maxSearchLimit`。"}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`啟用結構化計畫工具`},help:{"v1-1xgegme-4o":"統一的 `progress_card` 狀態工具，用於父工作階段中持久保存的計畫與敘述性備註。預設啟用；設為 false 即可停用。子代理一律無法使用。"}},"tools%2Eweb":{label:{"v1-3b07wa-9":`網頁工具`},help:{"v1-fpsy5-4y":`網頁工具的原則設定群組，用於調整搜尋／擷取供應商、限制與備援行為。啟用設定應與 API 金鑰可用性及對外網路連線原則保持一致。`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`網頁擷取快取 TTL（分鐘）`},help:{"v1-1hk89qp-17":`web_fetch 結果的快取 TTL，以分鐘為單位。`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`啟用網頁擷取工具`},help:{"v1-yrswld-1f":`啟用 web_fetch 工具（輕量級 HTTP 擷取）。`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`網頁擷取請求標頭`},help:{"v1-16bjkv5-me":"隨直接 web_fetch 請求傳送的額外請求標頭，例如閘道路由或驗證標頭。所有設定值皆視為敏感資訊，並會在對外顯示的設定和偵錯擷取資料中遮蔽。值為純字串，支援 ${VAR} 替換及全域 $${VAR} 字面值跳脫，且會傳送至模型選擇的 URL。項目會在建立請求時驗證，而非在載入設定時驗證，因此無效的名稱或無法傳送的值會被捨棄並記錄，而不會停用此功能；Accept、Accept-Language、User-Agent，以及 Transfer-Encoding 等訊息框架標頭也會被捨棄。若要變更使用者代理，請使用 tools.web.fetch.userAgent。跨來源重新導向僅會保留 guarded-fetch 安全標頭允許清單中的標頭，而變更實際傳送的標頭會使擷取快取分開儲存。"}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`網頁擷取字元數上限`},help:{"v1-12d1fw7-1d":`web_fetch 傳回的字元數上限（超出部分將截斷）。`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`網頁擷取字元數硬性上限`},help:{"v1-cl2mf1-1v":`web_fetch maxChars 的硬性上限（適用於設定及工具呼叫）。`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`網頁擷取重新導向次數上限`},help:{"v1-t6eak9-1h":`web_fetch 允許的重新導向次數上限（預設：3）。`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`網頁擷取下載大小上限（位元組）`},help:{"v1-q6ld9c-10":`截斷前的下載大小上限。`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`網頁擷取提供者`},help:{"v1-6pb3nv-v":`網頁擷取的備援供應商 ID。`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`網頁擷取 Readability 內容擷取`},help:{"v1-19exqzx-2c":`使用 Readability 從 HTML 擷取主要內容（失敗時改用基本 HTML 清理）。`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`網頁擷取 SSRF 政策`},help:{"v1-qtn7zx-3c":`針對 web_fetch 的限定範圍 SSRF 政策覆寫設定。請將範圍維持在最小限度，且僅在已知的區域網路代理環境中啟用。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`網頁擷取允許的主機名稱`},help:{"v1-1j9ctya-35":`允許 web_fetch 存取的確切主機名稱或 IP 位址字面值，包括原本會遭封鎖的目標。請將清單維持在最小限度。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`網頁擷取允許 IPv6 唯一本地位址範圍`},help:{"v1-1eyz55i-3b":`允許 IPv6 唯一本地位址（fc00::/7），以相容於受信任的 fake-IP 代理，例如 sing-box、Clash 或 Surge。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`網頁擷取允許 RFC 2544 基準測試位址範圍`},help:{"v1-u5asdb-2y":`允許 RFC 2544 基準測試範圍的 IP 位址（198.18.0.0/15），以相容於 fake-IP 代理，例如 Clash 或 Surge。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`網頁擷取封鎖的主機名稱`},help:{"v1-1164vvk-66":`每次 web_fetch 重新導向時，會在 DNS 解析及允許規則之前先套用的主機名稱封鎖模式。支援完整主機名稱，以及僅比對子網域的 "*.example.com"；若要封鎖根網域，請另外加入 "example.com"。留空或未設定時，不會新增任何封鎖規則。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`網頁擷取：允許存取私人網路（危險）`},help:{"v1-2s6mv7-3t":`允許 web_fetch 存取私人及內部網路目標。除非此部署環境信任模型所選的 URL，否則請保持停用。`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`網頁擷取逾時（秒）`},help:{"v1-1c3yfr4-16":`web_fetch 請求的逾時時間，以秒為單位。`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`網頁擷取 User-Agent`},help:{"v1-s7pe8j-1e":`覆寫 web_fetch 請求的 User-Agent 標頭。`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`網頁擷取：受信任的環境代理伺服器`},help:{"v1-1ypkqj7-54":`透過環境變數設定的受信任 HTTP(S) 代理伺服器傳送 web_fetch 請求，並由代理伺服器解析 DNS。僅在該代理伺服器由操作人員控制，且會在 DNS 解析後強制執行對外連線政策時啟用。`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`網頁搜尋快取 TTL（分鐘）`},help:{"v1-6trzlf-18":`web_search 結果的快取 TTL，以分鐘為單位。`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`啟用網頁搜尋工具`},help:{"v1-n1cm4y-27":`為符合資格的模型啟用受管理的 web_search，以及選用的 Codex 原生搜尋。`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`網頁搜尋結果數量上限`},help:{"v1-mrw7mi-z":`要傳回的結果數量（1–10）。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Codex 允許的網域`},help:{"v1-1cv4y44-43":`原生 Codex web_search 的網域允許清單。在使用原生託管搜尋的回合中，此清單也會限制受管理的 web_fetch；使用受管理供應商的回合則不受影響。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Codex 搜尋上下文大小`},help:{"v1-antack-1u":`原生 Codex 搜尋的上下文大小提示："low"、"medium" 或 "high"。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`啟用原生 Codex 網頁搜尋`},help:{"v1-ek2jzd-1k":`為支援 Codex 的模型啟用原生 Codex 網頁搜尋。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Codex 網頁搜尋模式`},help:{"v1-1ahyq9f-32":`原生 Codex 網頁搜尋偏好設定："cached"（預設值；不受限制的 Codex 回合會將其解析為 live）或 "live"。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codex 使用者城市`},help:{"v1-1y95orp-1d":`傳送至原生 Codex 網頁搜尋的大致所在城市。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codex 使用者國家`},help:{"v1-1xkm5ms-1g":`傳送至原生 Codex 網頁搜尋的大致所在國家。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codex 使用者地區`},help:{"v1-lhar02-1l":`傳送至原生 Codex 網頁搜尋的大致地區／州。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codex 使用者時區`},help:{"v1-fgv9fh-1h":`傳送至原生 Codex 網頁搜尋的大致時區。`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`網頁搜尋供應商`},help:{"v1-10omglr-1x":`搜尋供應商 ID。若省略，則根據可用的 API 金鑰自動偵測。`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`網頁搜尋逾時時間（秒）`},help:{"v1-i0egvw-17":`web_search 請求的逾時時間，以秒為單位。`}},transcripts:{label:{"v1-1iqk6o8-b":`逐字稿`},help:{"v1-1i0sc09-66":`用於會議筆記、具備錄製功能的代理工具，以及已設定的即時會議自動啟動來源的核心逐字稿擷取設定。會議外掛程式預設會擷取並永久保存筆記；將 enabled 設為 false 即可全域停用。`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`逐字稿自動啟動來源`},help:{"v1-1mzsl79-5s":`從 Gateway 啟動時便自動管理的即時逐字稿來源。每個項目只要存在即為啟用；移除項目即可停用該來源。除非啟用 whenOccupied，否則來源會持續擷取。`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`逐字稿帳號 ID`},help:{"v1-6g2kjj-4b":`選填的供應商帳號或工作區識別碼，適用於需要區分帳號的逐字稿來源。請使用供應商文件所載的帳號 ID 格式。`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`逐字稿頻道 ID`},help:{"v1-1lk9d5o-4u":`即時逐字稿來源在提供者端的頻道 ID，例如 Discord 語音頻道或 Slack 小組通話頻道。啟用自動啟動前，請確認該提供者的 ID 定義。`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord 伺服器 ID`},help:{"v1-fyfgnk-4l":`Discord 語音逐字稿來源的選填 Discord 伺服器 ID。當提供者需要在特定伺服器範圍內查找語音頻道時，請搭配對應的 channelId 設定此值。`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`逐字稿會議 URL`},help:{"v1-1xtt9ci-4f":`選填的會議 URL，適用於透過 URL 而非頻道 ID 加入會議的提供者。請僅使用可信任的會議連結，因為自動啟動可能會加入並擷取該會議的內容。`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`逐字稿來源提供者 ID`},help:{"v1-1uur06p-3s":`逐字稿來源提供者的 ID，例如 Discord 語音或未來的 Slack 小組通話提供者。請使用提供者外掛程式所提供的確切 ID。`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`逐字稿工作階段 ID`},help:{"v1-xyo4x5-5o":`此自動啟動來源的選填固定逐字稿工作階段 ID。當 whenOccupied 為 true 時會忽略此值。除非您需要穩定的每日選取識別碼，且能避免同日 ID 衝突，否則請保持未設定，以使用自動產生的 ID。`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`逐字稿標題`},help:{"v1-ycjnmp-5y":`未來逐字稿擷取作業的選用標題。僅變更標題會讓目前的擷取作業繼續執行，不會重新命名其啟動時採用的標題或已儲存的筆記。其他來源變更仍依正常的重新啟動機制處理。`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`有人在場時擷取逐字稿`},help:{"v1-34jid4-78":`每次來源中有真人在場時，啟動新的逐字稿工作階段，並在最後一位真人離開後停止（產生筆記）。需要能回報在場狀態的提供者，例如 discord-voice。預設值：false（從 Gateway 啟動時起持續擷取）。`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`啟用逐字稿`},help:{"v1-fyqqr0-6d":`啟用可持久儲存的自動會議筆記、transcripts 代理工具，以及已設定的自動啟動來源。預設值：true。設為 false 可停用持久儲存與工具；明確指定的會議轉錄模式仍會保留有限範圍的最新即時內容。`}},tts:{label:{"v1-bmxkk9-e":`文字轉語音`},help:{"v1-1o27tk2-4n":`文字轉語音原則，用於在支援的語音或音訊介面上朗讀代理回覆。除非語音播放是操作人員或使用者工作流程的一部分，否則請保持停用。`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS 角色`},help:{"v1-1r0opcb-29":`預設 TTS 角色 ID。各主機的本機 TTS 角色偏好設定可覆寫此值。`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS 角色`},help:{"v1-19aybhl-2l":`具名的 TTS 角色，定義一致的語音身分及提供者專屬的語音綁定。`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS 角色`},help:{"v1-10s52ah-2l":`單一 TTS 角色。使用提供者專屬的綁定來指定確切的語音、模型及提示範本。`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`TTS 角色供應商綁定`},help:{"v1-993jop-3e":`以語音供應商 ID 為索引鍵的供應商專屬 TTS 角色綁定。這些設定會合併至 tts.providers，並覆寫目前使用中角色的對應設定。`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS 供應商設定`},help:{"v1-1k80nl4-4y":`以語音供應商 ID 為索引鍵的供應商專屬 TTS 設定。請使用此設定，取代內建的供應商專屬頂層索引鍵，讓語音外掛與核心設定結構保持解耦。`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS 供應商組態`},help:{"v1-dwapva-3d":`單一語音供應商 ID 的供應商專屬 TTS 組態。請將欄位的作用範圍限定於該供應商所屬的外掛。`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`TTS 供應商 API 金鑰`},help:{"v1-1m2fj0i-2o":`當語音供應商的外掛需要經過驗證才能存取 TTS 時，該供應商所使用的 API 金鑰。`}},tui:{label:{"v1-c8hus1-b":`終端機介面`},help:{"v1-1fg9vw2-3s":`終端機介面顯示設定。使用此區段設定僅適用於終端機的呈現偏好，不會變更 Gateway 或其他介面的行為。`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`終端機介面頁尾`},help:{"v1-6e12l3-3k":`終端機介面頁尾顯示設定。請精簡呈現選用的脈絡資訊，讓工作階段、模型、目標及 token 資訊保持易讀。`}},ui:{label:{"v1-ye4dff-2":`使用者介面`},help:{"v1-dt1924-42":`用於強調樣式及操作者顯示偏好的介面呈現設定。使用此設定自訂可讀性，不會變更執行階段行為。`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`使用者強調色`},help:{"v1-16klzws-4z":`Control UI 強調色：使用 #RRGGBB 指定自訂顏色，或使用 'theme' 套用所選主題的調色盤。此設定會覆寫 ui.seamColor；清除此設定即可繼承已設定的接縫顏色或主題預設值。`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`強調色`},help:{"v1-14q3r4h-4g":`UI 介面用於強調、徽章及視覺識別提示的主要強調色。請使用在淺色與深色佈景主題中都能保持清晰易讀的高對比色值。`}},update:{label:{"v1-k12u1x-7":`更新`},help:{"v1-11c5k8v-5c":`用於保持 OpenClaw 執行階段版本為最新的更新管道與啟動檢查行為。正式環境請使用保守的管道，較具實驗性的管道僅應用於受控環境。`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`啟用自動更新`},help:{"v1-49xs2h-3c":`為 stable 與 beta 套件安裝啟用背景自動更新；extended-stable 永遠不會自動套用更新（預設值：false）。`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`更新管道`},help:{"v1-lqtdvf-5b":`git + npm 安裝的更新管道（"stable"、"extended-stable"、"beta" 或 "dev"）。extended-stable 僅支援套件安裝：安裝只能在前景執行，並可選擇在啟動時顯示唯讀提示。`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`啟動時檢查更新`},help:{"v1-qy3q9g-5v":`在 Gateway 啟動時檢查更新，包括唯讀的 extended-stable 提示（預設值：true）。設為 false 可停用 Gateway 和無介面節點的自動更新檢查、更新套用及匿名更新通知請求。`}},voicewake:{label:{"v1-txt1wb-a":`語音喚醒`}},web:{label:{"v1-1ae9z56-b":`網頁頻道`}},wizard:{label:{"v1-28jonk-h":`設定偏好`},help:{"v1-14jh6rm-3b":`由使用者管理的設定偏好。由機器管理的精靈歷程記錄與確認狀態儲存於共用狀態資料庫中。`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`設定探索存取權`},help:{"v1-1nqxt0w-38":`引導式設定的探索同意模式："full" 會自動掃描而不詢問，"guarded" 則會在檢查本機應用程式前詢問。`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`設定應用程式推薦`},help:{"v1-ub8uoi-30":`控制引導式設定是否可使用已安裝應用程式的標籤，推薦相關外掛程式與技能。`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`精靈上次執行時間戳記`},help:{"v1-1y0fbk-1k":`上次成功儲存精靈執行結果的時間戳記。`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`精靈上次執行命令`},help:{"v1-x2pfkk-15":`啟動上次精靈執行的命令。`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`精靈上次執行的提交版本`},help:{"v1-h0jkmt-1i":`上次執行開發版精靈時使用的原始碼提交版本。`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`精靈上次執行模式`},help:{"v1-16508qy-1r":`上次執行精靈時，設定目標為 "local" 還是 "remote"。`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`精靈上次執行版本`},help:{"v1-1tr4z9d-19":`上次執行精靈時使用的 OpenClaw 版本。`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`精靈安全確認時間戳記`},help:{"v1-86i182-2a":`設定過程中完成安全確認的時間戳記，會與目標設定一併儲存。`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`工作樹加速`},help:{"v1-9es3gc-4r":`在支援的情況下，對新建的受管理工作樹使用檔案系統加速（預設值：true）。設為 false 可使用一般的 Git 簽出與檔案複製。僅適用於新建的工作樹。`}},worktreeRoot:{label:{"v1-bqutg0-d":`工作樹根目錄`},help:{"v1-1tgti9j-5d":`新建受管理工作樹的全域目錄。請使用絕對路徑，或以 ~ 表示家目錄；預設為 <state-dir>/worktrees。變更此設定時，現有工作樹會保留已記錄的路徑。`}}}}})))()}export{t as n,n as t};